// Multilevel Master Writing — mavzular, mashqlar va topshiriqlar
window.WRITING={"units":[{"task":1,"no":1,"title":"Basics of letters","uz":"Xatlar haqida umumiy tushuncha","pages":"4–7","blocks":[{"t":"p","x":"Multilevel imtihonining **Writing** bo'limidagi 1-topshiriqda sizga bir **vaziyat** beriladi va shu vaziyat bo'yicha uchta **tayanch savol** (bullet points) asosida xat yozishingiz so'raladi. Topshiriq quyidagi ko'rinishda bo'ladi:"},{"t":"task","label":"Namuna topshiriq","situation":"You live in a room in college. There is a problem in the bathroom that you would like repaired.","to":"Write a letter to the accommodation officer at the college. In the letter:","bullets":["describe the problem","explain how the situation affects you","suggest a time when a repairman could visit."]},{"t":"list","items":["**Situation** — vaziyat: nima bo'lgani.","**Instruction** — kimga xat yozishingiz.","**Bullet points** — xatda albatta javob berilishi kerak bo'lgan uchta savol."]},{"t":"note","x":"Xat **kamida 150 so'zdan** iborat bo'lishi kerak. Uni yozishga taxminan **20 daqiqa** ajratish tavsiya qilinadi."},{"t":"h","x":"Xatlarning uslubi bo'yicha turlari"},{"t":"list","items":["**Rasmiy (formal)** — notanish yoki mansabdor shaxslarga yoziladi (shifokor, mehmonxona menejeri, kompaniya).","**Norasmiy (informal)** — yaqin do'stingiz va qarindoshlaringizga yoziladi.","**Yarim rasmiy (semi-formal)** — yaqindan tanish bo'lmagan, lekin taniydigan insonlarga yoziladi (qo'shnilar, o'qituvchingiz, do'stingizning ota-onasi)."]},{"t":"p","x":"Imtihonda asosan rasmiy, ba'zida norasmiy va yarim rasmiy xatlar so'raladi."},{"t":"h","x":"Xatlarning maqsadi bo'yicha turlari"},{"t":"p","x":"Xatlar turli maqsadlarda yoziladi. Kitobda ular 6 guruhga ajratilgan:"},{"t":"table","head":["Ingliz tilida","O'zbekcha"],"rows":[["Request letter","So'rov xati"],["Complaint letter","Shikoyat xati"],["Thank you letter","Minnatdorchilik va taklif xati"],["Apology letter","Uzr so'rash xati"],["Job application and resignation letter","Ishga topshirish yoki ishdan bo'shash xati"],["Condolence letter","Ta'ziya bildirish xati"]]},{"t":"ex","no":"1.1","q":"To'g'ri javobni belgilang.","kind":"mcq","items":[{"q":"Multilevel imtihonida xat nechta so'zdan iborat bo'lishi kerak?","o":["150 so'zdan kamroq","150 so'zdan ko'proq","So'zlar soni ahamiyatsiz"],"a":1,"why":"Xat kamida 150 so'z bo'lishi kerak."},{"q":"Imtihonda xat yozish uchun qancha vaqt ajratish tavsiya qilinadi?","o":["1 soat","40 daqiqa","20 daqiqa"],"a":2,"why":"Xatga ~20 daqiqa, qolgan vaqt inshoga."},{"q":"Sizga restorandagi ovqat yoqmadi. Restoran xo'jayiniga qanday uslubdagi xat yozasiz?","o":["Rasmiy","Norasmiy","Yarim rasmiy"],"a":0,"why":"Restoran xo'jayini — notanish, mansabdor shaxs: rasmiy xat."}]},{"t":"ex","no":"1.2","q":"Quyidagi holatlarda ma'noviy jihatdan qaysi turdagi xat yoziladi?","kind":"match","opts":[{"k":"A","x":"So'rov xati"},{"k":"B","x":"Shikoyat xati"},{"k":"C","x":"Minnatdorchilik va taklif xati"},{"k":"D","x":"Uzr so'rash xati"},{"k":"E","x":"Ishga topshirish yoki ishdan bo'shash xati"},{"k":"F","x":"Ta'ziya bildirish xati"}],"items":[{"q":"Siz do'stingizdan kitob qarzga oldingiz, lekin vaqtida qaytarib bera olmadingiz. Afsusda ekaningizni bildirib xat yozmoqchisiz.","a":"D"},{"q":"Bog'ingizda olchalar pishdi va ularni terib olish uchun do'stingizdan yordam so'rab xat yozmoqchisiz.","a":"A"},{"q":"O'quv markazda tayyorlanib, universitetga a'lo baholar bilan kirdingiz. O'qituvchingizga rahmat aytib xat yozmoqchisiz.","a":"C"},{"q":"O'g'lingizga sotib olgan kompyuteringizni internetga ulashda muammolar bo'lyapti. Do'kon menejeriga arz qilmoqchisiz.","a":"B"},{"q":"Yaqin do'stingiz avtohalokatga uchrab, qattiq jarohat oldi. Uning ota-onasiga hamdardlik bildirib xat yozmoqchisiz.","a":"F"},{"q":"Internetda supermarketga sotuvchilarni ishga qabul qilish bo'yicha e'lonni o'qidingiz. Supermarket xo'jayiniga xat yozmoqchisiz.","a":"E"}]},{"t":"ex","no":"1.3","q":"Quyidagi xat parchalari ma'noviy jihatdan qaysi turdagi xatga mos keladi?","kind":"match","opts":[{"k":"A","x":"I really hope you can come to my party. I'm sure we'll have a wonderful time."},{"k":"B","x":"I'm writing to ask you what you think I should do about Robert. I'd really like your advice as he's been…"},{"k":"C","x":"I'm having a fantastic time on holiday. I went sailing yesterday and I'm going to take part in a diving competition this afternoon. I can't wait!"},{"k":"D","x":"I received your leaflet in the post. I am very interested in the course and would be grateful if you could give me some more information."},{"k":"E","x":"I have enclosed my CV. I would be grateful if you could consider my application. I look forward to hearing from you."},{"k":"F","x":"I am writing to complain about the dishwasher which I purchased from your company last Monday."}],"items":[{"q":"letter of application","a":"E"},{"q":"letter giving news","a":"C"},{"q":"letter of invitation","a":"A"},{"q":"letter asking information","a":"D"},{"q":"letter of complaint","a":"F"},{"q":"letter asking for advice","a":"B"}]}],"writes":0},{"task":1,"no":2,"title":"The structure of letters","uz":"Xatlarning tuzilishi","pages":"7–9","blocks":[{"t":"p","x":"Multilevel imtihonidagi xat asosan quyidagi **7 qism**dan iborat bo'ladi:"},{"t":"list","ordered":true,"items":["**Salomlashish (Greeting)** — _Dear Sir or Madam,_ / _Dear Aunt Halima,_ / _Dear Mrs Salima,_","**Maqsad (Purpose)** — yangi paragrafda xat yozishdan maqsadingizni 1–2 gap bilan tushuntirasiz: _I am writing in response to your advertisement…_, _I am writing to express my strong dissatisfaction with…_, _I would greatly appreciate it if you could provide me with some information regarding…_","**Birinchi paragraf** — 1-tayanch savolga aniq ma'lumotlar bilan javob.","**Ikkinchi paragraf** — 2-tayanch savolga aniq ma'lumotlar bilan javob.","**Uchinchi paragraf** — 3-tayanch savolga aniq ma'lumotlar bilan javob.","**Yakunlovchi gap (Closing sentence)** — _I look forward to receiving your response._ / _Thank you for taking the time to read this letter._","**Xayrlashuv (Sign-off)** — xat turiga mos: _Yours faithfully_ + to'liq ism (rasmiy), _Lots of love_ + ism (norasmiy)."]},{"t":"model","title":"Xatning umumiy ko'rinishi","x":"Dear …,                      ← Greeting\n\nI am writing to …           ← Purpose\n\nParagraph 1                  ← 1-bullet pointga javob\n\nParagraph 2                  ← 2-bullet pointga javob\n\nParagraph 3                  ← 3-bullet pointga javob\n\nI look forward to …          ← Closing sentence\n\nYours faithfully,\nFull Name                    ← Name"},{"t":"ex","no":"2.1","q":"Topshiriqni diqqat bilan o'qing va har bir gap xatning qaysi qismiga tegishli ekanini belgilang.","kind":"match","intro":"**Vaziyat:** One of your friends recently had a birthday celebration, but you missed it and you forgot to tell your friend that you couldn't attend. **Topshiriq:** Write a letter to your friend. In your letter: apologise for missing the birthday celebration; explain why you missed it and why you didn't tell your friend; say what you would like to do to show that you are sorry.","opts":[{"k":"A","x":"Salomlashish"},{"k":"B","x":"Maqsad"},{"k":"C","x":"1-paragraf"},{"k":"D","x":"2-paragraf"},{"k":"E","x":"3-paragraf"},{"k":"F","x":"Yakunlovchi gap"},{"k":"G","x":"Xayrlashuv"}],"items":[{"q":"The truth is that I've been under a lot of stress at work recently.","a":"D","why":"Nega kelmaganini tushuntiradi — 2-tayanch savol (kitobda namuna sifatida berilgan)."},{"q":"By way of an apology, I've bought tickets for us both to go to the football next Saturday.","a":"E","why":"Uzr sifatida nima qilmoqchi — 3-tayanch savol."},{"q":"Dear Mark,","a":"A"},{"q":"Speak to you soon,","a":"G","why":"Kitob kalitiga ko'ra — xayrlashuv qismi."},{"q":"I hope you're well and that you had a fantastic time on your birthday.","a":"C","why":"Kitob kalitiga ko'ra — 1-paragrafning boshlanishi (uzr so'rashga olib kiradi)."},{"q":"I feel terrible that I haven't found the time to contact you until now.","a":"C","why":"Uzr so'rash — 1-tayanch savol."},{"q":"Best of love,","a":"G"}]},{"t":"ex","no":"2.2","q":"Quyidagi mulohazalar to'g'rimi yoki noto'g'ri?","kind":"tf","items":[{"q":"Xat turiga mos ravishda xayrlashish ikkinchi paragrafdan keyin yoziladi.","a":1,"why":"Xayrlashuv eng oxirida — uchinchi paragraf va yakunlovchi gapdan keyin."},{"q":"Salomlashgandan keyin xatni yozishdan asosiy maqsad batafsil yoziladi.","a":0,"why":"Kitob kalitiga ko'ra to'g'ri: salomlashishdan keyin maqsad yoziladi (lekin u qisqa — 1–2 gap)."},{"q":"Har bir tayanch savol uchun to'liq javob berish talab qilinmaydi.","a":1,"why":"Har bir tayanch savolga alohida paragrafda to'liq javob berilishi shart."},{"q":"Xayrlashishdan oldin xatni umumiy xulosalovchi yakuniy gap yoziladi.","a":0},{"q":"Birinchi paragrafni yozishdan oldin xatning asosiy maqsadi yozilishi kerak.","a":0}]}],"writes":0},{"task":1,"no":3,"title":"Tone","uz":"Uslub: rasmiy va norasmiy xatlar","pages":"10–20","blocks":[{"t":"p","x":"**Uslub (tone)** — siz yozayotgan holat va insondan kelib chiqadigan yozish ohangi. Ingliz tilida xatlar ikki uslubda yoziladi: **rasmiy (formal)** va **norasmiy (informal)**."},{"t":"list","items":["**Rasmiy uslub** — mansabdor shaxslar yoki siz tanimaydigan odamlarga. Qabul qiluvchiga hurmat saqlanadi.","**Norasmiy uslub** — yaqin tanigan insonlarga: oila a'zolari va do'stlar. Jiddiy bo'lmagan, hazil aralash, kundalik so'zlashuv ohangida yoziladi."]},{"t":"note","x":"Odatda topshiriq matnida **friend** so'zi ishlatilgan bo'lsa — norasmiy xat, ishlatilmagan bo'lsa — rasmiy xat yoziladi. **Yarim rasmiy** xatlar (qo'shni, o'qituvchi, hamkasb) uchun asosan rasmiy uslubdan foydalangan yaxshi."},{"t":"h","x":"Rasmiy va norasmiy xatlarning farqlari"},{"t":"h3","x":"1. Boshlash va yakunlash"},{"t":"table","head":["Xat turi","Boshlash","Yakunlash"],"rows":[["Rasmiy, ismini bilmaysiz","Dear Sir or Madam,","Yours faithfully,"],["Rasmiy, ismini bilasiz","Dear Mr Utkir,","Yours sincerely,"],["Norasmiy","Dear Dildora, / Hi Mom,","See you soon, / Best wishes, / Lots of love,"]]},{"t":"h3","x":"2. Qisqartmalar"},{"t":"p","x":"Rasmiy uslubda so'zlarni qisqartirib yozish mumkin emas: _I am / I do not / He would_. Norasmiy uslubda qisqartmalar mumkin: _I'm / I don't / He'd_."},{"t":"h3","x":"3. Kishilik olmoshlari (I, you, we)"},{"t":"p","x":"Rasmiy xatlarda imkon bo'lsa kishilik olmoshlaridan kamroq foydalaning.\nNorasmiy: _You would find it difficult to get a job without proper qualifications._\nRasmiy: _Finding a job without proper qualifications would be rather difficult._"},{"t":"h3","x":"4. Hol-ahvol so'rash"},{"t":"p","x":"Norasmiy xat sog'lik va kayfiyat so'rash bilan boshlanishi mumkin (_Hi! How are you? I thought I'd write and let you know that…_). Rasmiy xatda bunday qilinmaydi."},{"t":"h3","x":"5. So'z tanlash"},{"t":"table","head":["Formal","Informal","Tarjima"],"rows":[["inform me","let me know","menga xabar bering"],["cancel","drop","bekor qilmoq"],["contact","get in touch","aloqaga chiqmoq"],["obtain","get","olmoq"],["apologize","say sorry","uzr so'ramoq"],["postpone","delay","kechiktirmoq"],["request","ask for","so'ramoq"],["compensate","make up","zararni qoplamoq"],["establish","set up","qurmoq, tashkil etmoq"],["handle","deal with","hal qilmoq"],["investigate","check up on","tekshirmoq"],["tolerate","put up with","chidamoq"],["increase","go up","ko'paymoq"],["children","kids","bolalar"],["many / much","heaps of","ko'p"],["inquire","ask","so'ramoq"],["enclosed","attached","ilova qilingan"],["refrain from","avoid","tiyilmoq"],["utilize","use","ishlatmoq"],["regarding","about","haqida"],["verify","check","tekshirmoq"],["commence","start","boshlamoq"],["terminate","end","tugatmoq"],["endeavour","try","harakat qilmoq"],["approximately","about","taxminan"],["appreciate","thanks","minnatdor bo'lmoq"],["require","need","kerak bo'lmoq"],["oppose","go against","qarshi chiqmoq"],["consider","think about","o'ylab ko'rmoq"],["appear","seem","tuyulmoq"],["release","free","ozod qilmoq"],["permit","let","ruxsat bermoq"],["call","ring up","qo'ng'iroq qilmoq"],["demonstrate","show","ko'rsatmoq"],["retain","keep","saqlamoq"],["arrive","show up","yetib kelmoq"],["acceptable","OK","ma'qul"],["as soon as possible","ASAP","imkon qadar tez"],["negative / positive","bad / good","yomon / yaxshi"],["incorrect","wrong","xato"],["inexpensive","cheap","arzon"]]},{"t":"h3","x":"6. Phrasal verbs"},{"t":"p","x":"Phrasal verblar norasmiy xatlarda ishlatiladi; rasmiy xatlarda esa bitta so'zdan iborat sinonim afzal: _give up → abandon_ (voz kechmoq), _find out → discover, learn_ (bilib olmoq)."},{"t":"h3","x":"7. Bog'lovchilar"},{"t":"table","head":["Formal","Informal","Tarjima"],"rows":[["prior to","before","oldin"],["therefore","so","shuning uchun"],["consequently","as a result","natijada"],["despite","in spite of","garchi, qaramay"],["furthermore","also","shuningdek"],["however","but","ammo"],["in order to","to","uchun"],["in the event of","if","agar"],["definitely","really","albatta"],["in my opinion","I think","menimcha"],["finally","in the end","nihoyat"]]},{"t":"h3","x":"8. Misol"},{"t":"model","title":"Formal","x":"I regret to inform you that the product you purchased is currently out of stock. We sincerely apologize for any inconvenience this may have caused."},{"t":"model","title":"Informal","x":"I'm sorry, but the thing you bought is out of stock right now. We're really sorry about the hassle."},{"t":"p","x":"Norasmiy xatning belgilari: kundalik so'zlashuv gaplari (_I had a great time_), iboralar (_drop me a line_), phrasal verblar (_get on, give up_), qisqartmalar (_can't, don't, I'm, I'll_)."},{"t":"h3","x":"9. Bir xil fikr — ikki uslubda"},{"t":"table","head":["Formal","Informal"],"rows":[["I am writing to inquire about… / I am writing with regard to…","I'm writing to ask about…"],["I would be grateful if you could…","Can you do me a favour and…"],["I sincerely apologize for…","I'm really sorry about…"],["Please respond at your earliest convenience.","Please get back to me when you can."],["Please do not hesitate to contact me if you need any further assistance.","Let me know if you need any help."],["I kindly request you to consider my application for the position of waiter in your esteemed organization.","I was hoping you could do me a favour and check out my application for the waiter job at your cool company."],["We would like to bring to your attention the discrepancies found in the financial report submitted earlier this month.","So, there's this issue we noticed with the financial report you sent. Can you take a look at it, please?"],["I regret to inform you that I will be unable to attend the conference due to unforeseen circumstances.","I'm so sorry, but I can't make it to the conference. Something unexpected came up."],["We would like to extend our heartfelt congratulations on your recent academic achievement.","Congrats on acing that exam! You did awesome!"],["Please find enclosed the necessary documents as requested for the visa application process.","I've included all the documents you need for the visa stuff. Let me know if you need anything else."]]},{"t":"h3","x":"10. Uslubni tanlashda 3 narsaga e'tibor bering"},{"t":"list","ordered":true,"items":["**Kimga yozyapsiz?** Do'st, tanish, qarindosh — norasmiy; mansabdor shaxs va notanish — rasmiy.","**Qanday holat bo'yicha yozyapsiz?** Iltimos qilyapsizmi? Rasmiy xatda iltimosingizni ehtiyotkorona, norasmiy xatda bemalol aytasiz.","**Ruhiy holatingiz** — xafamisiz, jahlingiz chiqyaptimi yoki minnatdormisiz? So'zlarni shunga qarab tanlaysiz."]},{"t":"h3","x":"Uslubiy xatolar va ularning tuzatilishi"},{"t":"table","head":["Xato gap","Muammo","To'g'ri variant"],"rows":[["I am very sorry to have to inform you but I want to complain about the service I received at your restaurant.","Shikoyat qilyapti, lekin haddan tashqari muloyim va uzr so'rayapti.","I would like to complain about the service I received at your restaurant."],["You must send your catalogue to the above address immediately.","Buyruq ohangi juda kuchli, holbuki biz iltimos qilyapmiz.","Please could you send me the catalogue to the above address as soon as possible."],["Dear Anne, I request the pleasure of your attendance at my birthday party…","Do'stga ortiqcha rasmiy uslubda yozilgan.","I would like to invite you to my birthday party at my house next Saturday afternoon."],["Unfortunately I must return to my country as my Granny has not been very well lately. (hamkasbga)","Hamkasbga rasmiyroq, ortiqcha hissiyotsiz yozish kerak.","Unfortunately, I must return to my country because of my grandmother's continued ill-health."],["Dear Sir/Madam, I was excited when I saw your advertisement for a teacher… and I would be really happy to work for your company.","Ishga kirish xati — uslub rasmiy va neytral bo'lishi kerak.","I saw your advertisement in Darakchi and I would like to apply for the position of teacher."]]},{"t":"note","x":"Butun xat davomida **faqat bitta uslubdan** foydalaning. Xatning bir qismi rasmiy, boshqa qismi norasmiy bo'lsa, bahoingiz pasaytiriladi."},{"t":"ex","no":"3.1","q":"Quyidagi holatlar bo'yicha rasmiy xat yozasizmi yoki norasmiy?","kind":"tf","opts":["Rasmiy","Norasmiy"],"items":[{"q":"You saw furniture you liked at an exhibition and you would like a catalogue.","a":0},{"q":"You want your friend to come to your partner's surprise birthday party at a restaurant.","a":1},{"q":"You recently stayed in a hotel and the service was most unsatisfactory.","a":0},{"q":"You are interested in a job as a part-time sales assistant at a bookshop.","a":0},{"q":"You want your friend to look after your pet dog while you go on holiday.","a":1},{"q":"You went to a restaurant and found a cockroach in your soup.","a":0},{"q":"There is a gas leak in your rented flat.","a":0,"why":"Uy egasi yoki boshqaruvchiga yoziladi — rasmiy."}]},{"t":"ex","no":"3.2","q":"Quyidagi gaplarni rasmiy (F) yoki norasmiy (I) ga ajrating.","kind":"tf","opts":["Formal","Informal"],"items":[{"q":"I would also appreciate some information.","a":0},{"q":"Well, I must go now.","a":1},{"q":"Kindly accept my sincere apologies.","a":0},{"q":"You are cordially invited to attend …","a":0},{"q":"I am writing in response to your advertisement.","a":0},{"q":"Thanks for the invitation to your dinner party.","a":1},{"q":"I am writing to express my strong dissatisfaction with …","a":0},{"q":"I look forward to meeting you in person.","a":0},{"q":"Just a quick note to tell you …","a":1}]},{"t":"ex","no":"3.3","q":"Xatni o'qing. Jadvaldagi norasmiy jumlalar xatdagi qaysi rasmiy jumlaga mos keladi?","kind":"match","intro":"_Dear Mrs Hunter, With reference to your advertisement in Thursday's edition of the Daily Star, I am interested in applying for the position of primary school teacher. I am 28 years old and currently teaching in Margate. I have a BSc degree awarded by Glasgow University in 2005. I completed my certificate in Education at Preston Teacher Training College in 2006. I have been working for Margate Education Department since 2007. During this time, I have enjoyed teaching a variety of subjects, including English. I consider myself to be punctual, hard-working, and fair. I enjoy working with children and have good organizational skills. I enclose a reference from my present employer. I would be grateful if you would consider my application. I am available for an interview any weekday morning. I look forward to hearing from you. Yours sincerely, Steven Davies_","opts":[{"k":"A","x":"With reference to your advertisement"},{"k":"B","x":"I enjoy working with children"},{"k":"C","x":"I am interested in applying for the position of"},{"k":"D","x":"I look forward to hearing from you"},{"k":"E","x":"I completed my certificate in Education"},{"k":"F","x":"I am available for an interview"},{"k":"G","x":"I have been working for"},{"k":"H","x":"I would be grateful if you would consider my application"},{"k":"I","x":"I consider myself to be punctual"},{"k":"J","x":"I enclose a reference from my present employer"}],"items":[{"q":"About your advert","a":"A"},{"q":"I want to apply for","a":"C"},{"q":"I got my teaching certificate","a":"E"},{"q":"I've had a job in","a":"G"},{"q":"I think I'm always on time","a":"I"},{"q":"I like working with kids","a":"B"},{"q":"There's a note from my boss","a":"J"},{"q":"I'd like it if you hired me","a":"H"},{"q":"I'm free to talk to you","a":"F"},{"q":"Drop me a line sometime","a":"D"}]}],"writes":0},{"task":1,"no":4,"title":"Letters of request","uz":"So'rov xati","pages":"21–29","blocks":[{"t":"p","x":"**So'rov xati** sizga yordam, ma'lumot, ruxsat yoki boshqa birovdan ko'mak kerak bo'lganda yoziladi. Unda maqsadingizni va so'rovingiz sabablarini aniq ko'rsatishingiz kerak. Asosiy holatlar:"},{"t":"list","ordered":true,"items":["Ma'lumot so'rash","Yordam so'rash","Ruxsat so'rash","Xayriya yoki homiylik so'rash","Uchrashuv belgilash","Kimnidir tadbir yoki bazmga taklif qilish"]},{"t":"p","x":"So'rov xati har doim **aniq, tushunarli va samimiy** ohangda yoziladi. Salomlashishdan keyin xat yozish maqsadi 1–2 gap bilan tushuntiriladi — aynan maqsad xatning turini belgilaydi."},{"t":"phr","title":"Maqsadni boshlash uchun iboralar","items":[["I am writing to inquire / enquire about…","…haqida so'rash uchun yozyapman"],["I would like to request your assistance with…","…bo'yicha yordamingizni so'ramoqchiman"],["I am writing to request information about…","…haqida ma'lumot so'rab yozyapman"],["I am writing to seek your permission for…","…uchun ruxsatingizni so'rab yozyapman"],["I am addressing this letter to request…","Bu xatni …ni so'rash uchun yozyapman"]]},{"t":"h3","x":"Vaziyat → maqsad gapi"},{"t":"table","head":["Vaziyat","Maqsad (purpose)"],"rows":[["You want your friend to look after your pet dog while you go on holiday.","I'd like you to help me with taking care of my pet dog while I am on holiday in Brazil."],["You want to request information from a university.","I am writing to request information about the admission process, courses offered, and tuition fees for the upcoming academic year."],["You want to request a job application form from a company.","I am writing to request a job application form and further details about available positions at your esteemed organization."],["You want to request a meeting with a professional contact.","I am writing to request a meeting with you to discuss potential collaboration opportunities and share ideas."],["You want to request a leave of absence from work.","I am writing to formally request a leave of absence from 11th to 13th January due to personal reasons."]]},{"t":"p","x":"Maqsaddan keyin 3 ta tayanch savolga alohida paragraflarda javob yoziladi. Odatda **faqat bitta** tayanch savol sizdan haqiqatan ma'lumot yoki yordam so'rashni talab qiladi — uni topa bilish muhim."},{"t":"task","label":"Rasmiy topshiriq","situation":"You have just started a course in a college which has no sports facilities of its own.","to":"Write a letter to the manager of the nearest private sports club. In your letter","bullets":["introduce yourself","say why you are interested in this sports club","ask some questions about the club e.g., facilities, members, costs"]},{"t":"p","x":"Xat notanish insonga — **rasmiy**. 1- va 2-tayanch savollarda o'zingizni tanishtirasiz va nega aynan shu klubni tanlaganingizni yozasiz. Faqat **3-tayanch savol** so'rovni talab qiladi."},{"t":"model","title":"3-paragraf · B2 namuna","x":"Lastly, I am writing to request information about the types of membership the club offers. Do you have monthly or weekly based tickets available or do I need to sign up for a longer period?"},{"t":"note","x":"So'rov xatida qabul qiluvchiga to'g'ridan-to'g'ri savol berib ma'lumot so'rashingiz ham mumkin."},{"t":"model","title":"3-paragraf · C1 namuna","x":"Lastly, I would like to enquire about the overall membership strength and the composition of the members in terms of age groups and sports preferences. Understanding the club's diversity will help me better evaluate the sports activities and social interactions that I can participate in."},{"t":"phr","title":"So'rov paragrafini boshlash uchun","items":[["I would like to kindly request…",""],["I am reaching out to request…","reach out to — …ga murojaat qilmoq"],["I would be grateful if you could…",""],["I hope you can assist me with…",""],["What I wanted to ask you was…","(norasmiy)"]]},{"t":"task","label":"Norasmiy topshiriq","situation":"You are going to visit the town where your friend went to university.","to":"Write a letter to your friend. In your letter:","bullets":["explain why you will be visiting the town","give details of where you will be staying","ask your friend to recommend some evening entertainment"]},{"t":"model","title":"3-paragraf namunasi","x":"As you know the town better than anyone, I would greatly appreciate your recommendations for evening entertainment. Whether it's a cozy café, a lively music venue, or any local events, I am open to exploring the town's vibrant nightlife."},{"t":"h","x":"To'liq namunaviy xatlar"},{"t":"task","label":"Rasmiy xat","situation":"You want to learn a language. There is a teacher near to where you live.","to":"Write a letter to the teacher. In the letter:","bullets":["say how you came to know about him/her","explain why you want to learn","ask what help they can offer."]},{"t":"model","title":"Sample answer","x":"Dear Prof. Yuldashev,\n\nI am writing to inquire about taking Chinese lessons with you, and I am delighted to have found out about your language teaching services through a local advertisement.\n\nThe reason I am keen on learning Chinese is my desire to expand my horizons and explore diverse cultures. I believe that language is a gateway to understanding and appreciating different customs and traditions. Learning Chinese will not only enhance my personal growth but also open up new opportunities for professional development and interaction with a wider community.\n\nI am reaching out to request information about the language learning opportunities you offer. I am particularly interested in understanding the structure of your lessons, the duration of the course, and the frequency of classes. Additionally, I would like to know if you provide individual or group sessions and if there are any specific materials or resources required for the course.\n\nIf you can spare a moment to discuss the details and availability, I would greatly appreciate it. I am enthusiastic about commencing this learning journey with your guidance.\n\nThank you for considering my request. I look forward to your response.\n\nSincerely,\nBarno Sabirova"},{"t":"task","label":"Norasmiy xat","situation":"You are moving to a new city for work and have just realized that an old friend lives in the city.","to":"Write a letter to your friend. In your letter:","bullets":["ask them for advice in finding accommodation","tell them where you would like to live","tell them the type of place you are looking for"]},{"t":"model","title":"Sample answer","x":"Dear Jakhongir,\n\nI hope this letter finds you in great spirits. As you might have heard, I am relocating to Samarkand for a new job opportunity, and I just discovered that you are living there as well. I would be grateful if you could help me to find suitable accommodation.\n\nSince you are already familiar with the area, I was hoping to seek your valuable advice on finding suitable accommodation. Ideally, I would prefer to live in a neighbourhood that is safe, well-connected to public transportation, and offers a vibrant community vibe.\n\nAs I'm still in the early stages of my housing search, I would appreciate any insights you might have regarding the best areas to consider. I am looking for a cozy one-bedroom apartment or a small house with some greenery nearby, as I enjoy spending time outdoors.\n\nI genuinely value your guidance and any tips you can provide to ease my transition to the new city. I look forward to catching up soon and creating more memories together.\n\nThank you for your support, and let's plan a meet-up once I'm settled in.\n\nWarm regards,\nKamol"},{"t":"ex","no":"4.1","q":"Berilgan vaziyatlar asosida xatning maqsadini 1 yoki 2 ta gap bilan ifodalang.","kind":"write","items":[{"q":"You want to request information about a product from the manager of the company.","sample":"I am writing to enquire about a brand-new laptop which is manufactured by the HP company."},{"q":"You want to request a recommendation letter from a former employer or professor.","sample":"I am writing to kindly request a recommendation letter from you as my former employer."},{"q":"You want to request a meeting with a potential client or business partner.","sample":"I am writing to request a meeting with you to discuss potential business opportunities and collaboration."},{"q":"You want to request permission from your friend to drive his or her car at the weekend.","sample":"I am writing to request your permission to borrow your car for the weekend."},{"q":"You want to request information about available job vacancies from a company.","sample":"I am writing to inquire about any available job vacancies at your company."},{"q":"You want to request a refund for a defective product from a supermarket.","sample":"I am writing to request a refund for a defective product I purchased from your supermarket."},{"q":"You want to request access to the home library of your friend.","sample":"I am writing to request access to your home library for research and reading purposes."},{"q":"You want to request a change in schedule or work hours.","sample":"I am writing to request a change in my work schedule or working hours due to personal reasons."},{"q":"You want to request information about sports facilities available at the local sports centre.","sample":"I am writing to inquire about the sports facilities available at your local sports centre."},{"q":"You want to request your friend to share his or her travel experiences or tips for a destination.","sample":"I am writing to ask if you could share your travel experiences and any tips you have for my upcoming trip to Paris."}]},{"t":"ex","no":"4.2","q":"Har bir holat bo'yicha xatning maqsadini yozing.","kind":"write","items":[{"q":"You are a student who lost your backpack in a park. Write a letter to the park manager requesting assistance in finding it.","sample":"I would kindly request your assistance with finding my backpack that I lost because of my carelessness in the park."},{"q":"You are a member of a community organization seeking financial support for a charity event. Write a letter to a local business requesting sponsorship or donations.","sample":"I am writing to request sponsorship or donations from your local business to support our upcoming charity event organized by our community organization."},{"q":"You are a teacher planning an educational field trip for your class. Write a letter to the school principal requesting permission and support for the trip.","sample":"I am writing to request permission and support from the school principal for an educational field trip I am planning for my class."},{"q":"You recently purchased a faulty product from an online store. Write a letter to the customer service department requesting a return and refund.","sample":"I am writing to request a return and refund for a faulty product I recently purchased from your online store."},{"q":"You are an employee seeking a flexible work schedule to balance personal and family responsibilities better. Write a letter to your employer requesting a flexible schedule arrangement.","sample":"I am writing to request a flexible work schedule arrangement to better balance my personal and family responsibilities."},{"q":"You want to borrow a book from your friend. Write a request letter to your friend, politely asking if you can borrow the book.","sample":"I am writing to politely ask if I can borrow the book you mentioned during our conversation."}]},{"t":"ex","no":"4.3","q":"Berilgan so'zlardan foydalanib xatni to'ldiring. Bir so'zdan bir necha marta foydalanish mumkin.","kind":"fill","bank":["sincerely","position","qualifications","opportunity","consider","experience","application","interview","skills","grateful","request"],"text":"Dear Sir or Madam,\n\nI am writing to {1} some information about available job opportunities in the position of sales manager at Nestle company. I came across the job {2} on your website and believe that my {3} and {4} make me a strong candidate for this {5}.\n\nI have {6} in sales, having worked for 8 years as an assistant sales manager at Coca Cola company. I am confident that my {7} in strong leadership, effective communication, and time management align well with the requirements of the sales manager role.\n\nI would be so {8} for the {9} to discuss my {10} further in an {11}. Thank you for considering my {12}.\n\nYours {13},\nBekzod Rahimov","a":["request/enquire","position/opportunity","qualifications/qualification/skills/experience","experience/qualifications/qualification/skills","position/opportunity","experience","skills","grateful","opportunity","qualifications/application/skills/experience","interview","application/request","sincerely"]},{"t":"ex","no":"4.4","q":"So'zlarning joylashuvini o'zgartirib, grammatik to'g'ri gap tuzing.","intro":"**Vaziyat:** You want to request your school principal for permission to organize a charity event to raise funds for a local orphanage.","kind":"order","items":[{"q":"to / the / I / event / charity / hold / permission / a / for / am / writing / request / orphanage / to","a":"I am writing to request permission to hold a charity event for the orphanage."},{"q":"kindly / approve / May / our / on / event / charity / request / you / could / I / 20th / if / would / like / to","a":"I would like to request if you could kindly approve our charity event on May 20th.||I would like to kindly request if you could approve our charity event on 20th May.||I would like to kindly request if you could approve our charity event on May 20th."},{"q":"soon / a / hear / I / hoping / from / positive / you / response / am / to","a":"I am hoping to hear a positive response from you soon.||I am hoping to hear from you soon a positive response."},{"q":"you / my / considering / for / application / thank","a":"Thank you for considering my application."},{"q":"will / grateful / I / be / support / your / for","a":"I will be grateful for your support."},{"q":"request / favourable / provide / a / response / you / hope / my / consider / and / will / I","a":"I hope you will consider my request and provide a favourable response."}]},{"t":"p","x":"**4.5.** To'liq xat yozish topshiriqlari (tourist information centre, seaside hotel) — **Yozish xonasi**da."}],"writes":16},{"task":1,"no":5,"title":"Complaint letters","uz":"Shikoyat xati","pages":"30–39","blocks":[{"t":"p","x":"Imtihonda biror mahsulot yoki xizmatdan norozi ekaningizni ifodalovchi **rasmiy yoki yarim rasmiy** xat yozish so'ralishi mumkin. Xatda qanday muammoga duch kelganingiz, u sizga qanday ta'sir qilayotgani va kompaniya yoki shaxs nima qilishi kerakligini yozasiz."},{"t":"p","x":"Shikoyat xatining asosiy mavzulari:"},{"t":"list","ordered":true,"items":["Turar joy muammolari","Mahsulot yoki xizmat sifati","Transport muammolari","Restoran xizmati yoki ovqat","Ishdagi muammolar","Maktab yoki universitetdagi muammolar"]},{"t":"task","label":"Imtihondagi ko'rinishi","situation":"You bought a TV a week ago but when you got home you discovered it did not work as you expected.","to":"Write a letter to the company and in your letter:","bullets":["introduce yourself","explain the problem","and state what action you would like from the company."]},{"t":"h","x":"Shikoyat xatining qismlari"},{"t":"h3","x":"1. Purpose — maqsad"},{"t":"p","x":"Xat yozishdan maqsadingizni aniq ifodalaysiz."},{"t":"model","x":"Dear Sir or Madam,\n\nI am writing to express my dissatisfaction with the modern TV that I bought from your store."},{"t":"h3","x":"2. Details of the issue — holat tafsilotlari"},{"t":"p","x":"Vaziyat qachon va qanday sodir bo'lganini yozasiz: sana, manzil, mahsulot nomi. Muammoning o'zini esa keyingi paragrafda yozasiz."},{"t":"model","x":"I bought a modern TV of the latest model from the branch of \"Universal\" chain of stores in Samarkand on June 12. The store employee told me that the TV shows Russian and European channels in addition to Uzbek channels."},{"t":"h3","x":"3. Explanation of the problem and its impact — muammo va uning ta'siri"},{"t":"p","x":"Muammoni aniq faktlar bilan tasvirlaysiz va u sizga yoki atrofingizdagilarga qanday salbiy ta'sir qilganini yozasiz."},{"t":"model","x":"But when I came home and tuned the TV, it showed only Uzbek channels. The purpose of getting the TV was to please my disabled mother who stays at home all day, because my mother does not understand Uzbek and likes to watch movies and shows only in Russian and English. Now there is no chance for it."},{"t":"h3","x":"4. Requests and solutions — talab va yechimlar"},{"t":"p","x":"Muammoni hal qilish uchun nima qilish kerakligini yozasiz. Odatda **or** so'zi yordamida ikki va undan ortiq yechim taklif qilinadi."},{"t":"model","x":"That's why I ask you to have my TV set up by a professional or replace it with another TV that actually shows European channels."},{"t":"h3","x":"5. Closing statement — yakunlovchi gap"},{"t":"model","x":"I hope you can address this matter promptly and provide a suitable solution."},{"t":"h3","x":"6. Closing — xayrlashuv"},{"t":"model","x":"Yours faithfully,\nNargiza Sobirova"},{"t":"h","x":"Foydali iboralar"},{"t":"phr","title":"Salutation","items":["Dear (Recipient's Name),","Dear Sir or Madam,"]},{"t":"phr","title":"Introduction — maqsad","items":[["I am writing to express my dissatisfaction with… + noun",""],["I am writing to express my disappointment with/regarding… + noun",""],["I am writing to complain about… + noun",""],["I feel I must complain to you about… + noun",""]]},{"t":"phr","title":"Explanation of the problem and its impact","items":[["I regret to inform you that… + full sentence",""],["Unfortunately, I have encountered a problem regarding… + noun",""],["I was disappointed to find that… + full sentence",""],["To my disappointment, I found that… + full sentence",""],["Regrettably, I must inform you that… + full sentence",""],["Despite the fact that… + full sentence",""],["As a result of this, I had to… + V1","muammoning ta'siri"],["I was not able to… + V1",""],["Unfortunately, this led to… + noun",""],["Consequently, due to this problem I experienced… + noun",""]]},{"t":"phr","title":"Requests and solutions","items":[["To address this problem, I trust that you will… + V1",""],["To resolve this matter, I kindly request that you…","yechim taklif qiling"],["I would greatly appreciate it if you could…","yechim taklif qiling"]]},{"t":"phr","title":"Closing statement","items":["I look forward to a swift resolution to this matter.","I trust that you will take appropriate action.","I hope you can address this matter promptly and provide a suitable solution.","I trust that you will take the necessary steps to rectify this situation."]},{"t":"phr","title":"Closing","items":["Yours faithfully, (ism noma'lum)","Yours sincerely, (ism ma'lum)"]},{"t":"h","x":"Maqsad gapini yozish"},{"t":"table","head":["Vaziyat","Maqsad"],"rows":[["You ordered a new sofa online, but it was delivered with visible stains and damage.","I am writing to express my dissatisfaction with the damaged and stained sofa received, and to request a replacement or a refund."],["You recently dined at a restaurant where the food quality was poor, and the service was slow and inattentive.","I am writing to complain about the awful dining experience in your restaurant and to provide details of the issues encountered there."],["You booked a hotel room, but on arrival you discovered that the room did not match the description on the website.","I feel I must complain to you about the inaccurate description of rooms and facilities provided on your website."],["You purchased a fitness tracker that stopped working after a week of use.","I am writing to express my strong dissatisfaction with the malfunctioning of the fitness tracker that I bought from your company, and to request a replacement or a refund."],["You have bought a new camera but when you got it home you found it had some problems.","I am writing to complain about the defects of the newly purchased camera from your store."]]},{"t":"h","x":"Bog'lovchi so'zlar"},{"t":"p","x":"Shikoyat va uning asoslarini tartibli bayon qilish uchun bog'lovchilar muhim: _but, nevertheless / however, although / even though, not only… but also, furthermore, in addition to, firstly_. Ularni o'z o'rnida ishlatish yuqori ball olishga yordam beradi."},{"t":"model","x":"I purchased a laptop online yesterday but when I unpacked it, I realized that there was a big scratch on the screen.\n\nAlthough the location of your restaurant is quite suitable, the service of waiters and the quality of food were extremely disappointing.\n\nThe shoes I ordered were not only in a different size but also in a different colour than I expected.\n\nIn addition to the poor service of the hotel staff, there were small insects walking around my bed."},{"t":"h","x":"Topshiriq va namunaviy javob"},{"t":"task","situation":"You visit a sports centre regularly, and there is a problem with the changing rooms in it. You have complained about it several times but with no success.","to":"Write a letter to the manager of the sports centre. In your letter:","bullets":["describe what the problem with the changing rooms is","say what happened the last time you complained","explain what you want the manager to do"]},{"t":"model","title":"Sample answer","x":"Dear Sir or Madam,\n\nI am writing to express my dissatisfaction with the persistent issue with the changing rooms at your sports centre.\n\nI regret to inform you that there is an issue with the changing rooms due to their insufficient cleanliness and lack of proper maintenance. The floors are often wet and the locker doors are frequently malfunctioning. This has created an uncomfortable and unhygienic environment for members like myself who visit the sports centre regularly.\n\nDespite my previous complaints, there was not any visible improvement. This lack of response was disheartening, as it indicates a disregard for the well-being and satisfaction of your customers.\n\nIt would be greatly appreciated if you could take immediate action to address these concerns. It is essential that the changing rooms are cleaned thoroughly, locker facilities are repaired, and proper maintenance protocols are put in place to ensure a pleasant experience for all visitors.\n\nI hope you can address this matter promptly and provide a suitable solution.\n\nYours faithfully,\nBahodir Hamroyev"},{"t":"h","x":"Foydali so'zlar"},{"t":"table","head":["So'z","Tarjima","Misol"],"rows":[["malfunction","nosozlik","The laptop I purchased recently is already showing signs of malfunction."],["refund","pulni to'liq qaytarish","I would kindly request you to refund the money that I paid for these shoes."],["replacement","boshqasiga almashtirish","I would kindly request a replacement for the defective phone that I purchased from your store."],["disappointed","hafsalasi pir bo'lgan","I am strongly disappointed with the poor service and cold food served at your restaurant."],["inadequate","yetarli emas, talabga javob bermaydigan","The experience of your employee was inadequate to fix the problems in my kitchen."],["compensation","zararni qoplash","The airline provided compensation for the delayed flight in the form of a voucher."],["defective","nuqsonli, buzilgan","The defective remote control could not properly adjust the TV's volume."],["significant delay","sezilarli kechikish","I am writing to express my disappointment with the significant delay of my order made on June 19."],["frustration","hafsalasi pir bo'lish","…my strong dissatisfaction and frustration regarding the poor service I experienced during my last visit."],["despite the fact that","shunga qaramasdan","Despite the fact that I ordered a blue shirt in XXL, I was delivered a red shirt in XXXL."]]},{"t":"ex","no":"5.1","q":"Quyidagi holatlar bo'yicha shikoyat xatining maqsadini yozing.","kind":"write","items":[{"q":"You recently purchased a laptop online, but it arrived with a malfunctioning keyboard and a cracked screen.","sample":"I am writing to complain about the malfunctions of the laptop that I bought from your online store, and to request a replacement or a refund."},{"q":"You stayed at a hotel, and despite booking a non-smoking room, you were placed in a room with a strong smell of smoke.","sample":"I am writing to express my disappointment regarding the problem that I experienced during my stay at your hotel."},{"q":"You ordered a dress for a special occasion online, but the size and colour were different from what you selected.","sample":"I am writing to complain about a recent online order that I made from your company."},{"q":"While dining at a restaurant, you experienced poor service, cold food, and incorrect billing.","sample":"I am writing to express my strong dissatisfaction with the poor quality of service and food in addition to the discrepancy in billing that I experienced during my last visit to your restaurant."},{"q":"You signed up for a gym membership, but the facilities were not well-maintained, and some of the equipment was broken.","sample":"I am writing to complain about the problems with the conditions of the gym and to request a prompt resolution by the manager."},{"q":"You purchased a new smartphone, but it frequently freezes and shuts down unexpectedly.","sample":"I am writing to express my disappointment with the malfunctions of the phone that I bought from your store last week."}]},{"t":"ex","no":"5.2","q":"Yuqoridagi holatlardan birini tanlab, muammoni va uning ta'sirini batafsil yorituvchi 2–3 gapli paragraf yozing.","kind":"write","items":[{"q":"Scenario 1: laptop with a malfunctioning keyboard and a cracked screen.","rows":5,"sample":"I regret to inform you that some buttons of the keyboard were broken and it was impossible to see the full view of the screen because of a big scratch. As a result, I was not able to watch the video lessons of the last lectures and to prepare for the upcoming exam. Furthermore, I was late in finishing my dissertation due to the malfunctions of the keyboard."},{"q":"Scenario 2: smoke smell in a non-smoking hotel room.","rows":5,"sample":"Regrettably, I must inform you that although I had ordered a non-smoking room during my careful reservation before my arrival, I was allocated a room where the smell of smoke was extremely awful. Furthermore, the issue I reported to the staff about changing my room remained unattended. As a result, I could not sleep properly all night, which adversely affected my meeting with partners the following day."},{"q":"Scenario 3: a dress/shirt ordered online in the wrong size and colour.","rows":5,"sample":"Despite the fact that I ordered a blue shirt in XXL size, I was actually delivered a red shirt in XXXL size, which was completely different from what I had ordered. Unfortunately, due to this problem I had to wear my old clothes for my brother's wedding party. Moreover, I felt really terrible about my look, especially when everybody asked me to take a picture together."},{"q":"Scenario 4: poor service, cold food and incorrect billing at a restaurant.","rows":5,"sample":"Unfortunately, I encountered a problem regarding the on-time delivery of our ordered meal. Specifically, the waiter told us that our food would be ready in 15 minutes, but actually we had to wait more than an hour. Consequently, I felt really ashamed in front of my guests. Moreover, upon returning home and reviewing the bill, I discovered that we had been overcharged for food and drinks that were not part of our original order."},{"q":"Scenario 5: a badly maintained gym with broken equipment.","rows":5,"sample":"I regret to inform you that the conditions of the changing room were far below the standards. Precisely, it was not clean at all and was full of garbage left by gym members. Additionally, while attempting to run on the treadmill, I realized that it stopped several times due to malfunctions without any prior warning."},{"q":"Scenario 6: a smartphone that freezes and shuts down.","rows":5,"sample":"Despite the fact that my phone had recently been manufactured, its battery could not last as long as it was supposed to. Consequently, I was disconnected from my friends while playing online games together, which left me feeling truly disappointed. Additionally, the phone shuts down at night, causing my alarm not to work. As a result, I have been late for my lessons on several occasions."}]},{"t":"ex","no":"5.3","q":"O'zbek tilida berilgan shikoyat xati maqsadlarini ingliz tiliga o'giring.","kind":"write","items":[{"q":"Men sizning do'koningizdan o'tgan haftada sotib olgan muzlatgich bo'yicha noroziligimni bildirib yozyapman.","sample":"I am writing to express my dissatisfaction with the refrigerator that I purchased from your store last week."},{"q":"Men sizning restoraningizdagi yomon xizmat ko'rsatish va sifatsiz ovqatdan shikoyat bildirish uchun yozyapman.","sample":"I am writing to complain about the poor service and poor quality of food at your restaurant."},{"q":"Mehmonxonangizdagi xona sharoitlari va fitnes markazi bilan bog'liq muammolardan xafa bo'lganimni bildirish uchun yozyapman.","sample":"I am writing to express my disappointment regarding the room conditions and fitness centre issues at your hotel."},{"q":"Men 20-dekabrda bergan buyurtmamning sezilarli darajada kechikishidan qattiq norozi ekanligimni bildirish uchun yozyapman.","sample":"I am writing to express my strong dissatisfaction with the significant delay in my order placed on December 20th."},{"q":"Men sizning kompaniyangizdan ijaraga olgan mashinam bilan bog'liq muammolar ustidan shikoyat bildirish uchun yozyapman.","sample":"I am writing to complain about the problems with my rental car from your company."}]},{"t":"ex","no":"5.4","q":"Shikoyat xatidagi muammo yechimlarini ingliz tiliga o'giring.","kind":"write","items":[{"q":"Bu muammoni hal qilish uchun buzilgan mahsulotni zudlik bilan almashtirishingizni yoki pulini qoplab berishingizni iltimos qilaman.","sample":"To address this problem, I kindly request that you make a prompt replacement or a refund for the defective product."},{"q":"Ushbu muammoni hal qilish uchun sizdan mening hisobimni yaxshilab ko'rib chiqishingizni va hisob-kitob xatosini tuzatishingizni so'rayman.","sample":"To resolve this matter, I kindly request that you review my account thoroughly and rectify the billing error."},{"q":"Bu muammoni hal qilish uchun men sport zalining rahbariyatidan barcha mashg'ulot joylari, kiyim almashtirish xonalari va jihozlarni muntazam ravishda tozalashni so'rayman.","sample":"To address this concern, I kindly request that the gym management conducts regular cleaning of all workout areas, changing rooms, and equipment."},{"q":"Yo'lovchilar talabini qondirish uchun eng tig'iz soatlarda avtobus va poyezdlar sonini ko'paytirsangiz juda minnatdor bo'lar edim.","sample":"I would greatly appreciate it if you could increase the number of buses and trains during peak hours to meet the demand of commuters."},{"q":"Bu muammoni hal qilish uchun ofitsiantlaringizni qog'oz va ruchka o'rniga zamonaviy dasturlar yordamida buyurtma qabul qilishga undashingizni so'rayman.","sample":"To solve this problem, I kindly request you to encourage your waiters to take orders using modern software instead of paper and pen."},{"q":"Parvoz kechikishi sababli yuzaga kelgan noqulayliklar va mehmonxona uchun qo'shimcha to'lovni zudlik bilan qoplashingizni so'rayman.","sample":"I kindly request you to compensate promptly for the inconvenience and the extra payment for a hotel caused by the delay of the flight."},{"q":"Noutbuk uchun to'langan pulni zudlik bilan qaytarib berishni so'rayman, chunki olingan mahsulot va'da qilingan holatda emas va kutilganidek ishlamayapti.","sample":"I kindly request a full refund for the laptop, as the product received is not in the promised condition and is not functioning as expected."}]},{"t":"p","x":"**5.5.** To'liq shikoyat xatlari (qo'shnining baland musiqasi, buzuq mikroto'lqinli pech) — **Yozish xonasi**da."}],"writes":24},{"task":1,"no":6,"title":"Asking and giving information","uz":"Ma'lumot almashish xati","pages":"40–46","blocks":[{"t":"p","x":"**Information letter** — bu turdagi xatda sizdan biror narsa haqida ma'lumot so'rash yoki ma'lumot berish so'raladi."},{"t":"task","label":"Topshiriq","situation":"Your local council is considering closing a sports and leisure centre that it runs, in order to save money.","to":"Write a letter to the local council. In your letter:","bullets":["explain why the centre is important for the local community","give details of how you and your friends or family use the centre","describe the possible effects on local people if the centre closes"]},{"t":"p","x":"Hokimiyat mablag' tejash uchun sport markazini yopmoqchi. Maqsadimiz — markaz biz uchun muhim ekanini tushuntirib, uni yopmaslikka ishontirish. Buning uchun uch xil ma'lumot beramiz: markazning **bizga** foydasi, **butun aholiga** foydasi va yopilishning **oqibatlari**."},{"t":"h3","x":"Tone"},{"t":"p","x":"Shahar hokimiyatiga yozyapmiz — **rasmiy** uslub. Ohang jiddiy, bo'lajak o'zgarishdan achinishni aks ettiradi. Mansabdor shaxs ismini bilmaymiz, shuning uchun _Dear Sir or Madam,_ bilan boshlaymiz."},{"t":"h3","x":"Purpose"},{"t":"model","x":"I am writing with regard to the proposed closure of the town's sports and leisure centre."},{"t":"h3","x":"Bullet points: Topic sentence + Supporting sentences"},{"t":"p","x":"3 ta tayanch savolga 3 ta alohida paragrafda javob beramiz. Har bir paragraf o'rtacha 3 gapdan iborat:"},{"t":"list","items":["**Topic sentence** — paragrafning birinchi va eng muhim gapi; umumiy mavzuni aks ettiradi.","**Supporting sentence** — topic sentence'ni asoslab, qo'shimcha ma'lumot va aniq misol beradi."]},{"t":"table","head":["","Topic sentence","Supporting sentence"],"rows":[["Bullet 1","First, I would like to stress how important the centre is for my own family.","My wife and I both use the gym on a daily basis, and our two children attend weekly gymnastics and football clubs, which they enjoy immensely."],["Bullet 2","I also believe that the leisure centre is an integral part of the local community.","It is where people go to do exercise, play sports, take part in group activities, and to socialize and make friends. It really is a social hub in the town."],["Bullet 3","If you do close the sports and leisure centre, the local residents will lose a treasured facility.","As there are no other sports centres within a reasonable distance, the closure would have a detrimental effect on health and quality of life in the area."]]},{"t":"note","x":"3-tayanch savolda **oqibatlar** (ko'plik) so'ralmoqda — shuning uchun kamida **ikkita** salbiy oqibat yozilishi kerak (bu yerda: health va quality of life)."},{"t":"model","title":"To'liq xat","x":"Dear Sir or Madam,\n\nI am writing with regard to the proposed closure of the town's sports and leisure centre.\n\nFirst, I would like to stress how important the centre is for my own family. My wife and I both use the gym on a daily basis, and our two children attend weekly gymnastics and football clubs, which they enjoy immensely.\n\nI also believe that the leisure centre is an integral part of the local community. It is where people go to do exercise, play sports, take part in group activities, and to socialize and make friends. It really is a social hub in the town.\n\nIf you do close the sports and leisure centre, the local residents will lose a treasured facility. As there are no other sports centres within a reasonable distance, the closure would have a detrimental effect on health and quality of life in the area.\n\nI hope that you will take these concerns into consideration before making a decision.\n\nYours faithfully,\nPaul Jones"},{"t":"h","x":"Indirect questions — muloyim savollar"},{"t":"p","x":"Tayanch savolda savol so'rash topshirig'i berilsa, rasmiy xatda **indirect question** (bilvosita savol) ishlatiladi:"},{"t":"table","head":["Direct","Indirect"],"rows":[["Could you give me some further details?","I would be grateful if you could give me some further details."],["Could you provide me some information about accommodation?","I would appreciate it if you could provide me with some information about accommodation."],["Could you tell me the time of arrival?","I was wondering if you could tell me the time of arrival."]]},{"t":"ex","no":"6.1","q":"Berilgan \"indirect question\" strukturalaridan foydalanib gaplarni ingliz tiliga tarjima qiling.","kind":"write","items":[{"q":"**I would appreciate it if you could provide me with information regarding…** — Agar siz menga universitetingizning magistratura dasturiga ariza topshirish jarayoni haqida ma'lumot bersangiz, minnatdor bo'lardim.","sample":"I would appreciate it if you could provide me with information regarding the application process for your university's master's programme."},{"q":"**Could you kindly clarify the procedure for…** — Mamlakatingizda o'qish uchun viza olish tartibiga oydinlik kiritib bera olasizmi?","sample":"Could you kindly clarify the procedure for obtaining a student visa to study in your country?"},{"q":"**I was wondering if you could shed some light on…** — Stipendiya olish talablariga biroz oydinlik kirita olasizmi, deb so'ramoqchi edim.","sample":"I was wondering if you could shed some light on the requirements for obtaining a scholarship."},{"q":"**I am interested in knowing more about…** — Kompaniyangiz quyosh energiyasi sohasida taqdim etayotgan xizmatlar haqida ko'proq bilishga qiziqaman.","sample":"I am interested in knowing more about the services your company offers in the field of solar energy."},{"q":"**I am curious about the availability of…** — Kelgusi yil maktabingizda o'qituvchi yordamchisi lavozimlari uchun bo'sh ish o'rinlari bor-yo'qligini bilishni xohlardim.","sample":"I am curious about the availability of teaching assistant positions at your school for next year."},{"q":"**I would be grateful if you could inform me about…** — Kelajakda o'qituvchilar uchun o'tkaziladigan seminarlar haqida ma'lumot bersangiz, minnatdor bo'lardim.","sample":"I would be grateful if you could inform me about any upcoming seminars for teachers."}]},{"t":"ex","no":"6.2","q":"Xatdagi ikkinchi tayanch savolga javob yozilmagan. Shu paragrafni o'zingiz yozing.","kind":"write","items":[{"task":{"situation":"Your neighbourhood is experiencing a surge in crime, and you believe that increased police presence is necessary.","to":"Write a letter to your local police department. In your letter:","bullets":["describe recent incidents or concerns about safety in your neighbourhood","explain why having more police presence is essential for community security","request specific actions or strategies to address the crime issue"]},"given":"Dear Sir or Madam, I am writing to bring to your attention the recent rise in crime within our neighbourhood, which has left many residents deeply concerned about our safety. First and foremost, our community relies heavily on the local police department to maintain law and order. However, recent incidents, including break-ins and vandalism, have shaken our sense of security. Consequently, residents are forced to install cameras in their homes and prevent their children from playing outdoors. [ … 2-paragraf … ] I respectfully urge the local police department to consider allocating additional resources and officers to our neighbourhood to address these concerns effectively and restore our community's sense of security. Thank you for your attention to this matter. Sincerely, Sanjar Ahmedov","rows":6,"sample":"It is crucial to emphasize that increasing police presence is vital for deterring criminal activity and ensuring the safety of our residents. A visible police presence not only prevents crimes but also fosters a sense of security among our community members, encouraging them to report suspicious activities promptly."}]},{"t":"p","x":"**6.3.** To'liq xatlar (Chris's surprise party, property agent) — **Yozish xonasi**da."}],"writes":7},{"task":1,"no":7,"title":"Apology letters","uz":"Uzr so'rash xati","pages":"47–56","blocks":[{"t":"p","x":"**Apology letter** — biror inson yoki tashkilot oldida qilgan noto'g'ri ishingiz uchun kechirim so'rash yoki xatoni tuzatishga samimiy istagingizni bildirish uchun yoziladi. Imtihonda uchraydigan holatlar:"},{"t":"list","items":["Apologize for a late payment","Apologize for a shipping delay or error","Apologize for poor or inadequate service","Apologize for missing an appointment","Apology for bad news to employees","Apologize for damaged property"]},{"t":"task","label":"1. Missed dinner party (norasmiy)","situation":"You said you would attend a friend's dinner party but you did not go.","to":"Write a letter to your friend. In the letter:","bullets":["apologize for not attending","explain why you did not attend","say what you will do to make up for it"]},{"t":"task","label":"2. Missed important meeting (rasmiy)","situation":"You missed an important meeting at work.","to":"Write a letter to your manager. In the letter:","bullets":["apologize for not attending","explain why you did not attend","say what you will do to make up for it"]},{"t":"h3","x":"Bizning vazifa"},{"t":"list","items":["Biz tufayli boshqaga noqulaylik yetganini, uni xafa qilib qo'yganimizni **tan olish**.","Bu hodisa nega va qanday bo'lganini **tushuntirib**, aybni o'z zimmamizga olish.","Xatoni tuzatish uchun **aniq choralarni** keltirish."]},{"t":"h3","x":"Tone"},{"t":"p","x":"Uslub tanlaganda ikki narsaga e'tibor bering: 1) xat yozayotgan odam sizga qanchalik yaqin; 2) mavzu qanchalik jiddiy. Uzr xatida hazil, jahl yoki shikoyat o'rinsiz — faqat **samimiy, pushaymon** ohang. Unutmang: xatni o'qiyotgan inson sizdan xafa. Yuqoridagi 1-xat norasmiy, 2-xat rasmiy uslubda yoziladi."},{"t":"table","head":["Less formal","More formal"],"rows":[["I apologize for missing your party.","I wish to sincerely apologize for missing the meeting."],["I regret that I couldn't make it.","I deeply regret that I was not in attendance."],["Please accept my apology.","Please accept my sincerest apology."],["I'm sorry I wasn't able to come.","I am very sorry that I was not able to come."]]},{"t":"table","head":["Foydali so'z","Tarjima","Misol"],"rows":[["make up for","zararni o'rnini to'ldirish","He bought me dinner to make up for being so late the day before."],["offend","xafa qilmoq","I think she was a bit offended that she hadn't been invited to the party."],["make it to","kelishilgan vaqtda yetib kelmoq","We only made it to the concert a few minutes before it was supposed to begin."],["let sb down","kimnidir umidini puchga chiqarmoq","I really felt I had let my parents down."],["resolve","hal qilmoq","I'm sure these problems can be satisfactorily resolved."],["take precautions","ehtiyot chorasini ko'rmoq","They failed to take the necessary precautions to avoid infection."]]},{"t":"h","x":"Xat qismlari"},{"t":"h3","x":"1. Purpose and apology"},{"t":"p","x":"Maqsadni aniq yozing, xatoyingizni tan oling va chin dildan afsusda ekaningizni ko'rsating."},{"t":"phr","items":["I am writing to apologize for… I feel terrible about what happened and I understand how much it must have affected you.","I am writing this letter to offer my sincere apologies for… I deeply regret any inconvenience or hurt that my actions may have caused you.","I am writing to offer my apologies for…","Please accept my sincere apologies for…"]},{"t":"model","title":"Letter 1 (informal)","x":"I'm so sorry that I didn't make it to your dinner party. I know that you worked hard planning the get-together and that you were expecting me to be there with the others. I can't believe I missed it and I'm completely to blame.\n\n— or —\n\nI hope you're doing well. I wanted to reach out and apologize for not making it to your dinner party as I had promised. I feel awful for letting you down, and I'm really sorry."},{"t":"model","title":"Letter 2 (formal)","x":"I am writing to apologize for not being at the budget meeting yesterday afternoon. I know these meetings are important, especially when we are making plans for the final quarter. Unfortunately, a delay kept me from attending.\n\n— or —\n\nI am writing to extend my sincere apologies for my absence from the crucial meeting held on 14 June. I understand the significance of my presence and the impact of my absence on the proceedings of the meeting."},{"t":"h3","x":"2. Explain"},{"t":"p","x":"Xato nima sababdan va qanday sodir bo'lganini qisqa tushuntiring — **bahona emas, uzr** shaklida. Aybni birovga to'nkamang; xatodan dars olgan bo'lsangiz, uni ham ayting. Qisqa, faktlarga asoslangan tushuntirish bering."},{"t":"phr","items":["The reasons behind my absence were…","The situation arose from…, but I understand that this does not excuse my behaviour.","Due to…, I was unable to meet the deadline as planned. However, I fully recognize that my delay affected the workflow and the team's goals.","The misunderstanding arose due to…","The error occurred due to…","I take full responsibility for this mistake.","I take full responsibility for any confusion caused."]},{"t":"h3","x":"Afsusni ifodalash: grammatika"},{"t":"table","head":["Struktura","Ma'nosi","Misol"],"rows":[["should / shouldn't + have + V3","…qilishim kerak edi / …qilmasligim kerak edi","I shouldn't have left it so late to book the tickets. / I should have booked the tickets earlier."],["wish + had + V3","Qani edi…","I wish I'd known about this earlier. / I wish I hadn't said yes."],["could / would + have + V3","…qilgan bo'lardim","I could have / would have done something about it (if I'd known about it earlier)."]]},{"t":"h3","x":"3. Propose solutions"},{"t":"p","x":"Holatni o'nglash uchun aniq yechim taklif qiling va bunday xato takrorlanmasligiga urg'u bering."},{"t":"model","title":"Letter 1","x":"To further make up for this blunder, if you are available, I'd like to have you and Bob over for dinner next weekend. I'll make your favourite, seafood lasagna.\n\n— or —\n\nTo make up for my absence, I'd love to treat you to a special homemade dinner at my place. I promise to put my best culinary skills to use and create a meal that we both will enjoy. Let's pick a date that works for you."},{"t":"model","title":"Letter 2","x":"I have followed up to make sure I have all the budget information. Alice is going to provide me with the forecast and Jane will be sending me the minutes. I am also having lunch with Jack today and he will answer any questions I may have about what was discussed.\n\n— or —\n\nTo make up for my absence, I will promptly review the meeting minutes and consult with colleagues who attended to ensure I am up to speed on the discussed matters. Additionally, I will schedule a meeting with you to address any questions or concerns arising from the meeting."},{"t":"h3","x":"4. Request forgiveness"},{"t":"model","x":"Once again, I'm really sorry for not being there when I said I would. I value our friendship immensely and want to make it up to you. (informal)\n\nOnce again, I apologize for any disruption my absence may have caused and appreciate your understanding in this matter. Thank you for your time and consideration. (formal)"},{"t":"h3","x":"5. Close the letter"},{"t":"p","x":"Hurmat ko'rsatadigan, muloyim yakun: _Take care,_ (norasmiy) / _Sincerely,_ / _Yours truly,_"},{"t":"ex","no":"7.1","q":"Kerry hamkasbining hujjatlariga bilmay kofe to'kib yubordi. Xatdagi o'zbekcha qismlarni ingliz tiliga o'giring.","kind":"write","items":[{"q":"(1) Bugun ertalab sodir bo'lgan ko'ngilsiz hodisa uchun chin dildan uzr so'rayman. Afsuski, men sizning muhim hujjatlaringizga tasodifan kofe to'kib yubordim. Men bu hujjatlarning ahamiyatini va xatoyim tufayli sodir bo'lgan noqulaylikni to'liq anglab turibman.","rows":4,"sample":"I want to offer my sincerest apologies for the unfortunate incident that occurred earlier today. Regrettably, I accidentally spilled coffee on your important documents. I fully understand the significance of these papers and the inconvenience my mistake has caused."},{"q":"(2) Tushunganingiz va sabr-toqatingiz uchun tashakkur. Iltimos, ushbu masalani hal qilishda yana qanday yordam bera olishimni aytsangiz.","sample":"Thank you for your understanding and patience. Please let me know how I can further assist in resolving this matter."}]},{"t":"ex","no":"7.2","q":"Kale hamkasbiga qarzini vaqtida qaytara olmagani uchun uzr so'rayapti. Bo'sh joylarni berilgan iboralar bilan to'ldiring.","kind":"fill","bank":["to resolve this","apologize for","unexpected medical expenses","inconvenience","patience"],"text":"Dear Mrs Jane,\n\nI sincerely apologize for the delay in repaying the debt of $300. Due to {1}, I am facing financial constraints that have hindered my ability to meet the agreed-upon timeline.\n\nI understand the {2} my delay may have caused. I deeply regret not fulfilling my obligation.\n\n{3}, I am actively seeking freelance work and will ensure complete repayment by 3 June.\n\nOnce again, I {4} any inconvenience my actions may have had. Your understanding is appreciated.\n\nThank you for your {5}.\n\nSincerely,\nLynn Kale","a":["unexpected medical expenses","inconvenience","to resolve this","apologize for","patience"]},{"t":"ex","no":"7.3","q":"Har bir holat nega sodir bo'lganini tushuntiruvchi paragraf yozing (to'liq xat emas, faqat sabablar).","kind":"write","items":[{"q":"An apology letter to your roommate for accidentally breaking their favourite mug.","rows":4,"sample":"I accidentally knocked over the mug while trying to clean the table, which caused it to fall and break on the floor. It was a moment of carelessness, and I deeply regret not being more careful with your belongings."},{"q":"An apology letter to your boss for missing an important deadline at work.","rows":4,"sample":"Despite careful planning, an unexpected technical error with my computer prevented me from meeting the deadline. I had everything in place, but this unforeseen issue prevented me from completing the task on time."},{"q":"An apology letter to your neighbour for the loud party you had last night.","rows":4,"sample":"Our party got livelier than expected, and I underestimated the noise level, which led to a disturbance in the neighbourhood. I apologize for not managing the volume properly and for any inconvenience it may have caused."},{"q":"An apology letter to a friend for forgetting their birthday.","rows":4,"sample":"Due to my busy day, I regrettably overlooked your birthday. It was never my intention to forget this special day, and I'm truly sorry for not being there to celebrate with you."},{"q":"An apology letter to a customer for a mix-up in their order at your business.","rows":4,"sample":"A miscommunication in our internal system resulted in the mix-up of orders, causing the error in your shipment. I take full responsibility for this mistake and understand the frustration it must have caused you."},{"q":"An apology letter to a teacher for plagiarizing a portion of your assignment.","rows":4,"sample":"Due to my rush to complete the assignment, I included information without proper citations. It was an oversight on my part, and I deeply apologize for not upholding academic integrity."},{"q":"An apology letter to a family member for an argument that got out of hand.","rows":4,"sample":"Emotions escalated during our argument, causing me to say hurtful things I didn't actually mean. I deeply regret my words and the negative impact they had on our relationship."},{"q":"An apology letter to a colleague for taking credit for their idea in a meeting.","rows":4,"sample":"During the meeting, I mistakenly claimed ownership of your idea without acknowledging your contribution. It was an error of judgement, and I apologize for not giving you the credit you deserve."},{"q":"An apology letter to a partner for breaking a promise you made to them.","rows":4,"sample":"Unforeseen circumstances beyond my control arose, forcing me to break the promise I had made to you. I deeply value our commitment and sincerely apologize for not being able to uphold it in this instance."},{"q":"An apology letter to a sports team for missing a crucial game due to illness.","rows":4,"sample":"Unfortunately, I fell ill unexpectedly on the day of the game; therefore, I could not participate as planned. I deeply regret not being able to contribute to the team's efforts."}]},{"t":"ex","no":"7.4","q":"Afsus bildiruvchi gaplarni ingliz tiliga o'giring (should have / wish / could have).","kind":"write","items":[{"q":"Qani edi tushunmovchilik yuzaga kelishidan oldin tafsilotlarni ikki marta tekshirib ko'rsam edi. Har qanday chalkashlik uchun samimiy uzrimni qabul qiling.","sample":"I wish I had double-checked the details before the misunderstanding occurred. Please accept my sincerest apologies for any confusion."},{"q":"Men vaqtni boshqarishda mas'uliyatliroq bo'la olardim; muhim uchrashuvni o'tkazib yuborganim uchun meni kechiring.","sample":"I could have been more responsible with my time management. Please forgive me for missing the important meeting."},{"q":"Men sizga bunday qo'pol so'zlarni aytmasligim kerak edi. Xafa qiladigan so'z aytganimdan chuqur afsusdaman.","sample":"I shouldn't have said such rude words to you. I deeply regret the hurtful words I said."},{"q":"Agar yuzaga keladigan muammolarni oldindan ko'ra olsam, qo'shimcha ehtiyot choralarini ko'rgan bo'lardim. Keltirilgan noqulayliklar uchun uzr so'rayman.","sample":"I would have taken extra precautions if I could have foreseen the problems that arose. I apologize for any inconvenience caused."},{"q":"Men uy vazifamni o'z vaqtida topshirishim kerak edi. Belgilangan muddatni o'tkazib yuborganim uchun uzr so'rayman.","sample":"I should have submitted the homework on time. I apologize for missing the deadline."},{"q":"Qani edi loyihani topshirishdan oldin uni yaxshilab ko'rib chiqishga vaqt ajratgan bo'lsam. Xatolar uchun uzr so'rayman.","sample":"I wish I had taken the time to thoroughly review the project before submitting it. I apologize for any errors that may have resulted."}]},{"t":"p","x":"**7.5.** To'liq uzr xatlari (qo'shnilar shovqindan shikoyat qilgan; ishga chiqish sanasini o'zgartirish) — **Yozish xonasi**da."}],"writes":18},{"task":1,"no":8,"title":"Thank you letters","uz":"Minnatdorchilik xati","pages":"57–64","blocks":[{"t":"p","x":"**Thank you letter** — birovga qilgan yaxshi ishi uchun minnatdorchilik bildirib yoziladigan xat. Topshiriqda aynan _write a thank you letter_ deyilmasligi mumkin; uning o'rniga _write a letter to tell … that you were happy with…_ kabi ifodalar bo'ladi."},{"t":"task","label":"Letter 1 · Formal","situation":"You and some friends ate a meal at a restaurant to celebrate a special occasion, and you were very pleased with the food and service.","to":"Write a letter to the restaurant manager. In your letter","bullets":["give details of your visit to the restaurant","explain the reason for the celebration","say what was good about the food and the service"]},{"t":"p","x":"Bu topshiriqda _thank you_ so'zi yo'q, lekin _very pleased with_ va _write to the restaurant manager_ minnatdorchilik xati kerakligini ko'rsatadi."},{"t":"h3","x":"Tone"},{"t":"p","x":"Xat **ijobiy** ohangda yoziladi: ma'lum narsalarni maqtaysiz va ularning hayotingizga ijobiy ta'siri haqida yozasiz. Kimga yozayotganingizga qarab rasmiy yoki norasmiy bo'ladi."},{"t":"table","head":["Formal","Informal"],"rows":[["Dear Mr Thompson,","Hi Jim,"],["I am writing to express my gratitude for…","Thanks so much for…"],["I wanted to let you know that I was impressed by…","The … was amazing! I absolutely loved it."],["Yours sincerely,","Cheers,"]]},{"t":"p","x":"**be grateful to** — minnatdor bo'lmoq: _I am grateful to you for all you have done._ / _I would be most grateful if you would send me the book immediately._"},{"t":"h3","x":"Tartib"},{"t":"list","ordered":true,"items":["Salutation","Purpose and thank you statement","Bullet point 1","Bullet point 2","Bullet point 3","Final thank you statement","Closing"]},{"t":"h3","x":"Purpose and thank you sentence"},{"t":"model","x":"Dear Sir,\nI am writing to thank you and your staff for making our celebration meal so special last Friday evening.\n\n— or —\n\nDear Mr Sanjar,\nI wanted to express my sincere gratitude for the exceptional dining experience my friends and I had at your restaurant recently.\n\n— or —\n\nDear Mr Thomson,\nI am writing to let you know that I really enjoyed the meal and service I had at your restaurant last Friday evening, and I wanted to show my appreciation for your hard work and the efforts made by your staff."},{"t":"h3","x":"Bullet points"},{"t":"p","x":"Har bir tayanch savolga alohida paragraf, har biri 2–3 gap. Imkon qadar ko'proq ma'lumot bering. **Bullet 1** (tashrif tafsilotlari): shunchaki \"kecha do'stlar bilan bordik\" deyish yetarli emas — muhim narsani nishonlaganingiz, joy topib berishgani kabi tafsilotlarni yozing."},{"t":"model","title":"Bullet 1","x":"I made a booking for ten people at very short notice on Friday, and you managed to find us a table. When we made the spontaneous decision to eat out that evening, we were amazed to find a table for such a large group, and we could not have chosen a better restaurant."},{"t":"model","title":"Bullet 2 — nimani nishonladingiz","x":"The ten of us were celebrating our university graduation. The ceremony had taken place, and my friends and I were all so relieved to have finally received our degree certificates. Nobody wanted to go home, so I suggested that we find somewhere to have dinner together.\n\n— or —\n\nIt was my wife's birthday and so we invited a group of six friends to join us for a meal to celebrate. We searched for somewhere with a wonderful garden view and a no-smoking setting. Your restaurant seemed to be the right choice for us."},{"t":"note","x":"3-tayanch savol **ikki narsani** so'raydi: ovqat **va** xizmat. Faqat ovqat haqida yozsangiz, topshiriqqa to'liq javob bermagan bo'lasiz. Fikrlar faqat ijobiy bo'lsin."},{"t":"model","title":"Bullet 3","x":"As soon as we walked into the restaurant, we knew that we were in good hands. Your waiters were extremely friendly and obliging, and the food was delicious. We were also impressed that both you and the head chef came to check that everyone was happy with their food."},{"t":"model","title":"Final thank you sentence","x":"All ten of us would like to thank you for giving us such a memorable evening.\n\n— or —\n\nThanks again for a wonderful evening."},{"t":"h3","x":"Grammar to thank: Third Conditional"},{"t":"p","x":"Yordam bergan odamning yaxshiligini e'tirof etish uchun **Third Conditional** qulay — bu grammatik bilimingizni ham ko'rsatadi: **If + S + had + V3, S + would + have + V3**."},{"t":"table","head":["O'zbekcha","English"],"rows":[["Agar siz o'sha kuni menga yordam bermaganingizda, men jiddiy muammolarga duch kelardim.","If you had not helped me that day, I would have had serious problems."],["Agar biz boshqa restoranga borganimizda, mehmonlarimni bunchalik xursand qila olmasdim.","If we had gone to another restaurant, I would not have been able to make my guests so happy."],["Agar siz konsertga chipta sovg'a qilmaganingizda, vaqtimizni maroqli o'tkaza olmasdik.","If you hadn't given us tickets to the concert, we wouldn't have been able to have a good time."]]},{"t":"model","title":"Full sample · Letter 1","x":"Dear Sir,\n\nI am writing to thank you and your staff for making our celebration meal so special last Friday evening.\n\nI made a booking for ten people at very short notice on Friday, and you managed to find us a table. When we made the spontaneous decision to eat out that evening, we were amazed to find a table for such a large group, and we could not have chosen a better restaurant.\n\nThe ten of us were celebrating our university graduation. The ceremony had taken place, and my friends and I were all so relieved to have finally received our degree certificates. Nobody wanted to go home, so I suggested that we find somewhere to have dinner together.\n\nAs soon as we walked into the restaurant, we knew that we were in good hands. Your waiters were extremely friendly and obliging, and the food was delicious. We were also impressed that both you and the head chef came to check that everyone was happy with their food.\n\nAll ten of us would like to thank you for giving us such a memorable evening.\n\nYours faithfully,\nPaul Jones"},{"t":"task","label":"Informal letter","situation":"A friend has agreed to look after your house and pet while you are on holiday.","to":"Write a letter to your friend. In your letter","bullets":["give contact details for when you are away","give instructions about how to care for your pet","describe other household duties"]},{"t":"model","title":"Sample","x":"Hello Jean,\n\nThanks again for agreeing to look in on Barry while I'm in Thailand for the week. I really appreciate it.\n\nI'd just like to give you a little extra info that I'd forgotten to mention when we spoke last time. Barry's pretty easy to look after. He gets fed twice a day from the bag of kibble under the sink. If he whines, don't bother giving him any more, as he's just trying to manipulate you. Like most cats, he can look after himself, but he gets a bit lonely, so it'll be good to have you there for him every now and then.\n\nAs for the house, you can water my plants whenever you think they look a bit dry, and please remember to bring in the delivery packages before noon, or else the local kids might steal them.\n\nIf there's any problem or if you have any questions, you can send me a message on WhatsApp or Messenger. I know you already have both of those.\n\nThanks again,\nDavid"},{"t":"ex","no":"8.1","q":"Har bir holat uchun faqat xatning maqsadi va tashakkurni ifodalovchi gap yozing.","kind":"write","items":[{"q":"Write a letter to a colleague who assisted you with a work-related task.","sample":"I am writing to extend my sincere thanks for the invaluable help you provided with creating a lesson plan about complex grammar rules."},{"q":"You have recently received a gift from a friend. Write a letter to thank him for the gift.","sample":"I hope this letter finds you well. I wanted to express my heartfelt gratitude for the wonderful gift you sent me."},{"q":"Write a letter to a teacher who provided valuable guidance during your studies.","sample":"I am writing to thank you for your exceptional guidance throughout my studies."},{"q":"Thank a company for a product or service you recently purchased.","sample":"I am writing to convey my appreciation for the sofa I recently purchased."},{"q":"Write a letter to a neighbour who helped you with looking after your pet while you were away.","sample":"I am writing to let you know that I am really grateful to you for taking care of my dog when I was on holiday."},{"q":"Write to a hotel for your recent enjoyable stay.","sample":"I am writing to express my gratitude for the exceptional stay at your hotel."}]},{"t":"ex","no":"8.2","q":"Third Conditional yordamida gaplarni ingliz tiliga o'giring.","kind":"write","items":[{"q":"Agar siz o'sha og'ir damlarda yonimda bo'lmaganingizda, men buni qanday uddalagan bo'lardim, bilmayman. Qo'llab-quvvatlaganingiz uchun katta rahmat.","sample":"If you hadn't been there for me during that difficult time, I don't know how I would have managed. Thank you so much for your support."},{"q":"Agar siz o'z tajribangizni men bilan baham ko'rmaganingizda, men adashib ketgan bo'lardim. Ko'rsatmangiz hamma narsani o'zgartirdi va men chin dildan minnatdorman.","sample":"If you hadn't shared your expertise, I would have been lost. Your guidance made all the difference, and I'm truly thankful."},{"q":"Siz meni ruhlantirmaganingizda, men hech qachon maqsadlarimga erishish uchun jasorat topa olmasligim mumkin edi.","sample":"If you had not given me encouragement, I might never have had the courage to pursue my goals."},{"q":"Agar meni qo'shmaganingizda, ajoyib tajribani qo'ldan boy bergan bo'lardim. Bu voqeani unutilmas qilganingiz uchun tashakkur.","sample":"I would have missed out on an amazing experience if you hadn't included me. Thank you for making that event so memorable."},{"q":"Agar siz hamma narsani mukammal tashkil qilmaganingizda, men vaqtimni bunday ajoyib o'tkazmagan bo'lardim.","sample":"I wouldn't have had such a wonderful time if you hadn't organized everything so perfectly."}]},{"t":"p","x":"**8.3.** To'liq xatlar (do'stlaringizdan kelgan suratlar; baxtsiz hodisada yordam bergan notanish inson) — **Yozish xonasi**da."}],"writes":11},{"task":1,"no":9,"title":"Job application or resignation","uz":"Ishga topshirish yoki ishdan bo'shash xati","pages":"65–75","blocks":[{"t":"p","x":"Imtihonda ishga topshirish yoki ishdan bo'shash bo'yicha xat so'ralishi mumkin. **Ishga topshirish xati** (job application) asosan quyidagi holatlarda yoziladi:"},{"t":"list","items":["Hozirgi kompaniyangizda boshqa lavozimga o'tish uchun (rasmiy)","Kutilmaganda kim bilandir tanishib, uning taklifiga ko'ra ish so'rab (yarim rasmiy)","Reklama yoki e'lon orqali ish so'rab (rasmiy)"]},{"t":"p","x":"Bunday xatda ta'lim yoki kasbiy malakangiz, oldingi tajribangiz, shaxsiy fazilatlaringiz va mahoratingiz haqida yoziladi."},{"t":"note","x":"**Tone:** ishga topshirish va ishdan bo'shash xatlari har doim **rasmiy**. Hazil, qisqartmalar va qo'pol so'zlar ishlatilmaydi."},{"t":"task","label":"Imtihondagi ko'rinishi","situation":"You have seen an advert in a local magazine for a job working at a catering company during the summer season. You decide to apply for the job.","to":"Write a letter to the director of the company. In your letter:","bullets":["introduce yourself","explain what experience and special skills you have","explain why you are interested in the job"]},{"t":"h","x":"Ishga topshirish xati: tuzilishi va iboralar"},{"t":"note","x":"Tayanch savollarga qarab xatdagi ma'lumotlar ketma-ketligi o'zgarishi mumkin."},{"t":"phr","title":"1. Salutation","items":["Dear Sir or Madam,","Dear Mr / Ms / Mrs …,"]},{"t":"phr","title":"2. Introduction","items":["I am writing to apply for the position of (position) advertised in…","I am writing to express my interest in the (position) at (company name) as advertised on…","I am excited to apply for the (position) that I learned about through…"]},{"t":"phr","title":"3. Experience / Qualifications","items":["Currently, I am employed as a/an … by the company…","As you can see from my CV, I have been working as … for the past X years.","I am a/an … with more than 10 years of experience in…","I am a recent graduate of … University and I have a significant background in…","My responsibilities encompass…","I have / hold / obtained a degree / diploma / certificate in…","I have successfully completed a course in … (business management) at … (Harvard University)","I am eager to contribute…","I consider myself to be … (punctual, reliable, hard-working, motivated)","I have strong … (communication) skills and an excellent knowledge of … (IT)"]},{"t":"phr","title":"4. Closing statement","items":["I would appreciate a reply at your earliest convenience.","I would be available for a face-to-face interview at any time.","I would be pleased to supply you with any further information during the interview.","Should you have any questions, feel free to contact me at any time."]},{"t":"phr","title":"5. Closing","items":["Yours faithfully,","Yours sincerely,"]},{"t":"h3","x":"Zamonlardan to'g'ri foydalanish"},{"t":"table","head":["Nima haqida","Zamon","Misol"],"rows":[["Shaxsiy fazilat va qobiliyatlar","Present Simple","I am a patient and reliable person."],["Avvalgi tajriba","Past Simple","I left school in 1994. I worked for General Motors for four years."],["Yaqin oradagi ish yoki o'qish","Present Perfect","I have been working for LTYU for two years. I have recently graduated from university."]]},{"t":"h3","x":"Foydali so'zlar"},{"t":"table","head":["So'z","Tarjima","Misol"],"rows":[["outgoing and friendly","kirishimli va do'stona","I am an outgoing and friendly person who can get on well with other team members."],["punctual and hard-working","o'z vaqtida bajaruvchi va mehnatsevar","My previous job as a manager helped me develop punctuality and a strong work ethic."],["flexible and creative","moslashuvchan va ijodkor","I am very flexible in a new working environment and creative in finding solutions to problems."],["CV / résumé","tajriba, malaka va ma'lumot haqida hujjat","I submitted my CV to the prospective employer in hopes of securing the job."],["qualification","malaka (sertifikat)","I have all the qualifications to apply for this position."],["communication skills","muloqot mahorati","I have well-developed communication skills, as I have been working with customers for over 10 years."],["problem-solving skills","muammolarni hal qilish qobiliyati","My previous job as an accountant helped me develop my problem-solving skills."],["organization skills","tashkilotchilik","At Nestle I organized meetings with partners, which helped me cultivate my organization skills."]]},{"t":"p","x":"Boshqa qobiliyatlar: _critical thinking, teamwork, computer skills, business management, time management, leadership, sales and marketing, language skills._"},{"t":"h3","x":"Namuna: maqsad va asosiy qism"},{"t":"task","situation":"During a recent train journey, you sat next to a businesswoman who owns a chain of hotels. You talked to her and she suggested that you should contact her about a possible job opening in one of her hotels.","to":"Write a letter to this businesswoman. In your letter:","bullets":["remind her when and where you met","tell her what kind of job you are interested in","say why you think you would be suitable for the job"]},{"t":"model","title":"Sample","x":"Dear Ms Bakhromova,\n\nI am writing to express my interest in the position of sales manager at one of the \"Belek\" hotels owned by your organization.\n\nMy name is Alisher and we met last week on the train from Tashkent to Samarkand, on a late Sunday afternoon. We sat next to each other and you told me in detail about your hotels. Then, we exchanged business cards and you told me about a job vacancy in a new boutique hotel.\n\nAs I told you during our journey, I hold a degree from Singapore Management University with a significant background in Tourism and Hospitality. Currently, I am employed as an Assistant Manager at \"Nur\" hotel and I have been working in the tourism industry for more than 5 years. My responsibilities encompass managing hotel staff, addressing client concerns, and making plans for future development. Therefore, I am eager to contribute to the future growth of your new hotel as a sales manager.\n\nI consider myself to be a punctual, hard-working, and outgoing person. Experience from my previous roles has helped me develop my problem-solving and communication skills.\n\nI would be pleased to supply you with any further information during the interview.\n\nYours sincerely,\nAlisher Juraev"},{"t":"h","x":"Ishdan bo'shash xati: tuzilishi va iboralar"},{"t":"phr","title":"Introduction","items":["I am writing to formally announce my resignation from my position as … at … (company name).","I am writing to inform you of my decision to resign from my role as … at … (company name)."]},{"t":"phr","title":"Expressing gratitude — olgan tajribangiz uchun tashakkur","items":["I want to begin by expressing my sincere gratitude for…","I am truly grateful for the invaluable experiences and opportunities I have had at…","I want to express my profound appreciation for the support and guidance I have received while working at…","Precisely, while working at your company, I have gained valuable experience in…"]},{"t":"phr","title":"Expressing the reason for leaving","items":["The reason for leaving my current position is that…","Recently, I have been offered an exciting opportunity to work at… (new company name)"]},{"t":"note","x":"Biror muammo tufayli bo'shayotgan bo'lsangiz ham, sababni samimiy va muloyim ohangda yozing."},{"t":"phr","title":"Asking for a reference — tavsiyanoma so'rash","items":["I would really appreciate it if you could provide me with a letter of reference for my new employer.","I will require a letter of reference from you, which I need to provide when joining the new workplace.","Would you kindly send me a letter of recommendation, as it is compulsory for applying for a new job?"]},{"t":"phr","title":"Complimentary close","items":["I am excited about the next chapter in my career and am confident that … will continue to thrive and excel.","I sincerely wish … ongoing success and growth in the years to come.","Thank you for your support throughout the years, and I wish the company the best of luck in its future endeavours."]},{"t":"task","label":"Ishdan bo'shash topshirig'i","situation":"You have decided to resign from your work in order to try a new field.","to":"Write a letter of resignation to your boss. In your letter:","bullets":["tell your boss of your decision and explain why you are leaving","explain what you have learnt from your current job and how you feel about leaving","ask for a letter of reference"]},{"t":"model","title":"Sample","x":"Dear Mr John,\n\nI am writing to formally announce my resignation from my position as a sales manager at Nestle company.\n\nI am truly grateful for the invaluable experiences and opportunities I have had at Nestle. Precisely, while working at your company, I have gained valuable experience in leadership through the sales manager position that I have held for several years. I was also able to enhance my communication skills by interacting with others in the organization. Additionally, working with international companies helped to broaden my horizons in terms of cultural differences between nations.\n\nI would really appreciate it if you could provide me with a letter of reference for my new employer. Specifically, it should include my relevant experience and roles throughout this period, as well as my key skills.\n\nI sincerely wish Nestle company ongoing success and growth in the years to come.\n\nYours faithfully,\nMalak"},{"t":"ex","no":"9.1","q":"Gaplarning uslubiy muammolarini toping va ishga topshirish xatiga mos qilib qayta yozing.","kind":"write","items":[{"q":"Hey there! I'm writing to apply for the Marketing Manager position. I'm really excited about it!","sample":"I am writing to express my interest in the Marketing Manager position, and I am excited about the opportunity."},{"q":"I need this job badly. Can you please consider me for the Sales Associate role?","sample":"I am writing to express my interest in the Sales Associate role, and I would appreciate your consideration."},{"q":"I want to work at your company because it seems cool and the job pays well.","sample":"I am interested in working at your esteemed company due to its positive reputation and competitive compensation."},{"q":"Hey, I'm a software wizard! I can do wonders if you hire me for the IT job.","sample":"I am a skilled software professional with a strong track record. I believe I can contribute effectively to your IT team."},{"q":"Hi, I came across your job posting and would like to express my interest in the Finance Manager position.","sample":"I recently came across your job posting and would like to express my interest in the Finance Manager position."},{"q":"Hey, I don't have much experience, but I need a job. Can you hire me as your assistant?","sample":"While I may not have extensive experience, I am eager to contribute and learn in the role of your assistant."},{"q":"To whom it may concern, I'm interested in the Human Resources role at your organization.","sample":"I am writing to express my interest in the Human Resources role within your organization."}]},{"t":"ex","no":"9.2","q":"Gaplarni ingliz tiliga o'giring.","kind":"write","items":[{"q":"Hozirda Murad Buildings kompaniyasida grafik dizayner sifatida ishlayman.","sample":"Currently, I am employed as a graphic designer at Murad Buildings company."},{"q":"Men yaqinda Vestminster universitetini tamomlaganman va xalqaro iqtisod bo'yicha katta bilimga egaman.","sample":"I am a recent graduate of Westminster University, and I have a significant background in international economics."},{"q":"Mening vazifalarim talabalarga fransuz tilida yozish va gapirishni o'rgatishni o'z ichiga oladi.","sample":"My responsibilities encompass teaching students to write and speak in French."},{"q":"Men Cambridge universitetidagi Xalqaro biznes boshqaruvi kursini muvaffaqiyatli tamomlaganman.","sample":"I have successfully completed a course in International Business Management at Cambridge University."},{"q":"Men o'zimni punktual, ochiqko'ngil va mehnatsevar deb bilaman.","sample":"I consider myself to be punctual, outgoing and hard-working."},{"q":"Menda kuchli muloqot, qaror qabul qilish va muammoni hal qilish ko'nikmalari bor.","sample":"I have strong communication, decision-making and problem-solving skills."},{"q":"Ofitsiant sifatidagi oldingi ishim muloqot va tashkilotchilik qobiliyatlarimni rivojlantirishga yordam berdi.","sample":"My previous job as a waiter helped me develop my communication and organizational skills."},{"q":"Men Akfa kompaniyasida muhandis yordamchisi lavozimidan iste'foga chiqqanimni rasman e'lon qilish uchun yozyapman.","sample":"I am writing to formally announce my resignation from my position as an assistant engineer at AKFA company."},{"q":"Hozirgi lavozimimni tark etishimga sabab — xalqaro kompaniyadan yordamchi menejer lavozimiga ajoyib ish taklifini oldim.","sample":"The reason for leaving my current position is that I have received an excellent job offer from an international company for the position of Assistant Manager."},{"q":"Artel kompaniyasiga kelgusi yillarda davomiy rivojlanish va muvaffaqiyat tilab qolaman.","sample":"I sincerely wish Artel ongoing success and growth in the years to come."}]},{"t":"ex","no":"9.3","q":"Berilgan so'zlar bilan xatni to'ldiring.","intro":"**Vaziyat:** You recently noticed a local restaurant that was offering a part-time job. Write a letter to the restaurant's manager: explain that you would like to apply for the job; give some details of any relevant experience that you have; specify the days and times that would suit you.","kind":"fill","bank":["staff","should","description","eager","communication","position","additionally","manage","encompass"],"text":"Dear Sir or Madam,\n\nI am writing to express my interest in the {1} of a chef advertised on the local village board.\n\nI noticed from the job {2} that you require someone who can both cook in a creative and healthy way, and who can communicate with and {3} staff in an effective manner. As you can see from my CV, I have been working as an assistant chef for the past 2 years at Brew's restaurant in London. My responsibilities {4} preparing all the dishes on the restaurant's menu and coming up with inventive recipes to present to the head chef. {5}, I am also personally very interested in healthy living and this is always reflected in how I cook. I was responsible at Brew's for managing the cleaning and serving {6} at the restaurant, in which capacity I was able to build good working relationships with all the staff in my responsibility. My time at Brew's restaurant cultivated my {7} and organization skills.\n\nI am {8} to contribute to the growth and success of your restaurant. My preferred days for working would be Monday, Wednesday and Friday afternoons and evenings.\n\n{9} you have any questions, feel free to contact me at any time.\n\nYours faithfully,\nMarjona","a":["position","description","manage","encompass","additionally","staff","communication","eager","should"]},{"t":"p","x":"**9.4.** To'liq ishga topshirish va ishdan bo'shash xatlari — **Yozish xonasi**da."}],"writes":17},{"task":1,"no":10,"title":"Condolence letters","uz":"Hamdardlik maktubi","pages":"76–83","blocks":[{"t":"p","x":"**Hamdardlik maktubi** tanishingizning yaqin qarindoshi olamdan o'tganda, uy hayvoni o'lganda, muhim imtihondan yiqilganda yoki shunga o'xshash yo'qotishlarda tasalli berish uchun yoziladi. U asosan uch qismdan iborat:"},{"t":"list","ordered":true,"items":["Hamdardlik bildirish","Vafot etgan inson (yoki hayvon) haqida iliq xotiralar","Qo'llab-quvvatlash sifatida yordam taklif qilish"]},{"t":"task","label":"Namuna topshiriq","situation":"Your friend's dog has recently passed away.","to":"Write a letter to console your friend. In your letter:","bullets":["express your sympathy","include memories you have about the dog","invite your friend to do something with you."]},{"t":"table","head":["So'z","Tarjima","Misol"],"rows":[["condolence / offer condolences","hamdardlik / hamdardlik bildirmoq","Famous people from all over the world came to offer their condolences."],["pass away","vafot etmoq (die'ning muloyim shakli)","She's terribly upset because her father passed away last week."],["console","yupatmoq, taskin bermoq","I tried to console her with a box of chocolates."],["loss","yo'qotish","I was sorry to hear about the loss of your brother."],["grieve / grief","qayg'urmoq / qayg'u","He is still grieving for his wife."],["sadden","xafa qilmoq","I was deeply saddened to hear about Jacob's passing."],["sympathy","hamdardlik","I went to the funeral to express my sympathies."],["sorrow","g'am, alam","The sorrow she felt over the death of her husband was almost too much to bear."],["reminisce","o'tmishdagi yaxshi xotiralarni eslash","My grandfather used to reminisce about his years in the navy."]]},{"t":"h3","x":"Tone"},{"t":"p","x":"Hamdardlik maktubi odatda **rasmiy** — bu jiddiy mavzu, rasmiy uslub qayg'udagi insonga hurmat va hamdardlikni yetkazadi. Qabul qiluvchi juda yaqiningiz bo'lsa, norasmiy ham bo'ladi."},{"t":"h3","x":"Purpose"},{"t":"phr","items":["I'm writing to express my sorrow after the death of your sister.","I am so sorry to hear that Uncle Brad has passed away.","I was deeply saddened to hear about Tom's passing.","I'm incredibly sorry to hear that Scott has passed.","I'm reaching out to let you know how sorry I am about Joe.","I am grieved to hear the sad news about the death of your mother."]},{"t":"note","x":"Maktubda marhumning ismini kamida bir marta keltiring — bu hamdardlikni ta'sirliroq va samimiyroq qiladi."},{"t":"h3","x":"Bullet 1 — express your sympathy"},{"t":"p","x":"Hamdard ekaningizni, bu damlar og'ir ekanini tushunishingizni va yo'qotilgan inson qadrli bo'lganini ayting."},{"t":"model","x":"I just heard about your dog Jimmy, who passed away last week. My deepest condolences are with you and your whole family. I can understand that he was a member of your family and it is very hard to forget him. (iti o'lgan do'stga)\n\nIt's so difficult to lose a family member. While I never met Levi, I do know the two of you were very close. I do not doubt that his death is very hard for you and the rest of your family. (oila a'zosi vafot etgan do'stga)"},{"t":"phr","items":["It's so difficult to lose a family member.","My deepest condolences are with you and your whole family.","I know it was very unexpected, and I can't imagine what you and Mrs Byrne are going through.","Please accept my heartfelt condolences during this difficult time.","I know that words cannot fully express the pain you are feeling, but I want you to know that I am here for you in any way you may need.","Please accept my most sincere condolences as you navigate through this challenging and devastating time."]},{"t":"h3","x":"Bullet 2 — memories"},{"t":"p","x":"Vafot etgan inson yoki hayvon haqida ijobiy fikrlar: fazilatlari, yaxshi ishlari, yutuqlari. Shaxsan tanimagan bo'lsangiz ham, boshqalardan eshitgan iliq gaplarni keltiring."},{"t":"model","x":"I also have a lot of memories with him from my childhood. You and I used to play with him after coming back from school. We played hide and seek with him and it was really fun in those days. I still remember how he followed our commands like sit and stand — that was incredible. (it)\n\nI only met your dad a few times, but I know he was so proud of you. He was so excited about your recent promotion. He couldn't stop talking about you and everything you have achieved. (ota)\n\nTyrone was more than just a valued member of our team. He was the heart and soul of this office. Whenever anyone needed something, whether it was help with work or to talk through something personal, he was always there. (rahbar xodimining rafiqasiga)"},{"t":"h3","x":"Bullet 3 — offer help / invite"},{"t":"p","x":"Faqat \"Please let me know if I can do anything\" deyish yetarli emas — **aniq** narsa taklif qiling: bolalarini aylantirib kelish, konsertga olib borish, birga o'yin o'ynash."},{"t":"model","x":"I really want you and your family to be strong at this moment and, if possible, I would like you to come to my place to take your mind off things. We'll play cricket this Sunday — I hope you find time to come.\n\nI understand that you're taking a break from teaching while you grieve. If you feel up for having visitors, I'd love to come by. If you think it would help you to talk about Cameron, I'd be happy to hear more stories about him."},{"t":"phr","items":["If there's anything I can do to offer support or comfort, please do not hesitate to reach out.","Whether you need a listening ear, someone to help with daily tasks, or simply a distraction, please don't hesitate to reach out.","Remember that you are not alone and that you have friends and family who care about you deeply."]},{"t":"h3","x":"Closing remarks"},{"t":"table","head":["Formal","Informal"],"rows":[["Cordially, / Sincerely,","All my love, / Love you always,"],["My sincerest condolences,","All the best,"],["Our condolences for this tragic loss.","Again, I'm so sorry for your loss."]]},{"t":"ex","no":"10.1","q":"Har bir holat bo'yicha bir gapdan iborat hamdardlik bildiring.","kind":"write","items":[{"q":"To your friend who has recently lost his mother.","sample":"I was deeply saddened to learn of your mother's passing."},{"q":"To a coworker who has lost his pet.","sample":"I'm incredibly sorry to hear about the loss of your beloved pet."},{"q":"To your neighbour who has lost her sibling in a tragic accident.","sample":"I'm writing to express my sorrow after the death of your beloved sibling."},{"q":"To a family member whose best friend has passed away.","sample":"I am so sorry to hear that your best friend has passed away."},{"q":"To a classmate who has lost his grandfather.","sample":"I was deeply saddened to learn about the passing of your grandfather."},{"q":"To a distant relative who has lost his spouse.","sample":"I am grieved to hear the sad news about the death of your beloved spouse."},{"q":"To your professor who has lost his father.","sample":"I'm reaching out to let you know how sorry I am about your father."},{"q":"To a friend who has lost her job due to company downsizing.","sample":"I was deeply sorry to learn about the loss of your job."},{"q":"To a colleague who has lost a close friend to an illness.","sample":"I was deeply saddened to hear about the loss of your dear friend."},{"q":"To a neighbour who has lost his home in a fire.","sample":"I am so sorry to hear that your house was devastated by fire."}]},{"t":"ex","no":"10.2","q":"Iboralarga mos izohni toping.","kind":"match","opts":[{"k":"a","x":"Offering support and assistance."},{"k":"b","x":"Expressing sorrow and sympathy."},{"k":"c","x":"Hoping you find the courage to cope."},{"k":"d","x":"Sharing heartfelt feelings of grief."}],"items":[{"q":"My thoughts are with you.","a":"d"},{"q":"Please accept my condolences.","a":"b"},{"q":"I am here for you.","a":"a"},{"q":"Wishing you strength and comfort.","a":"c"}]},{"t":"ex","no":"10.3","q":"Gaplarni ingliz tiliga o'giring.","kind":"write","items":[{"q":"Sizning otangiz atrofdagilarga juda ko'p quvonch keltirgan ajoyib inson edi.","sample":"Your father was a wonderful person who brought so much joy to those around him."},{"q":"Siz va oilangiz doimo mening o'ylarim va duolarimdasiz.","sample":"My thoughts and prayers are with you and your family."},{"q":"Agar sizga dardlaringizni eshitadigan va o'tgan yaxshi kunlarni eslashadigan kimdir kerak bo'lsa, men shu yerdaman.","sample":"If you need a listening ear or someone to reminisce with, I am here for you."},{"q":"Ushbu qayg'uli davrda samimiy hamdardligimni qabul qiling.","sample":"Please accept my heartfelt condolences during this time of sorrow."},{"q":"Oilangizdagi yo'qotish uchun chuqur hamdardman.","sample":"My deepest sympathy for the loss in your family."}]},{"t":"p","x":"**10.4.** To'liq hamdardlik xatlari — **Yozish xonasi**da."}],"writes":15},{"task":1,"no":11,"title":"Task achievement","uz":"Topshiriq talablarini bajarish (baholash mezoni)","pages":"84–92","blocks":[{"t":"p","x":"**Task achievement** — Writing bo'limining baholash mezonlaridan biri: topshiriq qanchalik to'g'ri va to'liq yoritilganini baholaydi. Yuqori natija uchun 5 narsa muhim:"},{"t":"list","items":["**Content relevance** — javob topshiriqqa taalluqli bo'lishi","**Right tone** — to'g'ri uslub (rasmiy / norasmiy)","**Completeness** — topshiriqning barcha bandlarini to'liq qamrab olish","**Clarity and coherence** — aniq va tizimli matn","**Word limit** — kamida 150 so'z"]},{"t":"h","x":"1. Javob topshiriqqa taalluqli bo'lishi"},{"t":"p","x":"Topshiriq nima haqida yozish kerakligini aniq ko'rsatadi — undan chetga chiqmang. Quyidagi topshiriq va turli darajadagi javoblarni solishtiring:"},{"t":"task","situation":"You were recently disrespected by one of the employees at your local supermarket.","to":"Write a letter to the supermarket manager. In your letter:","bullets":["tell him/her why you were speaking with the employee","describe the employee's rude behaviour","explain what you'd like the manager to do"]},{"t":"h3","x":"Bullet 1 — nega xodim bilan gaplashdingiz?"},{"t":"model","title":"B1 dan past","x":"I have shopped at your supermarket every weekend for the past 6 years as your prices are reasonable and I am satisfied with the range of products which you stock. But, unfortunately, last weekend, I was shocked by the rude language that one of your staff members used while speaking to me."},{"t":"p","x":"**Izoh:** paragraf savolga umuman javob bermaydi — nega xodim bilan gaplashganingiz aytilmagan. B1 dan past ishlarda ma'lumot topshiriqqa bog'liq bo'lmaydi."},{"t":"model","title":"C1","x":"While at your supermarket last Tuesday, I was unable to reach a box of cereal from the top shelf, and there weren't any staff members or other customers in the aisle who I could ask for help. For this reason, I asked for assistance from a female employee in the nearby bakery section of your supermarket."},{"t":"p","x":"**Izoh:** ikkala gap ham to'g'ridan-to'g'ri savolga javob beradi, ortiqcha ma'lumot yo'q."},{"t":"h3","x":"Bullet 2 — xodimning qo'pol xatti-harakati"},{"t":"model","title":"B2","x":"Instead of answering my question, your employee just laughed at me. I am very upset by this rude behaviour, and I believe that I deserve more respect while shopping at your supermarket. Even if the employee couldn't help me, they should at least have the decency to answer my question."},{"t":"p","x":"**Izoh:** faqat birinchi gap savolga javob beradi, qolgani yozuvchining hissiyotlari. B2 dan yuqori uchun **barcha gaplar** savol so'ragan ma'lumot haqida bo'lishi kerak."},{"t":"model","title":"C1","x":"This person's response was incredibly inappropriate and is the reason I am writing this letter. At first, she stared into my eyes without saying anything, after which she laughed under her breath and walked away. At this point, she began pointing in my direction while whispering to another member of staff in the bakery."},{"t":"h3","x":"Bullet 3 — menejer nima qilishi kerak"},{"t":"model","title":"C1","x":"I'm highly insulted by this conduct for obvious reasons, and I wish to be sent a letter of apology directly from that staff member. On that day, it seemed as though this was the only female employee in the bakery, which is why I'm confident that you will easily identify the person in question, and furthermore, I expect to hear from her within the next week."},{"t":"h","x":"2. To'g'ri uslub"},{"t":"p","x":"Do'stga — norasmiy, notanishga — rasmiy. Mazmun to'g'ri bo'lsa ham, uslub noto'g'ri bo'lsa, baho keskin tushadi; uslub xatolari ko'p bo'lsa, natija B1 dan ham pastga tushishi mumkin. Grammatik strukturalar qanchalik uzun bo'lsa, gap shunchalik rasmiy bo'ladi:"},{"t":"table","head":["Formal","Informal"],"rows":[["I am afraid that I won't be able to attend your party.","I can't go to your party."],["I think it would be a good idea if you started to do some regular exercise.","You should do more exercise."]]},{"t":"note","x":"Butun xat davomida faqat bitta uslub. Bir xatda ham rasmiy, ham norasmiy uslub ishlatish — katta xato."},{"t":"h","x":"Ko'p uchraydigan xatolar"},{"t":"list","ordered":true,"items":["**Missing key points** — barcha tayanch savollarga javob bermaslik (masalan, _describe a problem, explain its impact, suggest a solution_ dan bittasini tushirib qoldirish).","**Going off-topic** — topshiriqqa aloqasiz ma'lumot yozish.","**Insufficient detail** — juda qisqa javob: _There's a problem at my workplace_ — tafsilotsiz, savol yoritilmagan.","**Lack of clarity** — o'quvchini chalkashtiradigan darajada noaniq yozish: haddan tashqari murakkab grammatika yoki kasbiy jargon.","**Word limit** — 150 so'zdan kam yozsangiz, jarima qo'llaniladi."]},{"t":"ex","no":"11.1","q":"Xatdagi uslub bilan bog'liq muammolarni toping va 4-paragrafni (Finally…) xat uslubiga mos qilib qayta yozing.","kind":"write","items":[{"task":{"situation":"You have seen an advertisement for a special offer at a beautiful tourist resort. You would like to book a holiday.","to":"Write a letter to the travel company. In your letter","bullets":["say when you would like to arrive and leave","describe the type of accommodation you require","ask for some more information about some activities you are interested in"]},"given":"Dear Sir or Madam, I saw your advertisement for a two-week holiday in Tasmania in Cheap and Cheerful Holiday Magazine and I would like to have information on the issues below. First, I really hope that the special offer is still valid for the school holidays from 8 to 21 July, as this is the only time that it is possible for us to get away. Second, in your advertisement you have forgotten to say what type of accommodation you are offering. I would like to know if you have anything suitable for a party of ten people. Furthermore, would it be possible for you to inform me whether any of the cabins have wheelchair access? **Finally, we would like to go sailing, as my son loves boats and wants to be a sailor when he grows up. Is it possible to hire a boat?** I look forward to your response and hope to see you in the near future. Yours faithfully","rows":5,"sample":"First, I would like to know if the special offer is still available during the school holidays from 8 to 21 July. Secondly, could you send me details of the type of accommodation you offer? Finally, we would like to go sailing and wonder if it is possible to book a boat from the resort. (Muammolar: \"I really hope\" — juda hissiyotli; \"you have forgotten\" — ayblovchi ohang; o'g'il haqidagi ma'lumot ortiqcha; to'g'ridan-to'g'ri savol o'rniga muloyim so'rov kerak.)"}]},{"t":"ex","no":"11.2","q":"Qavs ichidagi ko'rsatmalardan foydalanib, xatni to'liq yozing.","kind":"write","items":[{"task":{"situation":"You have bought some clothing online and are not satisfied with your purchase.","to":"Write a letter to the company that you bought clothing from. In your letter:","bullets":["give details of the purchase","describe the problem","explain why you need a replacement urgently"]},"given":"Dear Sir or Madam, I am writing to express my dissatisfaction with the suit that I purchased from your online store and to request a prompt replacement. On 25th of January, I ordered a black suit size 58 and a white shirt size XXL from your online store. (Narxi qancha edi va necha kunda yetkazib berishni va'da qilishgan.) However, upon receiving the order and opening it, I immediately noticed a problem with the colour and size of the suit. (Qora o'rniga boshqa rang, o'lcham kichik; oq ko'ylakda katta dog'.) I kindly request you to make an urgent replacement because I was expecting to wear these clothes for the wedding of my brother. (Menejer qayta jo'natishda rang va o'lchamni shaxsan tekshirsin.) I look forward to your swift resolution… Yours faithfully, Nodirbek","rows":8,"sample":"Dear Sir or Madam,\n\nI am writing to express my dissatisfaction with the suit that I purchased from your online store and to request a prompt replacement.\n\nOn 25th of January, I ordered a black suit size 58 and a white shirt size XXL from your online store. The total price of the suit and white shirt was $165 and the order was supposed to be delivered directly to my house within 3 days.\n\nHowever, upon receiving the order and opening it, I immediately noticed a problem with the colour and size of the suit. After taking the items out of the box, I realized that there was a brown suit instead of a black one, and the size was also much smaller than expected. Furthermore, I felt greatly frustrated to find a big stain on the front of the white shirt.\n\nI kindly request you to make an urgent replacement because I was expecting to wear these clothes for my brother's wedding. Moreover, it would be greatly appreciated if you inspected the details of the replacement personally so that the mistake would not be repeated.\n\nI look forward to your swift resolution, and I trust that you will continue to provide excellent customer service.\n\nYours faithfully,\nNodirbek"}]},{"t":"ex","no":"11.3","q":"Xatdagi ortiqcha (topshiriqqa aloqasiz) ma'lumotlarni olib tashlab, qayta yozing.","kind":"write","items":[{"task":{"situation":"Write a letter to your friend from a different country. Invite him/her to a party at your home.","to":"Include the following:","bullets":["what the party is about","give directions on how to get to your place","suggest how to accommodate him/her"]},"given":"Dear Dilshod, I am writing to invite you to a party I'm going to have at my home on March 12. I'm planning to celebrate my championship in the Asian boxing tournament with my close friends like you. The party is planned to start with a chess tournament at 3 o'clock and this should take a maximum of three hours. After that I've got some mates coming over who will play some good music and so on. It was very difficult to gain the Asian championship because I had to fight against the most talented boxers from more than 15 countries. As you have visited my home before I assume you remember how to find it. However, in case you don't, I'll give you some directions. The public transport system has been developed and one doesn't have to wait too much for a bus or a tram. Just after you've passed the Railway station, there is a bus stop before the junction on the right. Then go along the same street for about 100 metres and you should see my house at 67 Mitchell Street. As I've got plenty of free space in my house you don't need to worry about accommodation. I can keep a room for you. I have renovated my house since your last visit. Now, the living room is much bigger and I bought an expensive TV and sofa. By the way, if you prefer to stay in a hotel, don't book it in advance without warning me since my uncle has recently bought the one in our local area, and I will accommodate you there. I look forward to your reply! Best wishes, Feruzbek","rows":8,"sample":"Olib tashlanadigan gaplar:\n1) \"It was very difficult to gain the Asian championship because I had to fight against the most talented boxers from more than 15 countries.\"\n2) \"The public transport system has been developed and one doesn't have to wait too much for a bus or a tram.\"\n3) \"I have renovated my house since your last visit. Now, the living room is much bigger and I bought an expensive TV and sofa.\"\nBu gaplar tayanch savollarga javob bermaydi — ular partiya mavzusi, yo'l ko'rsatish yoki joylashtirish haqida emas."}]},{"t":"ex","no":"11.4","q":"Rasmiy gaplarni norasmiy uslubga aylantiring.","kind":"write","items":[{"q":"I am writing to express my interest in your advertised job position.","sample":"I'm writing because I'm interested in the job you advertised."},{"q":"I would like to kindly request some information about your company's products.","sample":"Can you tell me more about your company's products?"},{"q":"I am pleased to inform you that I have successfully completed the required training.","sample":"Great news — I've completed the required training!"},{"q":"Please be advised that your payment is overdue.","sample":"Hey, your payment is overdue."},{"q":"I regret to inform you that I am unable to attend the scheduled meeting.","sample":"Sorry, I can't make it to the meeting."},{"q":"I am writing to inquire about the availability of your services.","sample":"Just wondering if you have those services available."},{"q":"I wish to inform you that I have received your letter.","sample":"Got your letter, thanks!"},{"q":"I would like to request your assistance in this matter.","sample":"Mind helping me out with this?"},{"q":"I am writing to request a formal response to my previous letter.","sample":"Can you get back to me about my last letter?"},{"q":"I would appreciate it if you could provide me with more details about your event.","sample":"Could you give me more info about your event?"}]}],"writes":13},{"task":1,"no":12,"title":"Coherence and cohesion","uz":"Bog'lanish va matn yaxlitligi (baholash mezoni)","pages":"93–101","blocks":[{"t":"p","x":"**Coherence and Cohesion** — matn qanchalik oson va aniq tushunilishini baholaydigan mezon."},{"t":"h","x":"1. Coherence — mantiqiy izchillik"},{"t":"p","x":"Fikrlarning mantiqiy ketma-ketlikda, aniq va tizimli joylashuvi. Har bir xat uch qismdan iborat: **salomlashish va maqsad** → **vaziyat haqida ma'lumot** (uchta tayanch savol) → **uslubga mos xayrlashish**."},{"t":"h3","x":"1.1. Paragraflar"},{"t":"p","x":"Xat albatta paragraflarga bo'linadi va har birida **bitta** tayanch savolga javob beriladi. Masalan, quyidagi topshiriqda birinchi paragrafda qo'llanma (guidebook) haqida hech narsa yozilmaydi — u ikkinchi paragrafda."},{"t":"task","situation":"You recently went on a foreign holiday and borrowed a guidebook about your destination from your friend.","to":"Write a letter to your friend. In your letter","bullets":["describe your holiday to him/her","tell him/her why the guidebook was useful","make arrangements to return the book"]},{"t":"h3","x":"1.2. Progression — rivojlantirish"},{"t":"p","x":"Gaplar bir-biriga mantiqan bog'lanadi; har bir paragraf o'rtacha **~60 so'z**. Har bir gap **yangi ma'lumot** qo'shishi kerak — bir fikrni takrorlash ballni tushiradi."},{"t":"model","title":"Yomon rivojlantirilgan","x":"Vietnam is the most beautiful country. All the places that I went to were stunning, and the scenery was incredible. I saw so many amazing things, and I really couldn't believe my eyes with many of the sights that I saw there. The landscape was just out of this world."},{"t":"p","x":"**Izoh:** faqat birinchi gapda ma'lumot bor, qolganlari uni boshqacha so'zlar bilan takrorlaydi."},{"t":"model","title":"Yaxshi rivojlantirilgan","x":"I just got back from my trip to Paris, and it was as impressive as you described. I spent a lot of time visiting all the typical tourist attractions, which never failed to amaze me, and I also rambled around the back streets to see what other exciting things I might find. I must say, it's definitely the most unique and fascinating place I've ever been."},{"t":"h","x":"2. Cohesion — bog'lanish vositalari"},{"t":"h3","x":"2.1. Linking words"},{"t":"p","x":"Bog'lovchilar (_also, but, however, because, for example, therefore_) o'quvchiga ketma-ketlikni kuzatishga yordam beradi. Xilma-xil bog'lovchilarni o'z o'rnida ishlating."},{"t":"table","head":["Bog'lovchisiz","Bog'lovchi bilan"],"rows":[["I finished work. I went to the shop. I went home.","After I'd finished work, I went to the shop before going home."],["I didn't buy any milk. I didn't have enough money.","I didn't buy any milk because I didn't have enough money."]]},{"t":"model","title":"Do'stga — norasmiy bog'lovchilar","x":"Your guidebook was very useful, too, especially because the list of translated phrases meant that I could interact with the locals. Also, one time, I got completely lost, and it wasn't until I remembered the map in the guidebook that I found my way back to the hotel."},{"t":"model","title":"Rahbarga — rasmiy bog'lovchilar","x":"Furthermore, your guidebook was very useful, particularly as the list of translated phrases allowed me to interact with the locals. In addition, one time, I got completely lost, and it was only once I'd remembered the map in the guidebook that I found my way back to the hotel."},{"t":"h3","x":"2.2. Referencing — olmoshlar bilan qaytarish"},{"t":"p","x":"Takrordan qochish uchun olmoshlardan foydalaning: _I wasn't able to hand in my homework because the dog ate **it**._ / _…because I am washing my hair. I have to do **this** on **that** night…_\nNoto'g'ri: _Thanks for letting me borrow your guidebook. The guidebook was very useful._ → To'g'ri: _…**It** was very useful._ / _I'll definitely bring **one** on my holidays from now on._"},{"t":"h3","x":"2.3. Paraphrasing and substitution"},{"t":"p","x":"Ma'noni saqlab, so'z va grammatik tuzilishni almashtiring: _leave → depart, replace → change, additionally → also; I am unable to attend on this date → I am unavailable at this time._"},{"t":"ex","no":"12.1","q":"Gaplarni xatning qaysi paragrafiga tegishli ekanini belgilang (izchil xat tuzing).","intro":"**Topshiriq:** You are going on holiday. Write a letter to a friend asking him or her to look after your house: explain the situation; tell your friend what needs to be done while you are away; arrange to meet your friend before you go. **Paragraf 1** — vaziyat (2 gap), **2** — so'rov tafsilotlari (4 gap), **3** — uchrashuv (2 gap), **4** — xayrlashuv (1 gap).","kind":"match","opts":[{"k":"1","x":"Paragraph 1"},{"k":"2","x":"Paragraph 2"},{"k":"3","x":"Paragraph 3"},{"k":"4","x":"Paragraph 4"}],"items":[{"q":"I would really appreciate it if you could look after the house.","a":"2"},{"q":"Would it be possible for us to meet on Wednesday so I can give you the keys?","a":"3"},{"q":"I wonder if you could do me a favour while I am away.","a":"1"},{"q":"While you are at the house, it would be good if you could water the garden and take any post out of the mailbox and place it inside.","a":"2"},{"q":"As you know, I am going to England on holiday from next Monday until the 15th of July.","a":"1"},{"q":"If Wednesday is OK, please telephone me as soon as possible.","a":"3"},{"q":"He can get in and out of the house on his own, so all you need to do is leave some food in his bowl.","a":"2"},{"q":"I look forward to seeing you in the next few days.","a":"4"},{"q":"In particular, I would like you to feed the cat.","a":"2"}]},{"t":"ex","no":"12.2","q":"Berilgan bog'lovchilar (although, because, while, since, if, therefore, when, in addition to, despite, whereas) yordamida gaplarni bitta murakkab gapga birlashtiring.","kind":"write","items":[{"q":"The rain was pouring. I decided to go for a walk.","sample":"Although the rain was pouring, I decided to go for a walk."},{"q":"She studied hard. She passed her exams with flying colours.","sample":"She studied hard, so she passed her exams with flying colours. / Because she studied hard, she passed…"},{"q":"They had a busy day at work. They managed to finish all their tasks.","sample":"Although they had a busy day at work, they managed to finish all their tasks."},{"q":"He loves to read books. He also enjoys watching movies.","sample":"He loves to read books, in addition to enjoying watching movies."},{"q":"The traffic was terrible. I arrived at the meeting on time.","sample":"Despite the terrible traffic, I arrived at the meeting on time."},{"q":"She didn't like spinach. She ate her entire plate of spinach.","sample":"Although she didn't like spinach, she ate her entire plate of it."},{"q":"The sun was shining brightly. We decided to have a picnic.","sample":"The sun was shining brightly when we decided to have a picnic. / Since the sun was shining brightly, we decided to have a picnic."},{"q":"She saved money diligently. She could afford a dream vacation.","sample":"She saved money diligently; therefore, she could afford a dream vacation."},{"q":"He was exhausted. He continued working late into the night.","sample":"He was exhausted because he continued working late into the night. / Although he was exhausted, he continued working late into the night."},{"q":"The restaurant was crowded. We managed to find a table quickly.","sample":"While the restaurant was crowded, we managed to find a table quickly."}]},{"t":"ex","no":"12.3","q":"Xatda keragidan ortiq takrorlangan va topshiriqdan to'g'ridan-to'g'ri ko'chirilgan so'zlarni boshqa so'zlar bilan almashtirib, qayta yozing.","kind":"write","items":[{"task":{"situation":"You had a minor accident at work.","to":"Write a letter to your employers. In the letter","bullets":["describe what happened","explain the cause of the accident","state what you think should be done about the situation"]},"given":"Dear Mr Williams, I would like to report an accident that I had leaving work on Friday 21 October. As I was leaving work, I tripped over a raised paving stone just outside the front entrance. I fell over and tore my trousers and cut my knee. Although my cut knee was not serious, it was painful and my trousers were damaged beyond repair. I believe that this accident was caused by problems with the paving stones just outside the front entrance. This may be because tree roots are growing under the paving stones and pushing the paving stones up. I believe that the paving stones need to be replaced if this type of accident is to be avoided in the future. I would also like the company to pay to replace my trousers. Replacing my trousers will cost around $200. I look forward to hearing from you. Yours faithfully, Helen","rows":8,"sample":"Dear Mr Williams,\n\nI would like to report an accident that I had leaving work on Friday 21 October. As I was leaving the office, I tripped over a raised paving stone just outside the front entrance. I fell over and tore my trousers and cut my knee. Although my injury was not serious, it was painful and my trousers were damaged beyond repair.\n\nI believe that this accident was caused by problems with the pavement just outside the front entrance. This may be because tree roots are growing under the paving stones and pushing them up. I feel that the path needs to be replaced if this type of accident is to be avoided in the future.\n\nI would also like the company to pay for the damage to my clothing. Replacing my trousers will cost around $200. I look forward to hearing from you.\n\nYours faithfully,\nHelen"}]},{"t":"ex","no":"12.4","q":"Parchani qisqaroq va ravonroq qilib qayta yozing: ot guruhlarini olmoshlar bilan almashtiring, gaplarni relative clause (which, that, where) bilan birlashtiring.","kind":"write","items":[{"q":"As you know, we are all going on holiday to France in September and we wondered if you would like to join us in France. We are going in September so we can celebrate my birthday on the 13th. We are having a party in a local club. In the local club, there is live music every night. The band is very good. I saw the band in London last summer and was very impressed. We will be staying in an old farmhouse. The farmhouse has eight bedrooms so there will be room for everybody. The farmhouse is close to a beach. The beach has great waves for surfing. The beach is hidden from the road so very few people come to the beach.","rows":7,"sample":"As you know, we are all going on holiday to France in September and we wondered if you would like to join us there. We are going then so we can celebrate my birthday on the 13th. We are having a party in a local club where there is live music every night. The band is very good. I saw them in London last summer and was very impressed.\n\nWe will be staying in an old farmhouse that has eight bedrooms, so there will be room for everybody. It is close to a beach that has great waves for surfing and is hidden from the road, so very few people come there."}]},{"t":"ex","no":"12.5","q":"Xat paragraflarga bo'linmagan. Uni topshiriqqa mos paragraflarga ajratib yozing.","kind":"write","items":[{"task":{"situation":"You play a team sport with some friends. Last week a member of the team had an accident and wasn't able to play with you at the weekend. You decide to write to him in hospital, telling him about the match.","to":"Write a letter to your friend. In your letter,","bullets":["tell him which team won","describe the conditions on the day","say how you felt about the match"]},"given":"Dear Frank, I was so sorry to hear about your accident! I hope you're feeling a lot better today and that it's not too boring in hospital. The match on Saturday was disappointing. The score was 2 all, probably because you weren't there to score that extra goal! The awful thing was that we were winning until 10 minutes before the end, when suddenly they scored another goal. I was so shocked when I saw the ball hit the back of the net. I think the weather was to blame. It was a really wet day and the pitch was very muddy. By the end of the game, you could hardly see the grass and we were sliding around in the mud. Everyone was exhausted. Let us know when you're going home and we'll arrange for someone to bring you to watch the next game. The rest of the team send their regards and we all wish you a speedy recovery. Best wishes, Charlie","rows":10,"sample":"Dear Frank,\n\nI was so sorry to hear about your accident! I hope you're feeling a lot better today and that it's not too boring in the hospital.\n\nThe match on Saturday was disappointing. The score was 2 all, probably because you weren't there to score that extra goal! The awful thing was that we were winning until 10 minutes before the end when suddenly they scored another goal. I was so shocked when I saw the ball hit the back of the net.\n\nI think the weather was to blame. It was a really wet day and the pitch was very muddy. By the end of the game, you could hardly see the grass and we were sliding around in the mud. Everyone was exhausted.\n\nLet us know when you're going home and we'll arrange for someone to bring you to watch the next game. The rest of the team send their regards and we all wish you a speedy recovery.\n\nBest wishes,\nCharlie"}]},{"t":"ex","no":"12.6","q":"Xatda izchillik va bog'lanish muammolari bor. G'oyalar tartibini va gaplar bog'lanishini yaxshilab, qayta yozing.","kind":"write","items":[{"task":{"situation":"You won't be able to hand your assignment in on time.","to":"Write to your lecturer asking for an extension.","bullets":["describe the situation","explain why your assignment will be late","say when you will be able to hand in your assignment"]},"given":"Dear Mr Murray, I am sorry for any inconvenience caused but my mother has had a heart attack. I have to fly back to China as soon as possible. I do not know when I will be leaving because I am on a stand-by flight. I also do not know when I will be coming back. My Geography assignment is due on the 14th of September so I will not be able to hand it on that date. Could you let me know as soon as possible whether I can have an extension? I believe that I will be away for two weeks at most. I think that I will be able to do some work while I am in China. However, I will almost certainly need an extension on my assignment. Please could you give me permission to hand it in on the 21st of September? This would be one week later than expected. Yours sincerely, John","rows":10,"sample":"Dear Mr Murray,\n\nI am sorry to have to tell you that I will be unable to hand in my Geography assignment due on the 14th of September.\n\nUnfortunately, my mother has had a heart attack and I have to fly back to China to see her as soon as possible. At the moment I am on stand-by for the next available flight, so I do not know when I will be leaving or when I will be coming back.\n\nI believe that I will be away for two weeks at the most, and I think that I will be able to do some work while I am in China. However, I will almost certainly need an extension on my assignment. Please could you give me permission to hand it in on the 21st of September? This would be one week later than expected.\n\nCould you let me know as soon as possible whether I can get an extension? I am sorry for any inconvenience I have caused.\n\nYours sincerely,\nJohn"}]}],"writes":14},{"task":1,"no":13,"title":"Lexical resource","uz":"Lug'at boyligi (baholash mezoni)","pages":"102–107","blocks":[{"t":"p","x":"**Lexical resource** — ingliz tilidagi lug'at boyligingizni qanchalik samarali va rang-barang ishlata olishingizni baholaydi. Ikki omil muhim: so'zlarni **to'g'ri** va **rang-barang** ishlatish."},{"t":"h3","x":"So'z shakli va so'z tanlash"},{"t":"p","x":"Ko'p uchraydigan xato — bir so'z turkumi o'rniga boshqasini ishlatish:\n✗ _I am interesting in the course._ → ✓ _I am interested in the course._\nBunday xato tushunarli bo'ladi. Ammo butunlay boshqa so'z ishlatilsa, ma'no buziladi — bu qo'pol xato:\n✗ _I would like to appreciate for the noise I made yesterday._ → ✓ _I would like to apologize for the noise I made yesterday._"},{"t":"h3","x":"Collocations — so'z birikmalari"},{"t":"p","x":"So'zlarning o'zaro tabiiy birikishi: _test paper, test day, final test, **take** a test_. ✗ _Yesterday, I gave my final test._ → ✓ _Yesterday, I took my final test._\n✗ _I pedal my bicycle to work._ → ✓ _I ride my bicycle to work._ / _I cycle to work._"},{"t":"h3","x":"Clear communication"},{"t":"p","x":"Ma'nosini yaxshi bilmaydigan, lekin \"zo'r\" deb o'ylagan so'zni ishlatmang. ✗ _The new resort has had a beneficial consequence on local businesses._ → ✓ _The new resort has had a beneficial effect on local businesses._ (**consequence** odatda salbiy oqibatlar uchun ishlatiladi)."},{"t":"h3","x":"Spelling — imlo"},{"t":"list","items":["Bir-ikkita imlo xatosi bahoga jiddiy ta'sir qilmaydi, lekin tez-tez takrorlansa, baho pasayadi.","Qo'lda yozgan xatingizni Word'ga ko'chiring — imlo xatolari qizil chiziq bilan ko'rinadi; ularni o'rganing.","Daftarda \"Difficult spelling\" sahifasini oching va qiyin so'zlarni yozib, takrorlab boring.","Husnixat yomon bo'lsa va matnni o'qish qiyin bo'lsa, baho pasayadi."]},{"t":"h3","x":"Range — mavzuga oid lug'at"},{"t":"p","x":"Masalan, uy ijarasi mavzusida: _rent, rental, accommodation, interior design, kitchen appliances, energy bills_. Quyidagi mavzular bo'yicha yetarli lug'atga ega bo'ling:"},{"t":"list","items":["Turar joy (ijara, santexnika muammolari)","Ishga kirish (rezyume, malaka, qobiliyat)","Sayohat (poyezdda narsa yo'qotish, mehmonxonani tasvirlash)","Tadbirlarga taklif (to'y, bazm)","Iltimoslar","Minnatdorchilik","Shikoyat","Fikr bildirish"]},{"t":"ex","no":"13.1","q":"Har bir so'z qaysi xat turiga mos?","kind":"match","opts":[{"k":"A","x":"Application"},{"k":"B","x":"Apology"},{"k":"C","x":"Complaint"},{"k":"D","x":"Enquiry"},{"k":"E","x":"Recommendation"},{"k":"F","x":"Thanks"},{"k":"G","x":"Condolence"}],"items":[{"q":"apologise","a":"B"},{"q":"grief","a":"G"},{"q":"heartfelt","a":"G"},{"q":"grateful","a":"F"},{"q":"propose","a":"E"},{"q":"unhappy","a":"C"},{"q":"applicant","a":"A"},{"q":"be considered","a":"A"},{"q":"dissatisfied","a":"C"},{"q":"help","a":"D"},{"q":"sorry","a":"B"},{"q":"wonder","a":"D"},{"q":"appreciate","a":"F"},{"q":"excuse","a":"B"},{"q":"interview","a":"A"},{"q":"suggest","a":"E"},{"q":"ask","a":"D"},{"q":"complain","a":"C"},{"q":"forgive","a":"B"},{"q":"sympathy","a":"G"}]},{"t":"ex","no":"13.2","q":"Yuqoridagi so'zlar bilan gaplarni to'ldiring.","kind":"fill","text":"1. I would like to {1} about the treatment I received at your hotel.\n2. I hope that you will {2} me for behaving in this way.\n3. I am very {3} for the amount of time you have given up to help me.\n4. I offered my deepest {4} to Jane when I heard about the passing of her beloved pet cat.\n5. I am writing to {5} for your help in finding a place to live.","a":["complain","forgive","grateful","sympathy","ask"]},{"t":"ex","no":"13.3","q":"Namuna javobni berilgan so'zlar bilan to'ldiring.","intro":"**Topshiriq:** You are going on holiday and you would like to hire a car. One of your party is in a wheelchair. Write a letter to a car hire company: explain the reason you need the car; describe the type of car you need; ask what the price is and what it includes.","kind":"fill","bank":["suitable","car hire company","travel","website","storage space","22 December","our group","Tashkent","airport","accompanied"],"text":"Dear Sir/Madam,\n\nI found out about your {1} from your {2} and I would like some information.\n\nMy family and I are flying to {3} on {4} and we would like to rent a car to {5} around while we are there. We would return the car to the {6} on the 29th of December.\n\nAs there will be six people in {7}, we will need a large car. We will also be {8} by my brother, who is in a wheelchair. Therefore, we will need a car with lots of {9} and, if possible, a ramp for easy access.\n\nPlease could you let me know if you have anything {10} and whether there would be an extra cost. In addition, I would like to know whether your prices include insurance.\n\nI look forward to your reply.\n\nYours faithfully","a":["car hire company","website","Tashkent","22 December","travel","airport","our group","accompanied","storage space","suitable"]},{"t":"ex","no":"13.4","q":"Parchadagi so'z yasalishi xatolarini toping va to'g'ri shaklini yozing.","intro":"_I saw your **advertising** in Saturday's Daily Planet and I would like **applying** for the position of Sales Manager. I have three years' experience working as a salesman in Australia. I am energetic and **enthusiasm** in my work and I am **availability** to start immediately._","kind":"fill","text":"advertising → {1}\napplying → {2}\nenthusiasm → {3}\navailability → {4}","a":["advertisement","to apply","enthusiastic","available"]},{"t":"p","x":"**13.5.** Avtobus jadvali o'zgarishi haqida gazetaga xat — **Yozish xonasi**da (reja va namuna bilan)."}],"writes":0},{"task":1,"no":14,"title":"Grammatical range and accuracy","uz":"Grammatik xilma-xillik va aniqlik (baholash mezoni)","pages":"108–112","blocks":[{"t":"p","x":"Bu mezondan yuqori baho olish uchun **oddiy, qo'shma va murakkab** gaplardan va keng qamrovli grammatik vositalardan to'g'ri foydalanishni ko'rsatishingiz kerak."},{"t":"h","x":"1. Gap turlari"},{"t":"table","head":["Tur","Izoh","Misol"],"rows":[["Oddiy gap (simple)","bitta ega va kesim","I would like to invite you to my party on Saturday night."],["Qo'shma gap (compound)","ikki mustaqil gap: for, and, or, but, yet, so","The hotel was good but it was expensive. / It was raining so I decided to stay at my friend's home."],["Murakkab gap (complex)","mustaqil + ergash gap: although, because, while, after, if, before, since, as if, whenever, as","Although she likes chocolate, she chose vanilla ice cream. / If you study hard, you'll do well on the test. / I couldn't attend your birthday party because I was feeling unwell."]]},{"t":"h","x":"2. Gaplarni to'liq yozish"},{"t":"note","x":"Har qanday gapda kamida bitta **ega** va bitta **asosiy fe'l** bo'lishi shart."},{"t":"p","x":"✗ _My mobile phone which was very expensive._ — asosiy fe'l yo'q.\n✓ _My mobile phone was very expensive._ yoki ✓ _My mobile phone, which was very expensive, was stolen._\nFaqat oddiy gaplar bilan bexato yozgandan ko'ra, murakkab gaplarni yozishga harakat qilib, biroz xato qilgan yaxshiroq."},{"t":"h","x":"3. Ega-kesim moslashuvi"},{"t":"p","x":"✗ _Both the bus and train finishes at 10.00 pm._ → ✓ _Both the bus and train **finish** at 10.00 pm._ (ega ko'plikda — _they_)\nEng ko'p xato: he/she/it dan keyin fe'lga **-s** qo'shishni unutish: ✗ _He visit his mother on Monday._ → ✓ _He **visits** his mother on Monday._"},{"t":"ex","no":"14.1","q":"Gaplardagi grammatik xatolarni toping va to'g'rilab yozing.","kind":"write","items":[{"q":"The company have announced their new product.","sample":"The company has announced its new product."},{"q":"The advices you gave me were helpful.","sample":"The advice you gave me was helpful."},{"q":"Me and my friend went to the museum.","sample":"My friend and I went to the museum."},{"q":"I love to travel I have been to many countries.","sample":"I love to travel. I have been to many countries."},{"q":"Eager to join the team.","sample":"I am eager to join the team."},{"q":"I wants to express my gratitude for your assistance.","sample":"I want to express my gratitude for your assistance."},{"q":"The report which you have requested it is attached.","sample":"The report which you have requested is attached."},{"q":"Despite of the challenges, the project was successfully completed.","sample":"Despite the challenges, the project was successfully completed."},{"q":"Your prompt response is greatly appreciated by my team and I.","sample":"Your prompt response is greatly appreciated by my team and me."},{"q":"I'm looking forward to meet you in the upcoming meeting.","sample":"I'm looking forward to meeting you at the upcoming meeting."},{"q":"Let's meet up at the café on Saturday, isn't it?","sample":"Let's meet up at the café on Saturday, shall we?"},{"q":"Her new job is more challenging then her previous one.","sample":"Her new job is more challenging than her previous one."},{"q":"I'm writing to express my interest on the job opening.","sample":"I'm writing to express my interest in the job opening."},{"q":"The book you lent me were so interesting, thanks you!","sample":"The book you lent me was so interesting, thank you!"},{"q":"If I will have time, I'll attend the event.","sample":"If I have time, I'll attend the event."}]},{"t":"ex","no":"14.2","q":"Zamon bilan bog'liq xatoni tuzating — qavs o'rniga to'g'ri shaklni yozing.","kind":"fill","text":"1. I hope that the above information {1} (would) be helpful to you.\n2. I {2} (will) be grateful if you could think about the situation.\n3. However, there {3} (were) a few things I have to comment on.\n4. On the bus, I {4} (spend) the entire journey trying to make myself warm with the help of my shawl.\n5. Secondly, I {5} (want) to describe the kind of area I would like to move to.\n6. I {6} (writing) you this letter regarding doing a computer course.","a":["will","would","are","spent","would like","am writing"]},{"t":"ex","no":"14.3","q":"To'g'ri predlogni yozing (in, of, on, at, with, about, to, for).","kind":"fill","text":"1. The reason that I didn't take part is that I had an important examination in Marketing {1} the following day.\n2. On the night {2} last Sunday, I was playing games on the computer with my classmate.\n3. Yesterday, I noticed an advertisement {3} the newspaper.\n4. The main reason {4} my trip is to meet my nephews who are living there.\n5. I am looking forward {5} your reply and {6} having more details of this project.\n6. You can contact me {7} my phone at home {8} 5467 4539.\n7. I can support the project {9} a lot of ways.\n8. I have lots of experience {10} cooking and cleaning.\n9. I am really interested {11} this job.","a":["on","of","in","for","to","to","on","on","in","of/in","in"]},{"t":"ex","no":"14.4","q":"Imlo xatosi bor so'zni to'g'ri yozing.","kind":"fill","text":"1. I am writing to you becouse I'd like to attend the computer course → {1}\n2. I saw the advertisment at the university → {2}\n3. I think this is good for our sociaty → {3}\n4. Is that course avaible part time? → {4}\n5. The liberary needs more workers → {5}\n6. She has a degree in bussiness and marketing → {6}\n7. This resturant is situated at the centre of the city → {7}\n8. It's neccessary for me to improve my computer skills → {8}\n9. Yours sincerly → {9}","a":["because","advertisement","society","available","library","business","restaurant","necessary","sincerely"]},{"t":"ex","no":"14.5","q":"Norasmiy xatdagi grammatik xatolarni toping va to'liq to'g'rilab yozing.","kind":"write","items":[{"q":"Dear Go'zal, I hope you is doing well. I am writing you this letter to tell you about my recent trip to the mountains. Me and my friends decided to go camping last week and it was an amazing experience. Firstly, we reached the campsite and we setted up our tents near the river. The weather was so good and we enjoyed the beautiful scenery. In the nights, we was sitting around the campfire and telling stories. On the second day, we goes for a long hike. The trail was very challenging, but the views at the top was breathtaking. We took a lot of photos to remember the moments. During the trip, I have realized how important is to spend time in nature. It makes you feels refreshed and relaxed. I wish we can do this again sometime soon. Please write me back and tell me what's going on with you. I can't wait to hears from you! Take care, Barno","rows":10,"sample":"Dear Go'zal,\n\nI hope you are doing well. I am writing you this letter to tell you about my recent trip to the mountains. My friends and I decided to go camping last week, and it was an amazing experience.\n\nFirstly, we reached the campsite and set up our tents near the river. The weather was so good, and we enjoyed the beautiful scenery. At night, we were sitting around the campfire and telling stories.\n\nOn the second day, we went for a long hike. The trail was very challenging, but the views at the top were breathtaking. We took a lot of photos to remember the moments.\n\nDuring the trip, I realized how important it is to spend time in nature. It makes you feel refreshed and relaxed. I wish we could do this again sometime soon.\n\nPlease write back to me and tell me what's going on with you. I can't wait to hear from you!\n\nTake care,\nBarno"}]},{"t":"p","x":"**14.6.** Kutubxona kitoblari bo'yicha to'liq xat — **Yozish xonasi**da. Talablar: bitta ham imlo xatosi bo'lmasin; kamida 5 xil qo'shma va murakkab gap; kamida 3 xil zamon; artikl, predlog va ega-kesim moslashuviga e'tibor."}],"writes":16},{"task":1,"no":15,"title":"Letter samples","uz":"Xat namunalari va mashqlar","pages":"113–139","blocks":[{"t":"p","x":"Bu bo'limda kitobdagi 10 ta to'liq xat namunasi, ularning foydali iboralari va mashqlari jamlangan. Har bir namunani topshiriq bilan solishtirib o'qing: maqsad qayerda aytilgan, har bir tayanch savol qaysi paragrafda yoritilgan, qanday iboralar ishlatilgan. Har bir namuna **Yozish xonasi**da ham bor — o'zingiz yozib, namuna bilan solishtiring."},{"t":"h","x":"Sample 1 — Can't continue an evening course (formal)"},{"t":"task","situation":"You have a full-time job and are also doing a part-time evening course. You now find that you cannot continue the course.","to":"Write a letter to the course tutor. In your letter","bullets":["describe the situation","explain why you cannot continue at this time","say what action you would like to take"]},{"t":"model","title":"Sample answer","x":"Dear Mr Smith,\n\nI am writing to inform you that I will be unable to continue with the part-time computer programming course.\n\nI have been attending your evening classes for the last two months, and have enjoyed them immensely. As I stated on my course application form, I work full-time for a large IT company, and until now I have managed to fit the programming course into my schedule.\n\nHowever, my company is currently on the verge of signing a contract with an important new client in China, and I am part of the team that is being sent to Beijing to negotiate terms and conditions. I will probably be out of the country for several weeks.\n\nI am aware that you run the same course twice a year. Rather than try to catch up when I return from China, I was wondering if it would be possible for me to join the next cohort in September.\n\nI look forward to receiving your response.\n\nYours sincerely,\nPaul Jones"},{"t":"phr","title":"Iboralarni o'rganing","items":[["I am writing to inform you that…","Sizga shuni ma'lum qilish uchun yozyapmanki…"],["I will be unable to continue with…","…ni davom ettira olmayman"],["attend evening classes","kechki darslarga qatnashmoq"],["enjoy the course immensely","kurs juda yoqmoq"],["As I stated on the application form,","Arizada aytib o'tganimdek,"],["I managed to fit the course into my schedule","kurs uchun kun tartibimdan vaqt topa oldim"],["on the verge of signing a contract","shartnoma imzolash arafasida"],["negotiate terms and conditions","shart va sharoitlarni kelishib olmoq"],["I may be out of the country for several weeks","bir necha hafta chet elda bo'lishim mumkin"],["I am aware that…","Bilamanki…"],["I was wondering if it would be possible for me to…","…qilsam bo'ladimi, deb so'ramoqchi edim"],["join the next cohort","keyingi guruhga qo'shilish"],["I look forward to receiving your response.","Javobingizni kutib qolaman."]]},{"t":"h","x":"Sample 2 — Missed a flight because of airline staff (formal)"},{"t":"task","situation":"You missed a flight due to a problem at the airport.","to":"Write a letter to the airline. In your letter","bullets":["describe what happened that caused you to miss the flight","explain how missing your flight affected you","make it clear what you would like the airline to do"]},{"t":"model","title":"Sample answer","x":"Dear Sir or Madam,\n\nI am writing with regard to a flight that I missed due to a mistake by one of your employees.\n\nTwo weeks ago, I was due to catch a flight to Rome, where I intended to spend four days on holiday. Unfortunately, the attendant at the check-in desk gave me a boarding card for a different flight, and I did not notice the mistake until I arrived at the departure gate and it was too late.\n\nAs a result of the error, I was not allowed to board the flight to Rome, and this caused me great inconvenience. I had to book a new flight two days later, which meant that I missed two days of my holiday and I spent an extra $200.\n\nAs the mistake was caused by your company, I hope that you will compensate me for the cost of the additional flight as well as for my taxi fares to and from the airport.\n\nI look forward to receiving your response.\n\nYours faithfully,\nPaul Jones"},{"t":"phr","title":"Iboralarni o'rganing","items":[["I am writing with regard to a flight that…","…parvoz haqida yozyapman"],["I was due to catch a flight to Rome","Rimga uchishim kerak edi"],["the attendant at the check-in desk","ro'yxatdan o'tkazuvchi xodim"],["a boarding card for a different flight","boshqa reysga chiqish taloni"],["arrive at the departure gate","jo'nash eshigiga yetib kelmoq"],["As a result of the error, …, and this caused me great inconvenience.","Xato natijasida … va bu menga katta noqulaylik tug'dirdi."],["As the mistake was caused by your company,","Xato kompaniyangiz tomonidan qilingani sababli,"],["I hope that you will compensate me for…","…ni qoplab berasiz degan umiddaman"]]},{"t":"h","x":"Sample 3 — Asking your manager for time off (formal)"},{"t":"task","situation":"You are working for a company. You need to take some time off work and want to ask your manager about this.","to":"Write a letter to your manager. In your letter","bullets":["explain why you want to take time off work","give details of the amount of time you need","suggest how your work could be covered while you are away"]},{"t":"model","title":"Sample answer","x":"Dear Mr Smith,\n\nI am writing to ask for some time off work next month.\n\nThe reason for this request is that my brother is getting married. His future wife is Australian, and the wedding will take place in her home city, Melbourne. As the brother of the groom, I cannot miss such a special occasion.\n\nTo attend the ceremony and make the round trip from the UK, I would need at least five days off work. However, I would like to take the opportunity to do some sightseeing in Australia, so I am hoping that you will allow me to take a full two weeks' leave from the 1st to the 15th of May.\n\nI have spoken to my co-workers, and it seems that Peter Jones would be best placed to cover my project commitments while I am away. I will leave detailed instructions for him on my desk.\n\nI hope that my request does not cause you any inconvenience.\n\nYours sincerely,\nMichael Hall"},{"t":"phr","title":"Iboralarni o'rganing","items":[["ask for some time off work","ishdan biroz ta'til so'ramoq"],["The reason for this request is that…","Bu iltimosimning sababi shuki…"],["I cannot miss such a special occasion","bunday muhim tadbirni o'tkazib yubora olmayman"],["make the round trip from the UK","Britaniyadan borib-kelish"],["I would like to take the opportunity to…","…qilish imkoniyatidan foydalanmoqchiman"],["I am hoping that you will allow me to…","…ga ruxsat berasiz degan umiddaman"],["take a full two weeks' leave","to'liq ikki haftalik ta'til olish"],["X would be best placed to cover my project commitments","X vazifalarimni bajarib turishga eng mos nomzod"],["I hope my request does not cause you any inconvenience.","Iltimosim sizga noqulaylik tug'dirmaydi degan umiddaman."]]},{"t":"h","x":"Sample 4 — Accommodation abroad (formal)"},{"t":"p","x":"Bu namuna (Mark Smith, Australia) 6-unitda berilgan — **Yozish xonasi**da \"Moving abroad — property agent\" topshirig'ini oching."},{"t":"phr","title":"Foydali iboralar","items":[["I am writing to ask for your help finding accommodation","turar joy topishda yordam so'rab yozyapman"],["a recent promotion at work","ishdagi yaqindagi lavozim ko'tarilishi"],["I will soon be based in Sydney","tez orada Sidneyda ishlayman"],["we are hoping to emigrate as soon as possible","imkon qadar tez ko'chib o'tishni umid qilamiz"],["rented accommodation","ijara uy"],["property agent","ko'chmas mulk agenti"],["a detached house with three or four bedrooms","3–4 yotoqxonali alohida uy"],["Ideally,","eng yaxshi holatda,"],["a good-sized garden","kattagina bog'"],["a suburban location within easy commuting distance of the city centre","markazga qatnash oson bo'lgan shahar chetidagi joy"],["The local schools are an important consideration","mahalliy maktablar muhim omil"],["close to shops and other amenities","do'konlar va boshqa qulayliklarga yaqin"]]},{"t":"h","x":"Sample 5 — Lost camera — insurance claim (formal)"},{"t":"task","situation":"On a recent holiday you lost a valuable item. Fortunately, you have travel insurance to cover the cost of anything lost.","to":"Write a letter to the manager of your insurance company. In your letter","bullets":["describe the item you lost","explain how you lost it","tell the insurance company what you would like them to do"]},{"t":"model","title":"Sample answer","x":"Dear Sir/Madam,\n\nI am writing to inform you that I recently lost my digital camera while on holiday in Vietnam.\n\nThe camera is a black Canon 70D and cost $1550 when I bought it new last month. It has a resolution of 20 megapixels, a Canon 67 millimetre lens and was in a brown leather case with my name on it.\n\nI lost it when I was having coffee with my husband in the backpacker area of Ho Chi Minh City. I believe the coffee shop was called Highlands Coffee and it was on Pham Ngu Lao Street. We had been at the coffee shop for around 45 minutes when I noticed it was missing.\n\nI am entitled to make a claim for the value of the above-mentioned item and request that you send me details of what I need to do in order to proceed.\n\nI look forward to hearing from you at your earliest convenience.\n\nYours faithfully,\nJohn Smith"},{"t":"phr","title":"Iboralarni o'rganing","items":[["lost my digital camera while on holiday","ta'tilda raqamli kameramni yo'qotdim"],["It has a resolution of 20 megapixels","20 megapiksel aniqlikka ega"],["a brown leather case","jigarrang charm g'ilof"],["backpacker area","sayyohlar gavjum hudud"],["I am entitled to make a claim","da'vo qilishga haqliman"],["above-mentioned","yuqorida aytilgan"],["proceed","davom etmoq"],["at your earliest convenience","imkon qadar tezroq"]]},{"t":"h","x":"Sample 6 — A faulty toy from an online shop (formal)"},{"t":"task","situation":"You have recently purchased a toy from an online shop, but the delivered product is faulty.","to":"Write a letter to the owner of the shop. In your letter","bullets":["describe the toy","give details of the problem","tell the owner what you want him/her to do"]},{"t":"model","title":"Sample answer","x":"Dear Sir or Madam,\n\nI am writing this letter to complain about the faulty delivery of my product.\n\nYesterday, the brown teddy bear which I ordered from your website was delivered to my house. The bear appears to be made from polyester, and it is wearing a purple dress and matching hat, which are fashioned from a heavy velvet material. As well as that, the bear's paws are covered with red and white checkered cloth.\n\nHowever, the nose of the bear had not been firmly attached and fell off this morning. The bear was placed on a shelf immediately after the delivery and has not been touched since. I am, therefore, entirely confident that the issue was caused during the manufacturing process, rather than something that happened since it was delivered.\n\nAs this product was purchased as a gift for my daughter's birthday this weekend, I need you to send a replacement to me before the end of the week. My wife will be at home during the daytime, which means that your delivery driver can come at any time that is convenient for you.\n\nYours faithfully,\nLar Ryan"},{"t":"phr","title":"Iboralarni o'rganing","items":[["made from polyester","poliesterdan qilingan"],["fashioned from a heavy velvet material","qalin baxmal matodan tikilgan"],["firmly attached","mahkam biriktirilgan"],["I am, therefore, entirely confident that…, rather than…","Shuning uchun …ga to'liq aminman, … emas"],["during the manufacturing process","ishlab chiqarish jarayonida"],["send a replacement","almashtirib yubormoq"]]},{"t":"h","x":"Sample 7 — New apartments planned in a public park (formal)"},{"t":"task","situation":"You have heard about plans to build new apartments in a public park near your home. You want to give your opinion about this.","to":"Write a letter to the editor of your local newspaper. In your letter","bullets":["explain how you learnt about these plans","say what you think of the park","give your opinion on the plans"]},{"t":"model","title":"Sample answer","x":"Dear Sir or Madam,\n\nMy name is Mohammad Khatib, and I am a regular reader of your newspaper. I am writing to let you know of some rumours, which I hope are untrue, that I have heard recently about construction plans in our popular public park.\n\nAs you know, this is the only park within our immediate vicinity, and many people go there for relaxation. Many children also play in this park with their peers. I have recently heard from some of my neighbours that Royal Construction Company intends to build some apartment blocks in the park. At first, I did not take it seriously until yesterday, when I saw some engineers measuring and calculating different dimensions of the park.\n\nWe all like our local park, including its beautiful fountains, its playground and amusing facilities for children. So, as the representative of most of the neighbours, I have collected signatures against this project.\n\nTherefore, we, as local residents, disagree with the plan and kindly ask you to write an article about the disadvantages of this action and express our great disapproval of the plan. We are looking forward to seeing your article as our voice soon.\n\nThank you for your cooperation in advance.\n\nYours faithfully,\nMohammad Khatib"},{"t":"phr","title":"Iboralarni o'rganing","items":[["to let you know of some rumours","ba'zi mish-mishlar haqida xabar bermoq"],["within our immediate vicinity","yaqin atrofimizda"],["go there for relaxation","dam olish uchun bormoq"],["peers","tengdoshlar"],["the company intends to build apartment blocks","kompaniya ko'p qavatli uylar qurish niyatida"],["measure and calculate the dimensions","o'lchamlarini o'lchab hisoblamoq"],["disagree with the plan","rejaga qarshi bo'lmoq"],["express our great disapproval of the plan","rejadan katta noroziligimizni bildirmoq"],["Thank you for your cooperation in advance.","Hamkorligingiz uchun oldindan rahmat."]]},{"t":"h","x":"Sample 8 — Tell your best friend you've moved house (informal)"},{"t":"task","situation":"You have recently moved to a new house and want to inform your best friend about it.","to":"Write a letter to your friend. In the letter","bullets":["explain the reason for moving","describe your new house","invite him/her to your new house"]},{"t":"model","title":"Sample answer","x":"Dear Jasur,\n\nI'm just writing to let you know that I've moved house.\n\nAs you know, I went for an interview for a job here in Tashkent. Well, they gave me the position! It would have been impractical to travel from Chinoz every day, so we've found a house here, in a nice part of Tashkent called Sebzor.\n\nOur new house isn't ideal. Tashkent prices are crazy, and we were only able to afford a one-bedroom flat. But on the bright side, it's on the ground floor, it's got nice big windows, and a lovely view out onto the garden.\n\nIf you ever fancy a trip to Tashkent, you're more than welcome to come and stay. It would be great to see you. From where we live, it's only a quick ride on the underground into the city centre, so we could do some sightseeing together.\n\nKeep in touch!\n\nAll the best,\nMurod"},{"t":"phr","title":"Iboralarni o'rganing","items":[["I'm just writing to let you know that…","Shuni bilishingizni istab yozyapman…"],["As you know,","Bilasizki,"],["It would have been impractical to…","…qilish noqulay (imkonsiz) bo'lardi"],["isn't ideal","ko'ngildagidek emas"],["prices are crazy","narxlar juda baland"],["we were only able to afford…","faqat …ga qurbimiz yetdi"],["on the bright side,","yaxshi tomoni,"],["If you ever fancy a trip to…","Qachondir …ga kelgingiz kelsa"],["you're more than welcome to come and stay","bemalol kelib qolavering"],["a quick ride on the underground","metroda tezgina yo'l"],["Keep in touch! / All the best,","Aloqada bo'laylik! / Yaxshi qol,"]]},{"t":"h","x":"Sample 9 — Ask a friend to translate a document (informal)"},{"t":"task","situation":"You need a translation of a document into a different language, and you have a friend who speaks that language.","to":"Write a letter to your friend. In your letter","bullets":["explain what the document is and why you need a translation","explain why this is urgent and important for you","ask your friend if and when he/she will be able to help you"]},{"t":"model","title":"Sample answer","x":"Dear Jane,\n\nI hope you're well. I'm writing to ask for your help with a document that I need to have translated into French.\n\nAs you know, I've been given the opportunity to spend a semester at a business school in Paris. Well, they've asked me to provide a translated copy of my degree certificate with the original.\n\nI've been told that I must submit both documents this week in order to secure my place on the course. They will give my place to someone else if I don't get the translation done; I'm running out of time, and you're my only hope!\n\nDo you think you could do me a big favour and give me an hour or so of your time either tomorrow or Wednesday? It shouldn't take you long to translate the certificate, and I can come to see you whenever suits you best.\n\nIf you're able to help, just let me know when you'd like me to pop round.\n\nSpeak soon,\nChris"},{"t":"phr","title":"Iboralarni o'rganing","items":[["I've been given the opportunity to…","…ga imkoniyat berildi"],["spend a semester","bir semestr o'tkazmoq"],["a translated copy of my degree certificate","diplomning tarjima qilingan nusxasi"],["submit documents","hujjat topshirmoq"],["secure my place","joyimni saqlab qolmoq"],["I'm running out of time","vaqtim tugab qolyapti"],["Could you do me a big favour?","Menga katta yaxshilik qila olasizmi?"],["pop round (informal)","kirib o'tmoq"]]},{"t":"h","x":"Sample 10 — Offer your concert ticket to a friend (informal)"},{"t":"task","situation":"You bought a ticket to a music concert. However, you are unable to go, so you decide to offer your ticket to a friend.","to":"Write a letter to your friend. In your letter:","bullets":["tell your friend about the details of the concert","explain why you are unable to go","and explain how your friend can receive your ticket"]},{"t":"model","title":"Sample answer","x":"Dear John,\n\nI hope you're well. I'm just writing to offer you a concert ticket that I won't be able to use.\n\nDo you remember that I told you I was going to a gig this Saturday? There's an up-and-coming singer and guitarist who's playing at the Apollo Theatre. I think you'll be blown away by how good he is. The concert starts at 7 pm, but there's a support act on first, so you can arrive a bit later if you just want to catch the main performance.\n\nThe reason why I'm offering you my ticket is that I've been asked to visit a client in Germany to help with a product launch, and I won't be back until Monday.\n\nIf you're free on Saturday evening and you'd like to go, just speak to my brother. He'll be going to the gig, so you won't be alone, and you can arrange to meet beforehand or outside the venue on the night.\n\nI hope you can make it, and that you enjoy the concert!\n\nSee you soon,\nSimon"},{"t":"phr","title":"Iboralarni o'rganing","items":[["offer a concert ticket","konsert chiptasini taklif qilmoq"],["up-and-coming singer","kelajagi porloq qo'shiqchi"],["you'll be blown away","hayratda qolasiz"],["catch the main performance","asosiy chiqishga ulgurmoq"],["a product launch","mahsulot taqdimoti"],["going to the gig (informal)","konsertga bormoq"],["arrange to meet beforehand","oldindan uchrashishni kelishmoq"],["outside the venue","bino tashqarisida"]]},{"t":"h","x":"Mashqlar"},{"t":"ex","no":"1.4","q":"\"Rather than …, I was wondering if it would be possible for me to …\" strukturasi bilan tarjima qiling.","kind":"write","items":[{"q":"Bugun kechqurun tashqariga chiqish o'rniga, uyda qolib dam olsammikin deb o'ylagandim.","sample":"Rather than go out tonight, I was wondering if it would be possible for me to stay in and relax."},{"q":"Har kuni ko'chada tushlik qilish o'rniga, o'zim uyda tayyorlagan taomlarni olib kelsammikin deb o'ylagandim.","sample":"Rather than eat out for lunch every day, I was wondering if it would be possible for me to bring my own homemade meals."},{"q":"Aeroportga taksida borish o'rniga, jamoat transportidan foydalansammikin deb o'ylagandim.","sample":"Rather than take a taxi to the airport, I was wondering if it would be possible for me to use public transport."},{"q":"Ushbu hafta oxirida loyihani tugatishga shoshilishdan ko'ra, muddatni uzaytirishim mumkinmi deb o'ylayotgandim.","sample":"Rather than rush to finish the project this weekend, I was wondering if it would be possible for me to get an extension."},{"q":"Yangi mashina sotib olish o'rniga, eski mashinamni ta'mirlashim mumkinmi deb o'ylayotgandim.","sample":"Rather than buy a new car, I was wondering if it would be possible for me to repair my old one."}]},{"t":"ex","no":"2.2","q":"\"As a result of …, … and this caused …\" strukturasi bilan tarjima qiling.","kind":"write","items":[{"q":"Kutilmagan elektr uzilishi natijasida kompyuterim ishdan chiqdi va bu menga katta noqulaylik tug'dirdi.","sample":"As a result of the unexpected power outage, my computer crashed, and this caused me great inconvenience."},{"q":"Kuchli yog'ingarchilik natijasida tomdan suv sizib chiqa boshladi va bu yotoqxonamizga sezilarli zarar yetkazdi.","sample":"As a result of the heavy rainfall, the roof started leaking, and this caused significant damage to our bedroom."},{"q":"Farzandimning to'satdan kasal bo'lib qolishi natijasida ishga bora olmadim va bu menga katta noqulaylik tug'dirdi.","sample":"As a result of the sudden illness of my child, I had to miss work, and this caused me great inconvenience."},{"q":"Kompyuterning to'satdan buzilishi natijasida saqlanmagan barcha ishlarimni yo'qotdim va bu kechikishlarga sabab bo'ldi.","sample":"As a result of the sudden computer crash, I lost all my unsaved work, and this caused delays."},{"q":"Narxlarning kutilmagan o'sishi natijasida oylik xarajatlarimiz ko'paydi va bu bizga moliyaviy muammolar keltirib chiqardi.","sample":"As a result of the unexpected price increase, our monthly expenses soared, and this caused us financial problems."}]},{"t":"ex","no":"3.2","q":"Norasmiy gaplarning Sample 3 dagi rasmiy shaklini yozing.","kind":"write","items":[{"q":"Being the groom's bro, I can't skip this awesome event.","sample":"As the brother of the groom, I cannot miss such a special occasion."},{"q":"To make it to the wedding and fly back from the UK, I'd need at least five days off.","sample":"To attend the ceremony and make the round trip from the UK, I would need at least five days off work."},{"q":"I hope this doesn't mess up your plans too much.","sample":"I hope that my request does not cause you any inconvenience."},{"q":"He's marrying an Australian, and the wedding's in Melbourne, her hometown.","sample":"His future wife is Australian, and the wedding will take place in her home city, Melbourne."},{"q":"I'll drop some detailed notes on my desk for him.","sample":"I will leave detailed instructions for him on my desk."}]},{"t":"ex","no":"3.3","q":"Faqat birinchi tayanch savolga javob yozing: You are a member of a sports team and need to request time off from practice and games. Write a letter to your coach — explain the reason for needing time off from sports activities.","kind":"write","items":[{"q":"Paragraf (2–3 gap):","sample":"The reason I am seeking some time off from sports activities is a family emergency. Unfortunately, a close family member has fallen seriously ill, and I need to be by their side to provide support during this challenging period."}]},{"t":"ex","no":"4.2","q":"Gaplarni ingliz tiliga o'giring (Sample 4 iboralari).","kind":"write","items":[{"q":"Men tez orada Toshkentda bo'laman. Ijara bilan shug'ullanadigan agent menga ijaraga uy topishga yordamlashdi.","sample":"I will soon be based in Tashkent. A property agent helped me find a rented home."},{"q":"Oilamiz katta, shuning uchun bizga uch-to'rt yotoqxonali alohida uy kerak.","sample":"Our family is big, so we need a detached house with three or four bedrooms."},{"q":"Yaxshi yo'lga qo'yilgan jamoat transporti bo'lishi muhim omil.","sample":"Well-organized public transport is an important consideration."},{"q":"Menga uyimdan oson borib keladigan masofada joylashgan ta'lim markazi kerak.","sample":"I need an education centre within easy commuting distance of my home."},{"q":"Ideal holatda, kattagina bog'i bor ikki qavatli uyni ijaraga olmoqchiman.","sample":"Ideally, I would like to rent a two-storey house with a good-sized garden."}]},{"t":"ex","no":"5.1","q":"\"I am entitled to …\" bilan boshlab tarjima qiling.","kind":"write","items":[{"q":"Men sotib olgan nuqsonli mahsulot uchun pulni qaytarishni talab qilishga haqliman.","sample":"I am entitled to make a claim for a refund of the faulty product I purchased."},{"q":"Yozma ish topshirish muddatini uzaytirib berishingizni so'rashga haqliman.","sample":"I am entitled to request that you grant me an extension for the assignment submission."},{"q":"Ish joyidagi baxtsiz hodisa natijasida yetkazilgan zararni qoplash bo'yicha da'vo qilish huquqiga egaman.","sample":"I am entitled to make a claim for compensation for the injuries in the workplace accident."},{"q":"Bo'lajak safarim uchun munosib turar joy topishda yordam berishingizni so'rashga haqliman.","sample":"I am entitled to request that you provide assistance with finding suitable accommodation for my upcoming trip."},{"q":"Olgan adolatsiz bahomni qayta ko'rib chiqish uchun da'vo qilish huquqiga egaman.","sample":"I am entitled to make a claim for a review of the unfair assessment result I received."}]},{"t":"ex","no":"6.3","q":"\"I am, therefore, entirely confident that …, rather than …\" strukturasi bilan tarjima qiling.","kind":"write","items":[{"q":"Shuning uchun muammo uskunamiz sababli emas, balki ob-havo sharoiti tufayli yuzaga kelganiga aminman.","sample":"I am, therefore, entirely certain that the issue arose due to the weather conditions, rather than our equipment."},{"q":"Shuning uchun xatolik ishlatilgan materialda emas, balki dizaynda ekaniga aminman.","sample":"I am, therefore, entirely confident that the fault lies with the design, rather than the material used."},{"q":"Energiya to'lovlarining oshishi iste'mol ko'payishi bilan emas, balki yoqilg'i narxi oshishi bilan bog'liq ekaniga to'liq ishonaman.","sample":"I am, therefore, entirely sure that the increase in energy bills is due to rising fuel prices, rather than increased consumption."},{"q":"Havo sifatining pasayishiga tabiiy omillar emas, balki sanoat chiqindilari sabab bo'lganiga to'liq ishonaman.","sample":"I am, therefore, entirely confident that the recent drop in air quality is caused by industrial emissions, rather than natural factors."},{"q":"Xato yozuvchi tomonidan emas, balki chop etish bosqichida qilinganiga to'liq aminman.","sample":"I am, therefore, entirely sure that the mistake was made during the printing phase, rather than by the writer."}]},{"t":"ex","no":"7.1","q":"Izohga mos so'zni Sample 7 xatidan topib yozing.","kind":"fill","text":"1. the area around a place → {1}\n2. an unofficial interesting story or piece of news that might be true or invented → {2}\n3. the feeling of having a negative opinion of someone or something → {3}\n4. before a particular time, or before doing a particular thing → {4}\n5. someone who speaks or does something officially for another person or group → {5}\n6. a measurement of something in a particular direction (height, length, width) → {6}\n7. the act of working together for a particular purpose → {7}","a":["vicinity","rumour/rumor/rumours/rumors","disapproval","in advance","representative","dimension/dimensions","cooperation"]},{"t":"ex","no":"8.2","q":"Gaplarni ingliz tiliga o'giring (Sample 8 iboralari).","kind":"write","items":[{"q":"Agarda qachondir Toshkentga kelishni xohlasangiz, birgalikda Amir Temur muzeyiga boramiz.","sample":"If you ever fancy a trip to Tashkent, we will visit the Amir Temur Museum together."},{"q":"Toshkentda narxlar juda baland, shuning uchun Andijondan 2 xonali kvartira sotib olishga qaror qildik.","sample":"Tashkent prices are crazy, so we decided to buy a two-room flat in Andijan."},{"q":"Samarqandga har kuni avtobusda qatnash noqulay bo'lardi, shuning uchun shaxsiy mashina xarid qildim.","sample":"It would be impractical to take a bus to Samarkand every day, so I bought a car."},{"q":"Lekin yaxshi tomoni, qarindoshlarimiz bilan haftada kamida bir marta ko'rishib turamiz.","sample":"But on the bright side, we see our relatives at least once a week."},{"q":"Bilasizki, biz 5 yil oldin Buxoro viloyatidagi kichkina qishloqda yashardik.","sample":"As you know, we lived in a small village in the Bukhara region 5 years ago."}]},{"t":"ex","no":"9.1","q":"Rasmiy gaplarni norasmiy uslubda yozing.","kind":"write","items":[{"q":"I trust you are in good health.","sample":"I hope you're well."},{"q":"I am writing to request your assistance with…","sample":"I'm writing to ask for your help with…"},{"q":"As you are aware, …","sample":"As you know, …"},{"q":"I have been informed that it is imperative to submit…","sample":"I've been told that I must submit…"},{"q":"If you are available to assist, please inform me…","sample":"If you're able to help, just let me know…"},{"q":"I look forward to hearing from you soon.","sample":"Speak soon! / Hope to hear from you soon."}]},{"t":"ex","no":"9.3","q":"\"As you know, I've been given the opportunity to …\" strukturasi bilan tarjima qiling.","kind":"write","items":[{"q":"Sizga ma'lumki, menga kelasi oy bo'ladigan xalqaro savdo anjumanida kompaniyamiz vakili bo'lish imkoniyati berildi.","sample":"As you know, I've been given the opportunity to represent our company at an international trade conference next month."},{"q":"Sizga ma'lumki, menga Ispaniyada bir semestr o'qish imkoniyati berildi va men bundan juda xursandman.","sample":"As you know, I've been given the opportunity to study abroad for a semester in Spain, and I'm thrilled about it."},{"q":"Sizga ma'lumki, o'qituvchimiz Toshkentga ketganida menga o'quvchilarga ingliz tilidan dars berish imkoniyati berildi.","sample":"As you know, I've been given the opportunity to teach students English while our teacher is in Tashkent."},{"q":"Sizga ma'lumki, Samarqanddagi xalqaro ko'rgazmada suratlarimni namoyish etish imkoniga ega bo'ldim.","sample":"As you know, I've been given the opportunity to show my pictures at an international exhibition in Samarkand."},{"q":"Sizga ma'lumki, menga bir qancha xalqaro kompaniyalar bilan birga ishlash imkoniyati berildi.","sample":"As you know, I've been given the opportunity to work together with several international companies."}]},{"t":"ex","no":"10.1","q":"\"The reason why I'm offering you my ticket is that …\" strukturasi bilan tarjima qiling.","kind":"write","items":[{"q":"Chiptani taklif qilishimning sababi — hozir universitet imtihonlariga tayyorlanish bilan juda bandman.","sample":"The reason why I'm offering you my ticket is that I'm very busy preparing for my university exams at the moment."},{"q":"…sababi — onam kasal bo'lib qoldilar va ularga qarashga mendan boshqa odam yo'q.","sample":"The reason why I'm offering you my ticket is that my mother has fallen ill and there is no one else to take care of her."},{"q":"…sababi — kecha futbol o'ynayotib oyog'imni sindirib oldim, hozir yurishim cheklangan.","sample":"The reason why I'm offering you my ticket is that I broke my leg playing football yesterday, so unfortunately my ability to walk is limited at the moment."},{"q":"…sababi — meni kutilmaganda boshqa viloyatga yangi shartnoma tuzishga jo'natishmoqda.","sample":"The reason why I'm offering you my ticket is that I am unexpectedly being sent to another region to sign a new contract."},{"q":"…sababi — aynan o'sha kuni akamning uyida qarindoshlar bilan ziyofat qilmoqchimiz.","sample":"The reason why I'm offering you my ticket is that we are having a party with relatives at my brother's house that very day."}]},{"t":"p","x":"Har bir namunadan keyingi **to'liq xat yozish** topshiriqlari (1.5, 2.4, 3.4, 4.3, 5.3, 5.4, 6.4, 7.4, 8.3, 9.4, 10.3) — **Yozish xonasi**da."}],"writes":52},{"task":2,"no":16,"title":"Paraphrasing","uz":"Parafraza qilish","pages":"142–152","blocks":[{"t":"p","x":"**Paraphrasing** — so'z yoki gapning ma'nosini saqlab, boshqa so'zlar yoki grammatik tuzilish bilan qayta yozish. Inshoda u ayniqsa muhim: ko'pchilik ekspertlar kirish qismining birinchi gapida **topshiriqni parafraza qilib** yozishni maslahat beradi."},{"t":"table","head":["Oddiy gap","Parafraza"],"rows":[["Paraphrasing is one of the important skills to learn before taking a Multilevel exam.","Before sitting a Multilevel exam, mastering paraphrasing is one of the most crucial things to do."]]},{"t":"p","x":"Ikki o'zgarish: sinonimlar (_taking an exam → sitting an exam, important → crucial, learn → mastering_) va gap tuzilishi (ikkinchi qism boshiga chiqdi)."},{"t":"h","x":"1. Sinonimlardan foydalanish"},{"t":"model","x":"The reasons for increasing levels of pollution are the development of industry and air travel.\n→ The causes of rising levels of pollution are the growth and expansion of industry as well as the number of people travelling by air."},{"t":"p","x":"_reasons = causes, increasing = rising, the development of = the growth and expansion of, and = as well as, air travel = travelling by air_. \"levels of pollution\" va \"industry\" o'zgarmagan — bu normal. Barcha so'zni almashtirish shart emas: **faqat 100% bilgan sinonimingizni** ishlating — ba'zi so'zlar ma'nodoshdek ko'rinsa ham, qo'llanishi boshqacha."},{"t":"h","x":"2. So'z shaklini o'zgartirish"},{"t":"model","x":"Many people are unhealthy because they fail to eat well and exercise.\n→ Many people have poor health because they are failing to eat well and are not exercising enough.\n\nThe professor explained the impacts of climate change on agriculture.\n→ An explanation of the impacts of climate change on agriculture was given by the professor."},{"t":"p","x":"_unhealthy → poor health, fail → failing, explained → explanation_. O'zgargan shakl grammatik jihatdan gapga mos bo'lishi shart."},{"t":"h","x":"3. So'zlar joylashuvini o'zgartirish"},{"t":"model","x":"The government implemented new policies to stimulate economic growth and create job opportunities in the country.\n→ In order to foster economic growth and generate employment prospects, the government introduced new policies.\n\nPeople are heading to developed countries with the purpose of finding high-paid jobs now.\n→ Nowadays, with the goal of finding well-paid jobs, people are travelling to industrialized nations."},{"t":"h","x":"4. Active → Passive"},{"t":"model","x":"The researchers conducted experiments to reduce air pollution.\n→ Experiments were conducted by the researchers to reduce air pollution."},{"t":"p","x":"Majhul nisbat asosan ilmiy va rasmiy matnlarda ishlatiladi. Faqat to'ldiruvchisi bor gapni passivga aylantirish mumkin."},{"t":"h","x":"5. Referencing — olmosh bilan havola"},{"t":"model","x":"I bought a new apple yesterday. **It** was delicious.\n\nOne of the reasons that people are becoming overweight these days is that they are eating more junk food. Therefore, consumers would think twice about the foods **they** consume, which could lead to **them** losing weight."},{"t":"h","x":"Topshiriqni parafraza qilish: 15 ta misol"},{"t":"table","head":["Original","Parafraza"],"rows":[["Some people believe that it's acceptable for the media to publish the details of famous people's private lives. Others say that it should be stopped.","Some are okay with the media publishing private details of celebrities' lives, while other people feel that this shouldn't be allowed."],["Nowadays, many young people enjoy copying the behaviour of their favourite celebrities.","These days, a lot of young people like to copy the actions of the celebrities they admire most."],["Many people around the world spend the majority of their free time at home watching TV shows.","All over the world, many individuals use most of their spare time at home watching television programmes."],["Some people believe that team sports prepare children for their future careers while others do not agree.","Some believe team sports build children up to be ready for their careers, but others disagree."],["Some university students live with their families while studying, but others prefer to move away from home.","Some students stay at their family home while attending university, but other students decide to move out."],["In many countries, there is an increase in the number of serious crimes committed by young people.","In many nations, rising numbers of young people are committing serious crimes."],["Due to advances in technology, an increasing number of people are working from home instead of going to their company's premises.","Because of modern technology, more people are working from home rather than commuting to their employers' offices."],["In recent times, many children spend more time playing video games than they do playing sport.","Nowadays, a lot of children use more of their time to play computer games than to play sport."],["There are some people who decide to live in the countryside even though this means a long commute to work each day.","Some individuals choose to find accommodation in the country, although that results in longer commuting times to work every day."],["Nowadays, people across the world have access to a large number of online newspapers and magazines.","These days, people all over the world can read many different periodicals on the internet."],["Because of growing populations, more homes are needed in many countries.","Because populations are growing, additional housing is required in many nations."],["Around the world, traffic accidents cause many serious injuries every day. Due to this, some people believe stricter laws are necessary to improve road safety.","All over the world, accidents on the road each day result in grave injuries. Consequently, some hold that more stringent laws are required to reduce the number of casualties."],["Some people think the countryside is a better place for children to grow up than a city.","Some individuals are of the view that raising children in the countryside is much better than raising them in the city."],["Some people believe that online libraries are more beneficial than physical libraries.","Some individuals think that online libraries offer more benefits than conventional libraries."],["In some cultures, it's common for young adults to move out of their family homes as soon as possible.","In certain societies, it is customary for younger generations to leave their parents' dwellings as soon as they can."]]},{"t":"ex","no":"16.1","q":"Ajratilgan so'zning sinonimini toping.","kind":"mcq","items":[{"q":"The manager's decision had a profound **impact** on the company.","o":["effect","consequence","insignificance","aftermath"],"a":0},{"q":"The student's response to the question was **concise** and to the point.","o":["lengthy","brief","elaborate","wordy"],"a":1},{"q":"The team's **collaborative** efforts resulted in the successful completion of the project.","o":["fruitful","ineffective","futile","barren"],"a":0,"why":"Kitob kaliti: A."},{"q":"The scientist made a **profound** discovery that changed the course of research.","o":["shallow","superficial","significant","trivial"],"a":2},{"q":"The students were required to submit their assignments **promptly**.","o":["quickly","eventually","reluctantly","regularly"],"a":0},{"q":"The teacher encouraged students to **express** their opinions freely.","o":["suppress","articulate","conceal","repress"],"a":1},{"q":"The new policy aims to **enhance** customer satisfaction.","o":["diminish","improve","hinder","worsen"],"a":1},{"q":"The student's argument was **valid** and well-supported.","o":["invalid","rational","irrational","unreasonable"],"a":1},{"q":"The professor emphasized the **significance** of critical thinking in academic writing.","o":["insignificance","importance","triviality","unimportance"],"a":1},{"q":"The professor provided a **comprehensive** overview of the economic theories.","o":["detailed","limited","superficial","vague"],"a":0}]},{"t":"ex","no":"16.2","q":"Qavsdagi so'zning to'g'ri shaklini yozing.","kind":"fill","text":"1. The {1} (nation) government implemented new policies to address economic challenges.\n2. The documentary provided a {2} (history) account of the events leading to the revolution.\n3. The company is known for its commitment to environmental {3} (protect).\n4. The team's {4} (innovate) approach to problem-solving earned them recognition in the industry.\n5. The professor emphasized the importance of cultural {5} (diverse) in today's globalized world.\n6. The conference will focus on the latest {6} (develop) in sustainable energy.\n7. The manager expressed {7} (satisfy) with the team's performance during the project.\n8. The artist's work reflects deep {8} (think) about the complexities of human nature.\n9. The success of the project was due to the {9} (collaborate) efforts of the entire team.\n10. The candidate demonstrated a high level of {10} (prepare) for the challenging interview.","a":["national","historical","protection","innovative","diversity","developments","satisfaction","thinking","collaborative","preparedness/preparation"]},{"t":"ex","no":"16.3","q":"So'zlar joylashuvini o'zgartirib (va sinonimlardan foydalanib) gaplarni qayta yozing. Namuna: The scientist conducted experiments to analyze the effects of climate change on marine life. → To examine the impacts of climate change on marine life, the researcher conducted experiments.","kind":"write","items":[{"q":"Many students find it challenging to balance academics, work, and personal life.","sample":"Balancing academics, work, and personal life is a challenge for many students."},{"q":"The city council plans to build a new park in the downtown area to enhance green spaces.","sample":"To enhance green spaces, the city council plans to build a new park in the downtown area."},{"q":"Social media has transformed the way people communicate and share information in the digital age.","sample":"In the digital age, social media has transformed the way people communicate and share information."},{"q":"The manager provided employees with a comprehensive training program to improve their skills.","sample":"To improve their skills comprehensively, the employees were provided with a training programme by the manager."},{"q":"Students are required to submit their research papers by the end of the semester.","sample":"By the end of the semester, students are required to submit their research papers."},{"q":"The increasing popularity of electric vehicles is reshaping the automotive industry.","sample":"The automotive industry is being reshaped by the growing popularity of electric vehicles."},{"q":"The teacher emphasized the importance of critical thinking skills during the lecture.","sample":"During the lecture, the teacher stressed the importance of critical thinking skills."},{"q":"The government must address environmental concerns to ensure a sustainable future.","sample":"To ensure a sustainable future, the government must address environmental concerns."},{"q":"The company aims to expand its market share by introducing innovative products.","sample":"By introducing innovative products, the company aims to expand its market share."},{"q":"Most people learn foreign languages with the purpose of finding a high-paid job.","sample":"With the goal of finding a lucrative job, most people learn foreign languages."}]},{"t":"ex","no":"16.4","q":"Ajratilgan otni fe'lga aylantirib, gapni qayta yozing. Namuna: You have to give us your decision by tomorrow. → You have to decide by tomorrow.","kind":"write","items":[{"q":"This essay gives **an analysis** of the problem of climate change and describes a potential solution.","sample":"This essay analyses the problem of climate change and describes a potential solution."},{"q":"The Korean President did not give **an explanation** for the pardon of his business friend.","sample":"The Korean President did not explain the pardon of his business friend."},{"q":"Our class **debate** concerned the issue of nuclear weapons.","sample":"Our class debated the issue of nuclear weapons."},{"q":"We performed **a review** of the company's annual reports.","sample":"We reviewed the company's annual reports."},{"q":"The school club of actors did **a performance** of Romeo and Juliet on the second of June.","sample":"The school club of actors performed Romeo and Juliet on the second of June."},{"q":"There is a need for further **study** of this Master's programme.","sample":"This Master's programme should be studied further."},{"q":"It is necessary for political candidates to give a good **performance** during a TV debate.","sample":"Political candidates need to perform well during a TV debate."},{"q":"There is a need in our city for **an assessment** of the recycling system.","sample":"Our city needs to assess the recycling system."}]},{"t":"ex","no":"16.5","q":"Gaplarni to'liq parafraza qiling.","kind":"write","items":[{"q":"Governments should spend more money on education than on recreation and sports.","sample":"It is argued that countries should allocate more funds to education than to leisure and competitive games."},{"q":"Some people say that the best way to improve public health is by increasing the number of sports facilities. Others, however, say that this would have little effect on public health and that other measures are required.","sample":"It is often argued that expanding the number of leisure amenities is the most appropriate way of boosting the health of the general public, while others feel that this is not a viable solution and believe other steps are needed."},{"q":"Multinational companies are becoming increasingly common in developing countries.","sample":"More and more transnational corporations are setting up branches and factories in less developed nations."},{"q":"Some people say that online courses are the most beneficial, while others believe traditional classrooms are more advantageous.","sample":"There are those who feel that studying online is best, but others who think that traditional classrooms are better."},{"q":"The majority of people find it difficult to speak in public or give a presentation in front of an audience.","sample":"For most people, public speaking and giving presentations is something that they find difficult."},{"q":"There are many who feel that public transportation is the best way to commute. Others believe that private transportation such as cars is better.","sample":"Some believe that public transport is the best way to travel from one place to another, but others prefer private transport."},{"q":"Each country has its own traffic laws, such as speed limits, to ensure the safety of its citizens.","sample":"Every country has laws to help protect its residents from the dangers of driving."}]},{"t":"ex","no":"16.6","q":"Takrorlangan so'z o'rniga mos olmoshni yozing.","kind":"fill","text":"1. Fan Bingbing is a popular actress in China. {1} starred in My Fair Princess.\n2. Benedict Cumberbatch is one of my heroes. I met {2}.\n3. Our country has laws that protect people from paparazzi. Some countries' laws are not as strict as {3}.\n4. There are some reasons for my opinion. The first reason for {4} is that it is difficult to be famous.","a":["She","him","ours","this/it"]}],"writes":25},{"task":2,"no":17,"title":"Conjunctions","uz":"Bog'lovchilar","pages":"153–162","blocks":[{"t":"p","x":"Bog'lovchilar insho qismlarini va gaplarni mantiqan bog'laydi. Ularni to'g'ri va xilma-xil ishlatish **Coherence and Cohesion** mezonidan yuqori ball beradi. Quyida inshoda eng ko'p kerak bo'ladigan bog'lovchilar:"},{"t":"table","head":["Bog'lovchi","Ma'nosi","Misol"],"rows":[["and","va, bilan, hamda — teng bo'laklarni bog'laydi","He walks to school, and she takes the bus."],["but","lekin, ammo — qarama-qarshi fikrlar","We have a blackboard but we can't write on it."],["not only … but also","nafaqat … balki","Not only does regular exercise contribute to physical well-being, but it also plays a crucial role in maintaining mental health."],["so","shuning uchun","It's very hot so let's open the window."],["so as to / in order to + V1","…uchun, maqsadida","Governments can set rules in order to promote environmental conservation and resource efficiency."],["so that","…sin deb, maqsadida","Parents should limit their children's screen time so that they can have more time for outdoor activities and homework."],["because + gap","chunki","Children should be encouraged to eat more fruit and vegetables because they are essential for their overall health and development."],["because of / owing to / due to + ot","sababli, tufayli","Air pollution is a significant concern in cities because of increased vehicle emissions and industrial activities."],["This is because…","Buning sababi — (yangi gap boshida)","One problem is that a lot of young children don't have a healthy diet. This is because their parents don't have time to cook at home."],["although / even though / though + gap","garchi, …ga qaramasdan","Although many people enjoy fast food, it is important to consume it in moderation."],["in spite of / despite + ot / -ing","…ga qaramasdan","Despite facing financial challenges, she successfully completed her education."],["yet","ammo, vaholanki","He has a good job, and yet he never seems to have any money."],["since","chunki, …gani uchun","She enjoys hiking since it allows her to connect with nature and stay physically active."],["however","ammo (oldingi fikrga zid)","We thought the figures were correct. However, we have now discovered some errors."],["however + sifat/ravish","qanchalik … bo'lmasin","However carefully I explained, she still didn't understand."],["provided that / providing that / as long as","agar (sharti bilan)","You can take my car as long as you drive it carefully."],["unless","agar …masa","Unless she studies hard, she will fail the exam."],["as","1) chunki 2) paytda 3) sayin","As I was feeling very tired, I went to bed early. / As the days went on, the weather kept getting worse."],["such as / for example / for instance / including","masalan, jumladan","Some people, including me, believe online shopping is beneficial for the environment."],["on the one hand … on the other hand","bir tomondan … boshqa tomondan","On the one hand tourism has some advantages, but on the other hand it has several disadvantages."],["whereas / while","esa, ammo — qarama-qarshi","Some of the students show positive results, whereas others do not."],["nevertheless / nonetheless","shunga qaramasdan","There is little chance that we will succeed in changing the law. Nevertheless, it is important that we try."],["moreover / in addition / what is more / furthermore","bundan tashqari","Computers can help people work efficiently. Moreover, they can entertain workers when they are tired."],["in addition to / besides / as well as","…ga qo'shimcha","She has invited Jill as well as Kate."],["otherwise","aks holda","I'm lucky that I'm interested in school work, otherwise I'd go mad."],["as a result / consequently / thus / hence","natijada","I spent most of my money in the first week and consequently had very little to eat by the end of the holiday."],["therefore","shuning uchun","We were unable to get funding and therefore had to abandon the project."],["that is to say / in other words","ya'ni, boshqacha aytganda","One problem in cities is the cost of public transport. That is to say, in big capitals like London, the price of using public transport is extremely high."],["instead (of)","o'rniga","Instead of going to supermarkets, many people use the Internet to do their shopping."],["also","shuningdek","For a teacher to hit a child is not just morally wrong but also illegal."],["firstly / secondly / finally","birinchidan / ikkinchidan / nihoyat","Firstly, shopping online is cheaper. Secondly, it can save customers' time. Finally, it offers a wide selection of products."],["in conclusion / to conclude / in summary","xulosa qilib aytganda","In conclusion, the benefits outweigh the drawbacks."]]},{"t":"note","x":"**because / although / since / while** dan keyin **gap** (ega + fe'l) keladi; **because of / despite / in spite of / due to** dan keyin esa **ot, otli birikma yoki -ing**: _Although it rained, …_ ↔ _Despite the rain, …_"},{"t":"ex","no":"17.1","q":"Gapni ma'nosi jihatidan to'g'ri to'ldiradigan variantni tanlang.","kind":"mcq","items":[{"q":"I hurt my knee quite badly so…","o":["I had to go to hospital.","I didn't have the right running shoes."],"a":0},{"q":"I didn't work hard at school. Consequently, …","o":["I did well at university.","I failed most of my exams."],"a":1},{"q":"I believe travelling can help us to understand other cultures. Furthermore, …","o":["it can help you to become more independent.","it can be a lonely experience at times."],"a":0},{"q":"Although learning to speak a foreign language requires a lot of time and effort, …","o":["many people give up after a short time.","many people manage it successfully."],"a":1},{"q":"Fifty per cent of all newspaper readers in this country only read the sports section of the paper. In other words, …","o":["many people are not interested in news.","sports are reported very well in the newspaper."],"a":0},{"q":"Sydney is the biggest city in Australia, yet …","o":["it isn't the capital.","it is the oldest city."],"a":0},{"q":"You wouldn't be allowed to drive in my country because …","o":["there is no point in getting a car.","you need to be over 21."],"a":1},{"q":"The match was cancelled because of …","o":["the snow.","it started snowing."],"a":0},{"q":"The team went on to win the tournament, in spite of …","o":["winning all the games.","losing the first game."],"a":1},{"q":"There is currently a high demand for raw materials such as …","o":["products made in China.","oil and cotton."],"a":1}]},{"t":"ex","no":"17.2","q":"To'g'ri bog'lovchini tanlang.","kind":"mcq","items":[{"q":"I am not happy with your work. …, I am going to give you one last chance.","o":["That","Despite","Nevertheless","In spite of"],"a":2},{"q":"Sobir went on taking banknotes out of the safe … it was empty.","o":["while","before","as soon as","until"],"a":3},{"q":"… a heavy snow, we couldn't get there in time.","o":["Although","Instead of","Because","Owing to"],"a":3},{"q":"Human behaviour is mostly a product of learning, … the behaviour of an animal depends mainly on instinct.","o":["whereas","unless","so","unlike"],"a":0},{"q":"… so many of the team members were ill, it's not surprising that we lost the match.","o":["However","Due","Since","Nonetheless"],"a":2},{"q":"Shut the door, … I will get cold in here.","o":["unless","moreover","otherwise","providing that"],"a":2},{"q":"A carpenter came to fix the bed … it would be on a level with the window.","o":["so as to","so on","so that","so what"],"a":2},{"q":"He was injured. …, he was unable to play.","o":["Furthermore","But","In addition","Therefore"],"a":3},{"q":"… hungry I am, I never seem to be able to finish off a whole pizza.","o":["However","Moreover","Because","In case"],"a":0},{"q":"Most wild animals won't attack … they are provoked.","o":["as long as","in order to","unless","otherwise"],"a":2},{"q":"Eight people, …, two children, were injured in the explosion.","o":["but","nevertheless","so","including"],"a":3},{"q":"He gets more attractive … he gets older.","o":["so that","as","furthermore","despite"],"a":1},{"q":"We are in the middle of winter now, … the weather is too hot for this season.","o":["because","and","yet","so"],"a":2},{"q":"They made some bad decisions and, …, lost quite a lot of money.","o":["as well as","next to","as a result","by comparison"],"a":2},{"q":"Regular exercise increases the blood flow to your heart and keeps your heart healthy. …, it provides you with a general sense of well-being.","o":["For example","However","As a result","Similarly"],"a":3}]},{"t":"ex","no":"17.3","q":"Inshodagi har bir bo'shliq uchun mos bog'lovchini tanlang.","intro":"**Topshiriq:** _It is generally accepted that smoking causes the death of large numbers of people. In order to address this problem, governments should ban smoking in public places. Do you agree or disagree?_","kind":"mcq","items":[{"q":"Many people think that the best way to reduce deaths from smoking is to ban smoking in public places. (1) … it is not as simple as that.","o":["However","In addition"],"a":0},{"q":"There are several reasons why I do not consider this approach to be suitable. (2) …, banning activities often increases their popularity by making them seem more exciting.","o":["However","Firstly"],"a":1},{"q":"(3) …, most smoking takes place in the privacy of people's homes,","o":["Furthermore","Whereas"],"a":0},{"q":"…and would (4) … not be affected by the ban.","o":["therefore","nevertheless"],"a":0},{"q":"(5) …, a ban on smoking would make extra demands on the police.","o":["Finally","On the one hand"],"a":0},{"q":"(6) … the ideas behind banning smoking in public places are good, an alternative approach needs to be taken, in my opinion.","o":["Although","Despite"],"a":0},{"q":"Schools should lead the way in discussing the harmful effects of smoking. (7) …, parents need to support these efforts.","o":["In addition","Consequently"],"a":0},{"q":"If we adopted these measures, I believe fewer people would take up smoking, (8) …","o":["as a result","moreover"],"a":0},{"q":"To some extent, these things are already happening. (9) …, further efforts are needed.","o":["And","Nevertheless"],"a":1}]},{"t":"ex","no":"17.4","q":"Qavsdagi bog'lovchi bilan ingliz tiliga o'giring.","kind":"write","items":[{"q":"U endigina 17 yoshda va shuning uchun ovoz berish huquqiga ega emas. (therefore)","sample":"He's only 17 and therefore not eligible to vote."},{"q":"Bir tomondan ko'proq maosh oladigan ishni xohlayman, lekin boshqa tomondan hozirgi ishimdan zavqlanaman. (on the one hand, on the other hand)","sample":"On the one hand I'd like a job that pays more, but on the other hand I enjoy the work I'm doing at the moment."},{"q":"U kunduzgi talaba bo'lishdan tashqari, fitnes murabbiyi. (in addition to)","sample":"She's a fitness instructor in addition to being a full-time student."},{"q":"U sekin ishlaydi, men esa shoshilaman va xato qilaman. (whereas)","sample":"He works slowly, whereas I rush things and make mistakes."},{"q":"Qanchalik tez yursak ham, o'z vaqtida yetib bormaymiz. (however)","sample":"However fast we drive, we're not going to get there in time."},{"q":"Shoshiling, aks holda poyezddan qolib ketasiz. (otherwise)","sample":"You'd better hurry, otherwise you'll miss the train."},{"q":"Poyezdni kutishga bir necha daqiqa bor ekan, keling, bir piyola kofe ichaylik. (since)","sample":"Since we've got a few minutes to wait for the train, let's have a cup of coffee."},{"q":"U kasalligiga qaramay, oddiy hayot kechira oldi. (despite)","sample":"He was able to lead a normal life, despite the illness."},{"q":"U nafaqat kech keldi, balki kitoblarini ham unutdi. (not only … but also)","sample":"Not only did he turn up late, but he also forgot his books."},{"q":"Bu pul sayohat va turar joy kabi xarajatlarni qoplash uchun. (such as)","sample":"That money is to cover costs such as travel and accommodation."}]}],"writes":10},{"task":2,"no":18,"title":"Supporting ideas","uz":"Fikrlarni asoslash","pages":"163–169","blocks":[{"t":"p","x":"Inshoning eng muhim jihatlaridan biri — topshiriqqa aloqador **asosiy fikrlarni** topish va ularni bir-ikkita **asoslovchi fikr** bilan kengaytirish. Baholash mezonida ham topshiriqning barcha bandlari **tafsilot va misollar** bilan yoritilgani so'raladi. Asosiy fikrni shunchaki aytib, uni yoritmaslik — xato."},{"t":"table","head":["","Misol"],"rows":[["Asosiy fikr","Supermarkets keep increasing the range of services they offer."],["Asoslovchi fikr","For example, nowadays in some supermarkets you can not only buy products, but also eat with your children or use play areas for them."]]},{"t":"task","label":"Topshiriq","q":"Many people around the world spend the majority of their free time at home watching TV shows. What are the advantages and disadvantages of this situation?"},{"t":"table","head":["","Afzallik","Kamchilik"],"rows":[["Asosiy fikr","People who watch TV save more money than those who have other hobbies.","People who spend their free time watching TV may have health problems."],["Asoslovchi fikr","Many hobbies require a membership fee that must be paid regularly, whereas watching TV costs much less: once a TV is bought, there are almost no extra expenses.","They move much less than people with active hobbies. As a result, if this continues for a long time, it has a negative effect on their health."]]},{"t":"h","x":"Asoslovchi fikr asosiy fikrga mos bo'lishi kerak"},{"t":"task","q":"Some people believe that it's better to live in the countryside. Others argue that living in the city is superior. Discuss both views and give your opinion."},{"t":"table","head":["","Gap"],"rows":[["Asosiy fikr","Some people prefer to live in the countryside because it is peaceful."],["✗ Noto'g'ri asoslash","In the countryside, living is much cheaper because many families grow their own food and keep animals. (tinchlik haqida emas!)"],["✓ To'g'ri asoslash","In cities, the noise of cars and construction makes it hard to live calmly, while in the countryside, with its smaller population, such problems hardly exist."]]},{"t":"h","x":"Misol keltirish orqali asoslash"},{"t":"p","x":"Misol hayotingizdan, atrofingizdan, dunyodagi voqealardan yoki o'qigan ma'lumotlaringizdan bo'lishi mumkin. Bog'lovchilar: _for example, for instance, such as, take … as an example_."},{"t":"model","x":"My dog, Oso, is learning many new tricks. For example, he can sit, stay, and lie down.\nIn many countries punishment for crime is very strict. For instance, in China criminals can be executed for certain serious crimes.\nYou can use any two colours — such as red and yellow.\nNot everyone is employed. Take Jasmina as an example — she's still looking for a job."},{"t":"model","title":"Mashhurlikning salbiy tomonlari — misollar bilan","x":"One of the drawbacks of being famous is that people say bad things about you. For example, Bill Gates, who gives most of his money to charity, is criticized.\n\nThe second disadvantage is that you don't have a private life. For instance, many celebrities have got into trouble after getting angry with reporters and photographers who were following them.\n\nThe third negative aspect of fame is that your family may also suffer. Even your children may have paparazzi following them."},{"t":"p","x":"Ma'no tushunarli bo'lsa, _for example_ ni har doim yozish shart emas. Misol ichida yana misol ham bo'lishi mumkin: _Life in jail is far too comfortable for prisoners. For instance, many inmates have access to luxuries such as televisions, computers and sports facilities._"},{"t":"h3","x":"Asosiy fikrni asoslay olmaydigan misol — ko'p uchraydigan xato"},{"t":"table","head":["Asosiy fikr","✗ Yomon misol","✓ Yaxshi misol"],"rows":[["One advantage of being famous is that you can use your fame and money to help good causes.","For example, C. Ronaldo built his own hotels after he became a world-famous football star. (bu boshqalarga yordam emas)","For example, C. Ronaldo donated $1 million to hospitals during the coronavirus pandemic."],["Too much emphasis is put on passing exams, because pupils spend a large proportion of school time doing tests rather than learning.","For example, some exams in British schools last for two hours. (imtihon davomiyligi fikrni asoslamaydi)","For example, children in some British schools prepare for tests for weeks before the exam, but they are not taught anything new."]]},{"t":"ex","no":"18.1","q":"Asosiy fikrni mos asoslovchi gap bilan bog'lang.","kind":"match","opts":[{"k":"A","x":"You can sometimes get free delivery on some days of the week."},{"k":"B","x":"When I was a child, my mother enjoyed talking to shopkeepers and neighbours while she was shopping."},{"k":"C","x":"Some supermarkets will refund money if the same goods cost less at another supermarket."},{"k":"D","x":"You can now buy insurance and foreign currency at large supermarkets."},{"k":"E","x":"These cards provide incentives for regular customers by offering discounts, rewards, or exclusive deals."},{"k":"F","x":"The extensive product selection allows consumers to find all their essential items in one place."},{"k":"G","x":"Supermarkets contribute to local employment by hiring cashiers, stock clerks, managers and customer service staff."}],"items":[{"q":"Supermarkets are often in competition with each other.","a":"C"},{"q":"Supermarkets keep increasing the range of services they offer.","a":"D"},{"q":"Supermarket chains also offer online grocery shopping.","a":"A"},{"q":"Shopping can be an enjoyable and social experience.","a":"B"},{"q":"Supermarkets provide jobs for local people.","a":"G"},{"q":"Large supermarkets can offer a large choice of products.","a":"F"},{"q":"Some large supermarkets offer loyalty cards.","a":"E"}]},{"t":"ex","no":"18.2","q":"Bog'lovchidagi xatoni tuzating — to'g'ri shaklini yozing.","kind":"fill","text":"1. For examples, … → {1}\n2. … as such as … → {2}\n3. Take burglars is an example. → {3}\n4. For instanse, … → {4}\n5. There are some positive sides of studying alone. Such as, nobody disturbs you. → {5}","a":["For example","such as","Take burglars as an example.||Take burglars as an example","For instance","For example, nobody disturbs you.||For example, nobody disturbs you"]},{"t":"ex","no":"18.3","q":"Asosiy fikrni to'g'ri asoslaydigan misolni tanlang.","kind":"mcq","items":[{"q":"One drawback of studying abroad is that living away from home can be challenging because students may have many problems.","o":["For example, they have to complete visa applications, find accommodation and pay bills on their own.","For example, the crime rate is very high abroad and the student may be robbed in a new country."],"a":0,"why":"B — umumlashtirilgan va asossiz da'vo; asosiy fikr \"mustaqil hayot qiyinchiliklari\" haqida."},{"q":"In many situations robots can increase productivity.","o":["For instance, one robot can save money that is paid to multiple workers in a company.","For instance, they can work in manufacturing for 24 hours a day without stopping."],"a":1,"why":"A — pul tejash haqida, unumdorlik (productivity) haqida emas."},{"q":"One reason why many young people do not want to choose the teaching profession is that the salary is very low.","o":["For example, most teachers get only 2 million sums in my country.","For example, they are paid much less than other important professionals like doctors and lawyers."],"a":1,"why":"Kitob kaliti: B — taqqoslash maoshning pastligini aniqroq asoslaydi."},{"q":"If computers are used in education, students learn new skills which will be useful for their future jobs.","o":["For example, they can learn to write reports or make presentation slides using programs like Word and PowerPoint.","For example, my brother is a computer programmer and he earns a lot of money."],"a":0,"why":"B — akaning maoshi o'quvchilar o'rganadigan ko'nikmalarni asoslamaydi."},{"q":"Zoos attract tourists as they get a chance to see wild animals without having to travel far away.","o":["For example, Chinese pandas and African rhinos are endangered species, and without zoos it is almost impossible to see them in the wild.","For example, in zoos in our country there are many endangered species such as the Chinese panda and African rhinos, and we enjoy watching them."],"a":0}]},{"t":"ex","no":"18.4","q":"Gaplarni mos misollar bilan to'ldiring.","kind":"write","items":[{"q":"There are numerous things individuals can do to help the environment, such as …","sample":"…such as planting trees, collecting rubbish in the streets or conserving drinking water."},{"q":"Living in the countryside can have its disadvantages. Take …","sample":"Take the internet connection as an example. It is often weak in villages, and you find it hard to go online."},{"q":"We often see children doing hard physical work. For example, …","sample":"For example, in some places in Africa children have to carry drinking water from far away, so they cannot go to school."},{"q":"Many people feel that boxing should be banned as it is dangerous. It is their view that the sport is barbaric and that too many people are seriously injured in the ring. For example, …","sample":"For example, many boxers lose consciousness or get serious facial wounds during fights."},{"q":"Television is actually a good thing for children. It is educational and, in fact, it helps them learn. For instance, …","sample":"For instance, they can broaden their knowledge about wild animals and nature by watching wildlife documentaries."},{"q":"Women make better teachers than men. Women have natural skills which they are able to transfer to the classroom. For example, …","sample":"For example, female teachers often create a caring environment in classrooms, making students feel supported and comfortable, which helps them learn better."}]}],"writes":6},{"task":2,"no":19,"title":"Advantages and disadvantages essays","uz":"Afzallik va kamchiliklar inshosi","pages":"170–182","blocks":[{"t":"p","x":"Writing bo'limida biror vaziyatning **ijobiy va salbiy tomonlarini** yoritish so'ralishi mumkin. Savol odatda ikki xil bo'ladi:"},{"t":"list","ordered":true,"items":["**Do the advantages of the situation outweigh the disadvantages?** — ijobiy va salbiy tomonlarni yoritib, **qaysi biri ustun** ekanini ko'rsatish shart.","**What are the advantages and disadvantages of the situation?** — faqat ijobiy va salbiy tomonlarni keltirasiz, qaysi biri ustunligini aytish shart emas."]},{"t":"table","head":["","Sinonimlar"],"rows":[["advantage","benefit, upside, positive side, merit"],["disadvantage","drawback, downside, negative side, demerit, problem"]]},{"t":"note","x":"Baholash mezoniga ko'ra insho kamida **250 so'z** bo'lishi kerak."},{"t":"h3","x":"Nechta asosiy g'oya kerak?"},{"t":"list","items":["**1-tur savol (outweigh)** — 3 ta g'oya: o'zingiz qo'shiladigan tomonga 2 ta, qarshi tomonga 1 ta (2+1). Shu bilan pozitsiyangizni asoslaysiz.","**2-tur savol** — 4 ta g'oya: 2 ta afzallik + 2 ta kamchilik, chunki savolda _advantages and disadvantages_ ko'plikda."]},{"t":"h3","x":"Savolni to'g'ri tushunish"},{"t":"p","x":"Savolda odatda **umumiy mavzu** va uning ichida **maxsus mavzu** bo'ladi; ko'pchilik umumiy mavzu haqida yozib, maxsus mavzuni e'tibordan chetda qoldiradi. Ikki xavf: 1) yozishga shoshilish — C1 maqsad qilsangiz, avval savolni tahlil qilib, reja tuzing; 2) savoldagi so'zni tushunmaslik (masalan, _boarding school_ = maktab-internat, chet eldagi maktab emas)."},{"t":"task","label":"Namuna topshiriq","q":"Some university students live with their families while studying, but others prefer to move away from home.\nDo the benefits of moving out to attend university outweigh the disadvantages?"},{"t":"p","x":"Kalit qismlar: _university students · while studying · live with their families · move away from home_; savol: _benefits · moving out to attend university · outweigh · disadvantages_.\n**Kamchiliklar:** 1) increased cost of living; 2) reduced focus on studies. **Afzallik:** 1) gaining independence."},{"t":"table","head":["Qism","Mazmun"],"rows":[["Introduction","Topshiriq parafrazasi + pozitsiya + 3 ta asosiy g'oya"],["Body 1","Increased cost of living"],["Body 2","Reduced focus on studies"],["Body 3","Gaining independence"],["Conclusion","Mavzu + pozitsiya + asosiy g'oyalar (parafraza bilan)"]]},{"t":"p","x":"Paragraf tuzilishi: **Main idea → Supporting sentence → Example** (yoki Main idea → Example → Supporting sentence). Odatda paragraf 3–4 gapdan iborat."},{"t":"h","x":"Introduction"},{"t":"list","ordered":true,"items":["Paraphrasing the topic","State your position","Mention the main ideas"]},{"t":"model","x":"Some students stay at their family home while attending university, but other students decide to move out. (parafraza)\nThe advantages of moving away from home to attend university do not outweigh the drawbacks because the main disadvantages are the cost of living and the lack of focus on studies, whereas the only advantage is learning to be independent. (pozitsiya + g'oyalar)"},{"t":"phr","title":"Pozitsiya gapi shablonlari","items":["The advantages outweigh the disadvantages because the main advantages are A and B, whereas the only disadvantage is C.","This has more disadvantages because the main disadvantages are A and B, whereas the main advantage is C.","This has more advantages because the main advantages are A and B, whereas the main disadvantage is C."]},{"t":"h","x":"Body paragraphs"},{"t":"note","x":"Har bir paragraf faqat **bitta** g'oyani to'liq yoritadi. Bir paragrafda ham ijobiy, ham salbiy tomonni yozish — xato (bir paragrafda ikkita ijobiy yoki ikkita salbiy tomon bo'lishi mumkin)."},{"t":"p","x":"**Topic sentence** — paragraf nima haqida ekanini aytadi: _The first disadvantage of [topic] is [main idea]._ Bu yerda introduction yoki savoldagi so'zlarni aynan ko'chirmang — parafraza qiling: _move away from home → living away from home; cost of living → increased cost of living_."},{"t":"phr","title":"Topic sentences","items":["The first disadvantage of living away from home is the increased cost of living.","Another downside is that students who move out of home tend to be less focused on their studies.","However, there is the advantage in having more independence."]},{"t":"h","x":"Conclusion"},{"t":"p","x":"Yangi g'oya qo'shilmaydi. _In conclusion / To conclude_ bilan boshlab: 1) bahs mavzusi, 2) pozitsiyangiz, 3) asosiy g'oyalar — barchasi parafraza bilan."},{"t":"model","title":"To'liq insho","x":"Some students stay at their family home while attending university, but other students decide to move out. The advantages of moving away from home to attend university do not outweigh the drawbacks because the main disadvantages are the cost of living and the lack of focus on studies, whereas the only advantage is learning to be independent.\n\nThe first disadvantage of living away from home is the increased cost of living. That is to say that there are extra costs such as accommodation that don't need to be paid by those who stay with their families. As it usually takes four years to complete a university degree, these costs put considerable strain on an average family's finances.\n\nAnother downside is that students who move out of home tend to be less focused on their studies. Because they have nobody making sure they attend university every day, they are far more likely to skip lectures when they're tired or not in the mood. When I was at college, for instance, it was very rare for someone who lived with their parents to miss a lecture, which was not the case for those in rented accommodation.\n\nHowever, there is the advantage in having more independence. Students who live away from family are responsible for all aspects of their lives and need to complete household chores that their family members would otherwise complete. From these responsibilities, they become more independent, and this independence generally translates into other situations as well.\n\nIn conclusion, the advantages of moving away from home to study at university do not outweigh the disadvantages as this costs substantially more money, and these students are less focused on their studies. But, on the other hand, there is the advantage of becoming more independent."},{"t":"ex","no":"19.1","q":"So'z \"good point\" (ijobiy) yoki \"bad point\" (salbiy) guruhigami?","kind":"tf","opts":["Good point","Bad point"],"items":[{"q":"downside","a":1},{"q":"drawback","a":1},{"q":"benefit","a":0},{"q":"negative aspect","a":1},{"q":"advantage","a":0},{"q":"merits","a":0},{"q":"disadvantage","a":1},{"q":"demerit","a":1},{"q":"upside","a":0},{"q":"positive point","a":0},{"q":"problem","a":1}]},{"t":"ex","no":"19.2","q":"Zoopark haqidagi insho uchun 2- va 3-paragraflarning main idea, supporting sentence va example'ini rejalashtiring.","intro":"**Topshiriq:** _Some experts believe it is better for animals to live in zoos where they are safe and are given all the food they need. Do the advantages of keeping animals in zoos outweigh the disadvantages?_ **Paragraf 1 (namuna):** Advantage — safety and protection from predators → provide a secure environment, food and medical care, leading to a longer lifespan → the Galapagos giant tortoise was saved from extinction thanks to zoos.","kind":"write","items":[{"q":"Paragraf 2 — Advantage","rows":4,"sample":"Main idea: educational and fun. Supporting sentence: families are entertained and children learn about wildlife. Example: in many zoos children can come close to, feed and touch the animals."},{"q":"Paragraf 3 — Disadvantage","rows":4,"sample":"Main idea: restricted freedom. Supporting sentence: in captivity animals lose their natural behaviours and instincts. Example: many animals, when released, cannot hunt or escape predators and easily die."}]},{"t":"ex","no":"19.3","q":"Berilgan reja asosida kirish (introduction) yozing.","intro":"**Topshiriq:** _Some people think that playing video games is useful. Others, however, believe that video games are having a negative effect on the people who play them. Do the drawbacks of video games outweigh the benefits?_ **Reja:** 1) Advantage — educational; 2) Advantage — entertaining; 3) Disadvantage — addictive.","kind":"write","items":[{"q":"Introduction:","rows":5,"sample":"Many people, and children in particular, enjoy playing computer games, but other people think they are more likely to have a harmful impact on the user. The advantages of playing computer games outweigh the drawbacks because the main advantages are that they can be educational and entertaining, whereas the only disadvantage is their addictive nature."}]},{"t":"ex","no":"19.4","q":"O'zbekcha paragrafni ingliz tiliga o'giring.","kind":"write","items":[{"q":"Video o'yinlarning afzalliklaridan biri — ularning ta'lim beruvchi vosita bo'la olishidir. Bu o'yinlar foydalanuvchining ijodkorligi, diqqatni jamlashi, mantiqiy fikrlash va muammoni hal qilish qobiliyatini rivojlantiradi. Masalan, poyga o'yinlarida ishtirokchi g'olib bo'lishi uchun raqiblarni diqqat bilan tahlil qiladi, turli o'lchovlarni hisoblaydi va eng yaqin yo'llarni o'ylab topadi. Bunday qobiliyatlar real hayotdagi vazifalarni uddalashga yordam beradi.","rows":6,"sample":"One of the advantages of video games is that they can be an educational tool. These games develop the user's creativity, concentration, logical thinking and problem-solving skills. For example, in racing games, the participant carefully analyses the opponents, makes various calculations and works out the shortest routes to win. Such skills will help them to cope with real-life tasks."}]},{"t":"ex","no":"19.5","q":"Reja asosida keyingi paragrafni yozing.","kind":"write","items":[{"q":"Source of entertainment → transfer to a virtual world → exciting and unique experience → when playing Blur racing games, the user dives into imaginative landscapes → relieves stress, relaxation, overall well-being.","rows":6,"sample":"Another advantage of video games is their ability to serve as a source of entertainment. These games offer a gateway to the virtual world, providing an exciting and unique experience. When playing games like Blur racing, users dive into imaginative landscapes, leaving the real world behind. This immersive escape not only offers a thrilling pastime but also serves as a means to relieve stress, achieve relaxation, and thus enhance overall well-being."}]},{"t":"ex","no":"19.6","q":"Video o'yinlarning salbiy tomoni haqida paragraf yozing (avval main idea, supporting idea va example'ni rejalang). \"However,\" bilan boshlang.","kind":"write","items":[{"q":"Body paragraph 3 (disadvantage):","rows":6,"sample":"However, there is a disadvantage in becoming addicted to playing games. Games can be very addictive because they keep giving players scores, new goals, and rewards to make them keep playing. Nowadays, many children spend lots of time each day trying to reach higher levels in a game or beat their friends' scores. This kind of addiction can cause issues, from not getting enough sleep to having problems at school when homework is ignored in favour of spending more time on the computer or game console."}]},{"t":"ex","no":"19.7","q":"Video o'yinlar haqidagi insho uchun xulosa yozing: mavzu, asosiy g'oyalar va pozitsiya.","kind":"write","items":[{"q":"Conclusion:","rows":4,"sample":"In conclusion, playing video games has various effects on a gamer's life. They serve as effective educational tools and sources of entertainment despite the risk of addiction. Overall, the benefits of playing video games generally outweigh the drawbacks."}]},{"t":"p","x":"**19.8.** To'liq insholar (fast food; being a celebrity) — **Yozish xonasi**da."}],"writes":7},{"task":2,"no":20,"title":"Agree or disagree essays","uz":"Fikr bildirish (qo'shilish / qo'shilmaslik) inshosi","pages":"183–190","blocks":[{"t":"p","x":"**Agree or disagree** turida jamiyatdagi biror muammo yoki fikr beriladi va siz unga qo'shilish yoki qo'shilmasligingizni ikki asosiy g'oya bilan asoslab yozasiz."},{"t":"task","label":"Namuna topshiriq","q":"Some people believe that we should replace all plastic products with more environmentally-friendly materials, such as glass.\nDo you agree or disagree?"},{"t":"p","x":"Savol boshqa ko'rinishlarda ham keladi: _To what extent do you agree or disagree? / … with this opinion? / … with this statement? / Is this a positive or a negative development?_"},{"t":"h3","x":"Uch xil pozitsiya"},{"t":"list","ordered":true,"items":["Completely agree — to'liq qo'shilaman","Completely disagree — umuman qo'shilmayman","Partially agree and disagree — qisman qo'shilaman"]},{"t":"note","x":"Tavsiya: **to'liq qo'shiling yoki umuman qo'shilmang** — bitta tomonda tursangiz, fikringiz butun insho davomida aniq bo'ladi. Savolda _To what extent_ bo'lsa, darajani albatta ayting: _I completely disagree_ (shunchaki _I agree_ emas)."},{"t":"h3","x":"Reja va g'oyalar"},{"t":"list","items":["Asosiy g'oyalarni shakllantiring va ular mavzuga aloqador ekaniga ishonch hosil qiling.","Har bir g'oyaga tushuntirish va/yoki misol toping, ular ham mavzuga taalluqli bo'lsin.","Reja 2–3 daqiqada tuziladigan bo'lib qoladi."]},{"t":"p","x":"**Ko'p xatolar:** 1) o'zingiz to'liq tushunmagan g'oyani yozish; 2) \"yaxshiroq, hayratlanarli\" g'oya izlab vaqt yo'qotish — g'oya mavzuga taalluqli bo'lsa bas; 3) xayoliy misollar — real hayotiy tajriba va dunyo haqidagi bilimdan foydalaning."},{"t":"task","label":"Namuna #1","q":"Some people believe that modern technology, such as the internet and smartphones, creates more problems than it solves.\nTo what extent do you agree or disagree with this opinion?"},{"t":"table","head":["","Main idea","Explanation","Example"],"rows":[["Body 1","people's mental health is suffering","they don't spend time on themselves / reflecting","people in queues usually look at their phones"],["Body 2","free time is not enjoyable nowadays","video games need minimal effort but are less rewarding than sport or gardening","my family members used to have outdoor hobbies"]]},{"t":"h3","x":"Introduction"},{"t":"p","x":"1-gap — topshiriq parafrazasi; 2-gap — to'liq pozitsiya va ikki asosiy g'oya. **Introductionda birinchi aytilgan g'oya birinchi paragrafda, ikkinchisi ikkinchi paragrafda** yozilishi shart — aks holda Coherence and Cohesion bahosi tushadi."},{"t":"p","x":"Parafraza: _some people believe → some individuals think; modern technology → technology from the modern era; problems → issues; solve → resolve_."},{"t":"h3","x":"Body paragraphs"},{"t":"p","x":"Har bir paragraf bitta asosiy g'oyaga asoslanadi va **topic sentence** bilan boshlanadi."},{"t":"h3","x":"Conclusion"},{"t":"p","x":"Pozitsiyani yana bir bor ta'kidlab, asosiy g'oyalarni parafraza bilan qaytaring. **Yangi fikr qo'shmang.**"},{"t":"model","title":"To'liq insho (Namuna #1)","x":"Some individuals think that technology from the modern era, like the internet and smartphones, is creating more issues than it is resolving. I completely agree with this statement because people's mental health is suffering and, also, people don't enjoy their free time as much as they used to.\n\nFirst of all, modern technology is negatively affecting the mental health of many individuals. This is because an essential aspect of good mental health is processing what happens to us, particularly any negative experiences. However, with modern technology, many people don't take any time to reflect on their lives and instead spend all of their available time on the internet or watching television. These days, for instance, most customers in supermarket queues look at something on their phones, whereas before this technology, they had no option but to think about whatever came to mind.\n\nAnother drawback is the way that this technology has hindered how much people enjoy their leisure time. Passing the time with modern technology, such as phone apps or video games, requires minimal effort but is not as enjoyable or rewarding as hobbies such as playing a sport or gardening, which were more popular in the past. For example, in my family, most members had various outdoor pursuits that they did in the evenings, but now it's more common to see them sitting inside the house on their phones.\n\nIn conclusion, I agree that the advent of modern technology has created more issues than it has solved because of the decline in mental health that it has brought and the resulting lack of enjoyment that people experience in their free time."},{"t":"ex","no":"20.1","q":"Gaplarni parafraza qiling.","kind":"write","items":[{"q":"Some people believe that the government should provide free education at all levels.","sample":"There is a belief held by some individuals that the government should offer education free of charge at all educational levels."},{"q":"In today's society, it is often said that money is the key to happiness.","sample":"It is a common view in contemporary society that money is the main source of happiness."},{"q":"Technology has made it easier for people to communicate and connect with others, but it has also led to a decline in face-to-face interactions.","sample":"While technology has facilitated communication and connections among people, it has also contributed to a reduction in in-person interactions."},{"q":"Some argue that the best way to reduce crime is to implement stricter punishment for offenders.","sample":"Some individuals claim that imposing stricter penalties on offenders is the most effective approach to reducing crime."},{"q":"In many countries, people are living longer due to advances in healthcare. Some individuals believe that this trend has negative consequences for the economy and society.","sample":"Due to advancements in healthcare, life expectancy has increased in most nations. Some individuals argue that this phenomenon has adverse implications for the economy and society."},{"q":"Advertising plays a significant role in shaping people's choices and preferences.","sample":"The influence of advertising in shaping people's preferences and choices is considerable."},{"q":"Some people think that young individuals should be required to do unpaid community service in their spare time.","sample":"There are those who believe that young individuals should be encouraged to engage in unpaid community service during their free time."}]},{"t":"ex","no":"20.2","q":"Mavzu bo'yicha reja tuzing: pozitsiya, 2 ta main idea, har biriga explanation va example.","intro":"**Namuna:** _Some people believe that students should study practical skills at school such as managing a bank account or car maintenance as well as traditional subjects. To what extent do you agree or disagree?_ → **Plan — completely disagree.** Main idea 1: students already have too much to learn at school (explanation: less time with friends and for hobbies; example: Irish students' free time decreased after extra lessons were introduced in the 90s). Main idea 2: it's better to learn practical skills when they are required (explanation: skills tend to disappear if not used; example: in Switzerland a person should retake the driving test).","kind":"write","items":[{"q":"As the average age at which people get married increases, some people worry that it will have a negative impact on the family. To what extent do you agree or disagree?","rows":5},{"q":"Some people believe that parents should limit how much time their children spend watching TV and encourage them to read books instead. To what extent do you agree or disagree with this statement?","rows":5},{"q":"The role of artificial intelligence in our lives is increasing. Do you agree or disagree?","rows":5},{"q":"Some people believe that the government should provide free education at all levels. Do you agree or disagree with this statement?","rows":5},{"q":"Some people think that young individuals should be required to do unpaid community service in their spare time. Do you agree or disagree with this idea?","rows":5}]},{"t":"ex","no":"20.3","q":"Berilgan reja asosida ikkita asosiy paragraf yozing.","intro":"**Topshiriq:** _Governments should spend more money on education than on recreation and sports. To what extent do you agree or disagree?_ **Plan — completely agree.** Main idea 1: education benefits an economy in the long term (a skilled workforce leads to innovation and productivity; e.g. South Korea and Finland decided to invest heavily in education). Main idea 2: education has many social benefits (well-educated people are more aware of harms like drugs and alcohol; e.g. Singapore has one of the lowest levels of drug abuse thanks to educated citizens).","kind":"write","items":[{"q":"Body paragraph 1","rows":7},{"q":"Body paragraph 2","rows":7}]},{"t":"p","x":"**20.4.** To'liq insholar (shaharmi yoki qishloqmi; sun'iy intellekt) — **Yozish xonasi**da."}],"writes":14},{"task":2,"no":21,"title":"Discuss both views and give your opinion","uz":"Ikki tomonni muhokama qilib, fikr bildirish","pages":"191–200","blocks":[{"t":"p","x":"**Discuss both views and give your opinion** turida bitta vaziyat bo'yicha ikki xil fikr beriladi. Ikkala tomonni ham muhokama qilib, o'zingiz qaysi tomonda ekaningizni aniq ko'rsatishingiz kerak."},{"t":"task","label":"Namuna topshiriq","q":"Some people believe that it's better to live in the countryside. Others argue that living in the city is superior.\nDiscuss both views and give your own opinion."},{"t":"p","x":"Odatda **5 paragrafli** insho: Introduction + 3 ta body (har birida bitta g'oya) + Conclusion."},{"t":"note","x":"Faqat bir tomonni yoritsangiz, topshiriq to'liq bajarilmagan hisoblanadi — **ikkala** tomon muhokama qilinishi shart."},{"t":"list","ordered":true,"items":["Body 1 — nega ba'zi odamlar birinchi fikrda; Body 2 — nega boshqalar ikkinchi fikrda; Body 3 — sizning fikringiz (qo'shilgan tomoningiz bo'yicha).","Avval ikki tomonni yoritib, uchinchi paragrafda o'z fikringizni bildirish mantiqliroq.","O'zingiz qo'shilgan tomonga jami **2 ta** g'oya, qarshi tomonga **1 ta** g'oya yozing — pozitsiyangiz aniq ko'rinadi."]},{"t":"p","x":"Bir tomon g'oyasini yozayotganda, uni boshqa tomon bilan **solishtiring**: masalan, shaharda yashashning afzalligini aytsangiz, bu afzallik qishloqda yo'qligini ham ta'kidlang."},{"t":"h3","x":"Reja"},{"t":"table","head":["Tomon","G'oya → izoh → misol"],"rows":[["Qishloq 1","peaceful, no noise → no rest from traffic and construction in the city → trucks near my city home blow their horns all night"],["Qishloq 2","private outdoor space → country homes have their own land, city homes rarely do → space for parties with friends and hobbies"],["Qishloq 3","closer to nature → trees in cities are disappearing → last year many trees were cut down in Tashkent, causing dust storms"],["Shahar 1","closer to work → villagers commute for hours → city dwellers have more free time"],["Shahar 2","more job opportunities → factories and a large population → a London survey: the main reason people move to cities is jobs"]]},{"t":"p","x":"Qishloq tomoniga ko'proq g'oya topildi — demak, shu tomonni tanlaymiz."},{"t":"h3","x":"Introduction"},{"t":"p","x":"1-gap: ikki tomonni keltiruvchi parafraza (while bilan): _some people believe → there are individuals who feel; others argue → others feel; in the countryside → in a rural area; superior → a better choice_.\n2-gap: Although / While bilan murakkab gap — qarshi tomon va o'z pozitsiyangiz. **I do believe** — kuchaytirilgan fe'l (\"chindan ham ishonamanki\"); _I do feel, I do hope_ ham shunday."},{"t":"model","x":"There are individuals who feel that living in a rural area is more beneficial, while others feel that the city is a better choice. Although there are some advantages of living in the city, I do believe living in the countryside has more positive sides."},{"t":"h3","x":"Body paragraphs"},{"t":"phr","title":"Paragraf boshlanishlari","items":["On the one hand, some individuals like the countryside best as it's more peaceful.","On the other hand, other individuals like city life best because the short journey to and from work is a significant advantage.","My opinion is that life in the countryside is better as private outdoor space is an enjoyable feature."]},{"t":"h3","x":"Conclusion"},{"t":"p","x":"Asosiy g'oyalarni parafraza bilan qaytaring va pozitsiyangizni yana ayting. Task achievement C1 talabi — **pozitsiya butun insho davomida aniq ko'rinishi**: Introduction, bitta body paragraf va Conclusion'da."},{"t":"model","title":"To'liq insho","x":"There are individuals who feel that living in a rural area is more beneficial, while others feel that the city is a better choice. Although there are some advantages of living in the city, I do believe living in the countryside has more positive sides.\n\nOn the one hand, some individuals like the countryside best as it's more peaceful. With all the noise from traffic and construction in urban areas, it's difficult to relax. Where I live, for example, trucks on the nearby highway blow their horns all through the night, and this regularly affects my sleep.\n\nOn the other hand, other individuals like city life best because the short journey to and from work is a significant advantage. As people in the countryside often spend hours commuting between their house and workplace, they lose a lot of time compared to those in the city. This means that people who live in urban areas have additional free time and get to spend it doing things they enjoy.\n\nMy opinion is that life in the countryside is better as private outdoor space is an enjoyable feature. Houses in the country tend to have space outside that belongs to the owner, but this is rare for city houses. Having this land is a massive benefit as it can be used for barbecue parties with friends and family.\n\nIn conclusion, some people prefer to live in the country as they are more relaxed in the peaceful environment. In contrast, others who prefer to live in a city enjoy the benefits of having a short commute to work. However, my own opinion is that countryside life is more enjoyable because of the private outdoor space."},{"t":"ex","no":"21.1","q":"Gaplarni parafraza qiling.","intro":"**Namuna:** _In some countries, companies allow people to work from home. In others, people are still expected to work in an office._ → _While certain countries permit employees to work remotely, some nations continue to require individuals to fulfil their work duties in an office._","kind":"write","items":[{"q":"Many university students want to learn about different subjects in addition to their main subjects. Others feel it is more important to give all their time and attention to studying for their qualification.","sample":"Many university students aspire to acquire knowledge of various subjects alongside their majors, while others believe in dedicating their full time and attention to their qualification."},{"q":"Some believe that students should begin learning a language very early in school while others think these subjects should be taught later.","sample":"There is a debate on whether students should begin learning a language at an early stage in school, or whether this subject should be introduced later."},{"q":"Some people prefer to spend their lives doing the same things and avoiding changes. Others, however, think that change is always a good thing.","sample":"Some individuals prefer to do the same things and resist change throughout their lives, whereas others embrace change as a positive force."},{"q":"Some think newspapers are the best method for reading the news while others think other media is better.","sample":"There are some people who think that newspapers are the best way to get the news, while others argue that alternative media sources are better."},{"q":"As the number of cars increases, more money has to be spent on road systems. Some people think the government should pay for this. Others, however, think that drivers should cover the costs.","sample":"With the increasing number of cars on the roads, more money needs to be spent on maintaining them. People have different opinions on whether the government or drivers should cover this budget."},{"q":"Some people believe that car-free days are effective ways to reduce air pollution. However, others argue that there are other ways that are more effective.","sample":"While some individuals think that one of the best methods to cut air pollution is to introduce days when nobody drives a car, others believe that there are more efficient ways to do it."},{"q":"Some believe that money for education should mainly be spent on better computers while others believe it would be better spent on teachers.","sample":"Some argue that the budget allocated to education should mostly be spent on computers, whereas others claim that investing in teachers is much better."}]},{"t":"ex","no":"21.2","q":"Har bir topshiriq uchun 3 g'oyali reja tuzing (2 ta tomon + o'z fikringiz; izoh va misol bilan).","intro":"**Namuna:** _In an era of globalization, some people think that studying abroad is the best way to attain a well-paid job, while others believe other options are better._ → Main idea 1: studying abroad lets you build a network and understand the world. Main idea 2: you can gain experience in any profession regardless of location. Main idea 3 (my opinion): learning modern skills via online courses is best — no extra costs or tuition fees; e.g. social media marketing can be learned anywhere, and companies pay well for qualified candidates.","kind":"write","items":[{"q":"Some people believe that professionals, such as doctors and engineers, should be required to work in the country where they did their training. Others believe they should be free to work in another country if they wish.","rows":5,"sample":"Main idea 1 — a debt of gratitude to the country of training: professionals rely heavily on government and educational resources. Main idea 2 — everybody has the right to choose where to live and work: people from less developed countries may gain more experience abroad. My opinion — working in the country of origin helps to reduce the shortage of skilled workers; if every professional leaves, it is unfair to that nation."},{"q":"Some feel that cities should be designed to be beautiful while others feel their functionality is more important.","rows":5,"sample":"Main idea 1 — beautiful cities attract more tourists, which boosts the economy and reduces unemployment (e.g. Dubai). Main idea 2 — residents' living standards should come first: a city must be well planned; climate-resistant housing matters more than appearance. My opinion — building cities only for tourists may increase air pollution in the long term (more flights; e.g. Istanbul's infrastructure struggles with 20 million visitors a year)."},{"q":"Some people think it is better to have many short holidays during the year. Others believe it would be beneficial to have fewer, longer vacations.","rows":5,"sample":"Main idea 1 — short breaks give children more time to relax; long periods of study harm their psychology. Main idea 2 — it can be hard to readjust after frequent breaks; students may become lazier. My opinion — longer vacations allow children to attend summer camps, make friends and develop social skills."},{"q":"Some people say that individuals should change jobs often during their working life, while others believe that doing the same job has advantages to individuals, companies, and society.","rows":5,"sample":"Main idea 1 — companies profit from staying employees (no need to hire and train new staff), and loyal workers get promotions and raises. Main idea 2 — the opportunities people miss by not changing jobs are significant; an unhappy worker can improve their situation. My opinion — people's preferences change with age; staying in one field may hinder other talents (e.g. my uncle was a waiter until he tried playing the guitar)."},{"q":"Some say that children should be taught at school to recycle and avoid waste. Others say they should learn this at home.","rows":5,"sample":"Main idea 1 — group activities at school encourage competitiveness and passion; alone at home children may not feel responsible. Main idea 2 — schoolchildren already have many subjects, so this is extra pressure; parents should teach recycling before school age. My opinion — children obey their parents more than teachers, so parents as role models are more effective."}]},{"t":"ex","no":"21.3","q":"Topshiriq va g'oyalar asosida to'liq Introduction yozing.","kind":"write","items":[{"q":"Some people think children should have the freedom to make mistakes, while other people believe that adults should prevent children from making mistakes. Discuss both sides and give your opinion. — Main idea 1: children should have a sense of autonomy. Main idea 2: repeated mistakes may lead to a child's misbehaviour. Main idea 3 (opinion): mistakes help children become strong adults.","rows":5,"sample":"It is argued by some individuals that children should be free to make mistakes, whereas others feel that adults should help them avoid making mistakes. People who agree with allowing children to make errors think they need a sense of autonomy, while others feel that repeated mistakes may lead to misbehaviour. I feel that mistakes help children to become strong adults in the long term."},{"q":"Some people think that individuals today are more dependent on each other. Others believe people have become more independent. Discuss both views and give your own opinion. — Main idea 1: technology is helping people be more independent. Main idea 2: people feel more need for social bonds in today's stressful world. Main idea 3 (opinion): even young people are trying to support their own education and living costs.","rows":5,"sample":"Some feel that individuals today rely on each other more, while others think they are more independent. Technology is helping people to be more independent, whereas people feel more need for social bonds in today's stressful world. I believe people are now more independent, since even young people are trying to support their own education and living costs."}]},{"t":"ex","no":"21.4","q":"Berilgan topshiriq bo'yicha uchta body paragrafni yozing.","intro":"**Topshiriq:** _Some people believe that team sports prepare children for their future careers, while others do not agree. Discuss both views and give your own opinion._","kind":"write","items":[{"q":"A) O'zbekcha paragrafni ingliz tiliga o'giring: Ba'zi odamlar jamoaviy sport bolalarga qanday hamkorlik qilishni o'rgatadi va bu kelajakdagi martabasida yordam beradi, deb hisoblashadi. Muvaffaqiyatga erishadigan yagona jamoa — a'zolari yutqazmaslik uchun birgalikda harakat qiladigan jamoadir. Jamoaviy sportda bu mahorat bolalar shug'ullanadigan boshqa mashg'ulotlarga qaraganda ko'proq namoyon bo'ladi va natijada jamoada o'ynaganlar keyingi hayotda jamoada ishlashda ustunlikka ega bo'ladilar.","rows":6,"sample":"Some individuals believe that team sports teach children how to cooperate and this helps with future careers. The only teams that succeed are those whose members work together to avoid losing. In team sports, this skill is more apparent than in any other activity that children engage in, and, as a result, those who play on a team have an advantage when working in a team later in life."},{"q":"B) Reja asosida 2-paragrafni yozing: competition in team sports often leads to cheating → children may want to win at all costs → in the workplace, such an attitude may help only in the short term.","rows":6,"sample":"Those who feel that team sports are not an advantage understand that this type of competition often leads to cheating. Compared to playing other sports, children are more likely to be encouraged to cheat by their team members due to the desire to win at all costs. As this mentality is then brought to the workplace, it only allows for short-term success and inevitably leads to shame and the loss of jobs."},{"q":"C) 3-paragraf uchun o'zingiz asosiy g'oya toping va paragraf yozing (o'z fikringiz).","rows":6,"sample":"My opinion is that team sports help children in their future careers because they learn the value of working hard. Success doesn't come easily, and children who play on a team understand that they must work hard to win. This realization transfers directly into one's career, as they know that hard work will result in success."}]},{"t":"p","x":"**21.5.** To'liq insholar (kasb tanlash; texnologiya va boylar–kambag'allar farqi) — **Yozish xonasi**da."}],"writes":17},{"task":2,"no":22,"title":"Problem and solution essays","uz":"Muammo (sabab) va yechim inshosi","pages":"201–210","blocks":[{"t":"p","x":"Bu turdagi insholar ikki xil bo'ladi:"},{"t":"list","ordered":true,"items":["**Problems and Solutions** — vaziyatdan kelib chiqadigan **muammolar** va yechimlar.","**Causes (Reasons) and Solutions** — muammoli vaziyatning **sabablari** va yechimlari."]},{"t":"task","label":"1. Problem and solution","q":"People who live in large cities face a range of problems in their daily life.\nWhat are the main problems people in cities face?\nHow can these problems be tackled?"},{"t":"task","label":"2. Reason and solution","q":"These days, in many countries, fewer and fewer people want to become teachers, particularly in secondary schools.\nWhat are the reasons for this?\nHow could the problem be solved?"},{"t":"note","x":"Ikkala holatda ham yechimlar yoziladi. Lekin savol **muammoni** so'rayaptimi yoki **sababini** so'rayaptimi — farqlang: ikkinchi turda muammoni emas, uning sabablarini yoritasiz."},{"t":"task","label":"Namuna","q":"In many countries, there is an increase in the number of serious crimes committed by young people.\nWhat do you think are the causes of this situation?\nWhat measures could be taken to solve this problem?"},{"t":"table","head":["Qism","Mazmun"],"rows":[["Introduction","Parafraza + 2 sabab + 2 yechim (qisqa)"],["Body 1","2 ta sabab"],["Body 2","2 ta yechim (muhimrog'i birinchi)"],["Conclusion","Mavzu + sabablar + yechimlar (parafraza bilan)"]]},{"t":"h3","x":"Reja: har bir sababga — yechim"},{"t":"table","head":["Reasons","Solutions"],"rows":[["many parents are too busy","governments should reduce the number of hours that parents work"],["children have easy access to violent movies","websites with mature content should set restrictions based on the visitor's age"]]},{"t":"h3","x":"Introduction"},{"t":"p","x":"Parafraza: _In many countries → In many nations; an increase → rising; committed → committing_."},{"t":"model","x":"In many nations, rising numbers of young people are committing serious crimes. This is happening because many parents are too busy, and children have easy access to violent movies. To resolve this issue, governments should enforce a maximum number of hours that people can work, and websites with mature content should require their visitors to register."},{"t":"h3","x":"Body 1 — sabablar"},{"t":"p","x":"Birinchi gap — asosiy sabab; keyingi gap — u qanday qilib muammoga olib kelishini asoslaydi. Ikkinchi sababni _Furthermore / Moreover / Another reason is_ bilan kiriting."},{"t":"h3","x":"Body 2 — yechimlar"},{"t":"p","x":"Yechimni aytib, uning **samarasini** (natijasini) asoslang; ikkinchi yechimni _In addition to this_ bilan kiriting."},{"t":"h3","x":"Conclusion"},{"t":"p","x":"1) mavzuni eslatish, 2) sabablarni qisqa keltirish, 3) yechimlarni qisqa keltirish. Tuzilishi introductionga o'xshaydi."},{"t":"model","title":"To'liq insho","x":"In many nations, rising numbers of young people are committing serious crimes. This is happening because many parents are too busy, and children have easy access to violent movies. To resolve this issue, governments should enforce a maximum number of hours that people can work, and websites with mature content should require their visitors to register.\n\nOne of the primary reasons for more crimes being committed by young people is that parents must work longer hours. Because they don't have the time to care for their children properly, some young people use the additional freedom to explore criminal activities. Furthermore, with the advent of the internet, young people can easily access inappropriate films, and some come to admire the violent characters portrayed and so imitate the behaviour they observe.\n\nThe first way this can be resolved is by setting a limit to the number of hours that anyone can work. If parents spend less time at work, they will have the opportunity to closely foster their children and guide them away from any unlawful behaviour. In addition to this, websites that provide access to movies unsuitable for children should require their visitors to create accounts that confirm their age. This will ensure that children are not exposed to inappropriate content and will not be negatively affected.\n\nIn conclusion, more young people are breaking the law because their parents are too busy working, and violent content can readily be accessed on websites. To overcome this, governments should set a maximum number of working hours per person, and websites with violent movies must get visitors to register and confirm their age."},{"t":"h3","x":"Bir g'oya — uch joyda, uch xil parafraza"},{"t":"table","head":["Introduction","Body","Conclusion"],"rows":[["many parents are too busy","parents must work longer hours","parents are too busy working"],["children have easy access to violent movies","young people can easily access inappropriate films","violent content can readily be accessed on websites"],["governments should enforce a maximum number of hours that people can work","setting a limit to the number of hours that anyone can work","governments should set a maximum number of working hours per person"],["websites with mature content should require their visitors to register","websites … should require their visitors to create accounts that confirm their age","websites with violent movies must get visitors to register and confirm their age"]]},{"t":"h3","x":"Foydali so'zlar va iboralar"},{"t":"table","head":["Ma'no","So'zlar"],"rows":[["Muammo","problem, issue, concern"],["Sabab","reason, cause"],["Oqibat","effect, consequence, result, outcome"],["Yechim / hal qilish","deal with, solve, tackle, address, sort out, take measures, mitigate, remedy, alleviate, prevent, resolve"]]},{"t":"phr","title":"Sabab","items":["One of the main reasons for…","Another problem to consider is…","One main cause of…","A particular cause for concern is…"]},{"t":"phr","title":"Yechim","items":["To tackle this issue, …","One possible solution is…","The way forward could be to…","To solve this problem, …"]},{"t":"phr","title":"Oqibat","items":["Therefore, consumers would think twice about the food they consume.","As a result, this would have a positive effect on people's health.","Unless action is taken, the problem will get worse.","If the government takes steps to address the issue, the problem could be resolved.","This would result in a reduction in obesity."]},{"t":"ex","no":"22.1","q":"Har bir muammoli vaziyatga bitta sabab va bitta yechim yozing.","kind":"write","items":[{"q":"It's really dangerous to cycle in big cities.","sample":"Reason: there are too many cars, and bikes don't have a safe place. Solution: cities should build special cycle lanes and make sure everyone follows safety rules.","rows":3},{"q":"Sports centres are really expensive, so many people can't afford them.","sample":"Reason: running sports facilities is costly and not everyone has enough money. Solution: the government can make sport cheaper or offer low-cost sports programmes.","rows":3},{"q":"People eat too much junk food.","sample":"Reason: junk food is everywhere and it is cheap and convenient. Solution: educate everyone about healthy eating and why it is important.","rows":3},{"q":"People don't recycle newspapers, bottles and plastic enough.","sample":"Reason: recycling is inconvenient and people are not aware of its importance. Solution: make recycling easy, educate people and give rewards for recycling.","rows":3},{"q":"There are water shortages in some countries because people use too much water.","sample":"Reason: people waste water in everyday life. Solution: use water carefully, build better water systems and introduce rules on water use.","rows":3},{"q":"The country depends too much on fossil fuels (coal, oil, gas).","sample":"Reason: fossil fuels are the traditional, established source of energy. Solution: invest in clean energy such as solar and wind power.","rows":3},{"q":"People travel by plane too often, which causes air pollution.","sample":"Reason: flights are fast and increasingly cheap. Solution: promote other ways to travel, like high-speed trains, and make air travel greener.","rows":3},{"q":"Families don't eat together as much as they used to.","sample":"Reason: everyone is busy and uses their phones. Solution: explain why eating together matters and make time to share meals.","rows":3},{"q":"A lot of litter is dropped in the streets.","sample":"Reason: some people don't care and there are not enough bins. Solution: teach people not to litter, put more bins on the streets and fine litterers.","rows":3},{"q":"Many accidents are caused by people driving while using a mobile phone.","sample":"Reason: people don't pay attention when they use phones in the car. Solution: strict laws against phone use while driving, awareness campaigns and technology that blocks phones in moving cars.","rows":3}]},{"t":"ex","no":"22.2","q":"Reja tuzing va shu asosida introduction yozing.","kind":"write","items":[{"q":"People who live in large cities face a range of problems in their daily life. What are the main problems people in cities face? How can these problems be tackled?","rows":5,"sample":"Living in large cities can be challenging. Two prominent problems are overcrowding and traffic congestion. To tackle these issues, careful urban planning and sustainable transport systems play crucial roles."},{"q":"These days, in many countries, fewer and fewer people want to become teachers, particularly in secondary schools. What are the reasons for this? How could the problem be solved?","rows":5,"sample":"In many countries today, fewer people are interested in becoming teachers, especially in secondary schools. This is mainly because of low salaries and heavy workloads. To tackle this challenge, governments need to raise teachers' salaries and reduce their workloads."}]},{"t":"ex","no":"22.3","q":"O'zbekcha paragrafni ingliz tiliga o'giring.","intro":"**Topshiriq:** _Global warming is one of the biggest threats to our environment. What causes global warming? What solutions are there to this problem?_","kind":"write","items":[{"q":"Global isishning asosiy sabablaridan biri — havoni ifloslantiradigan yoqilg'idan ortiqcha foydalanish. Biz energiya ishlab chiqarish uchun neft, gaz va ko'mir kabi ko'plab narsalarni yoqamiz va bu jarayon havoni ifloslantiradi. Bundan tashqari, benzin yoki gazda yuradigan avtomobil va yuk mashinalaridan foydalansak, bu yanada ko'proq ifloslanishga sabab bo'ladi. Yana bir katta muammo — juda ko'p daraxtlarni kesish. Daraxtlar havoni tozalashga yordam beradi va ularni yo'q qilsak, bu sayyoramiz uchun yaxshi emas, chunki daraxtlar havodagi karbonat angidridni yutadi.","rows":7,"sample":"One major cause of global warming is the excessive use of fossil fuels that pollute the air. We burn a lot of things like oil, gas and coal to produce energy, and this sends lots of pollution into the air. When we use cars and trucks that run on petrol or gas, it causes even more pollution. Another big problem is cutting down too many trees. Trees help clean the air, and when we get rid of them, it is not good for the planet, because trees absorb carbon dioxide from the air."}]},{"t":"ex","no":"22.4","q":"Reja asosida sabablar paragrafini yozing.","intro":"**Topshiriq:** _Behaviour in schools is getting worse. Explain the causes and suggest some possible solutions._ **Reason 1:** lessons are not interesting → materials are dry and taught in an uninspiring way → pupils don't focus and behave badly. **Reason 2:** home environment → parents don't give discipline and guidance → pupils disrespect peers and teachers → misbehave.","kind":"write","items":[{"q":"Body paragraph — causes","rows":6,"sample":"One cause of poor student behaviour at school is that many lessons are not very interesting. In many cases, the subject materials are presented by teachers in a dry and uninspiring way. As a result, pupils do not concentrate on the lesson and, instead, behave badly in class. Another contributing factor is the home environment. Students who lack the necessary guidance and discipline from their parents tend to disrespect their peers and teachers by misbehaving."}]},{"t":"ex","no":"22.5","q":"Faqat yechimlar paragrafini yozing.","intro":"**Topshiriq:** _Childhood obesity is becoming a serious problem in many countries. Explain the main causes and suggest some possible solutions._","kind":"write","items":[{"q":"Body paragraph — solutions","rows":6,"sample":"However, several measures can be taken to mitigate this issue. Firstly, parents should give children healthy food and control what they eat in order to ensure that they have a healthy diet. For this, parents ought to give children home-cooked meals prepared with fresh vegetables and less fat, so that they avoid consuming junk food. The second solution is restricting the time children spend playing computer games and encouraging them to take regular exercise. This will help them avoid a sedentary lifestyle and stay active."}]},{"t":"p","x":"**22.6.** To'liq insholar (qo'shnilarni tanimaslik; ichimlik suvi tanqisligi) — **Yozish xonasi**da."}],"writes":15},{"task":2,"no":23,"title":"Two-part question essays","uz":"Ikki savolli insho","pages":"211–220","blocks":[{"t":"p","x":"**Two-part question** inshosida bitta vaziyat beriladi va unga **ikkita savol** qo'yiladi."},{"t":"task","label":"Misol","q":"Nowadays sending children to boarding schools is becoming increasingly popular.\nWhat are the reasons?\nDo you think it is a positive or negative development?"},{"t":"note","x":"Eng muhimi — **ikkala savolga ham** javob berish. Ko'p uchraydigan xato: faqat bitta savolga javob berish (masalan, faqat ijobiy/salbiy tomonlar yozilib, sabablar tushirib qoldiriladi) — natija past baho."},{"t":"task","label":"Namuna","q":"Nowadays the way many people interact with each other has changed because of technology.\nIn what ways has technology affected the types of relationships that people make?\nHas this been a positive or negative development?"},{"t":"h3","x":"Tuzilish"},{"t":"table","head":["Qism","Mazmun"],"rows":[["Introduction","1) mavzu parafrazasi; 2) 1-savolga qisqa javob; 3) 2-savolga qisqa javob"],["Body 1","1-savol: topic sentence + main idea 1, 2, 3 (har biri asoslangan)"],["Body 2","2-savol: On the one hand + ijobiy g'oya; On the other hand + salbiy g'oya"],["Conclusion","In conclusion + mavzu + 1-savol g'oyalari + 2-savol bo'yicha pozitsiya"]]},{"t":"p","x":"Har bir savolga 2 ta g'oya bilan ham javob berish mumkin; bu yerda 1-savolga 3 ta, 2-savolga 2 ta g'oya. 2-savolga \"faqat ijobiy\", \"faqat salbiy\" yoki \"ham ijobiy, ham salbiy\" deb javob berish mumkin."},{"t":"h3","x":"Reja"},{"t":"table","head":["Savol","G'oyalar"],"rows":[["1. In what ways?","Business: partners communicate without face-to-face meetings · Education: teachers and students exchange knowledge on Zoom and YouTube · Daily life: online friends on social networks"],["2. Positive or negative?","Positive: communication is easy, saving time and money · Negative: people are isolated, face-to-face communication discouraged; children make friends in the virtual world, not in the streets"]]},{"t":"h3","x":"Introduction"},{"t":"p","x":"Parafraza: _technology → new technologies; interact with → communication; changed → had an influence_."},{"t":"model","x":"It is true that new technologies have had an influence on communication between people. Technology has affected relationships in various ways, and in my opinion there are both positive and negative effects."},{"t":"h3","x":"Body 1 — Firstly / Secondly / Finally"},{"t":"h3","x":"Body 2 — On the one hand / On the other hand"},{"t":"h3","x":"Conclusion"},{"t":"model","x":"In conclusion, technology has certainly revolutionized communication between people in teaching, business cooperation and social life. But not all the results of this change have been positive, because it has made our communication easy, but real face-to-face interaction is being discouraged."},{"t":"model","title":"To'liq insho","x":"New technologies have indeed had an influence on communication between people. Technology has affected relationships in various ways, and in my opinion there are both positive and negative effects.\n\nTechnology has had an impact on relationships in business, education and social life. Firstly, telephones and the Internet allow business people in different countries to interact without ever meeting each other. Secondly, services like Zoom create new possibilities for relationships between students and teachers. For example, a student can now take video lessons with a teacher in a different city or country. Finally, many people use social networks, like Instagram, to make new friends and find people who share common interests, and they interact through their computers rather than face to face.\n\nOn the one hand, these developments can be extremely positive. Cooperation between people in different countries was much more difficult when communication was limited to written letters or telegrams. Nowadays, interactions by email, phone or video are almost as good as face-to-face meetings, and many of us benefit from these interactions, either in work or social contexts. On the other hand, the availability of new communication technologies can also have the result of isolating people and discouraging real interaction. For example, many young people choose to make friends online rather than mixing with their peers in the real world, and these 'virtual' relationships are a poor substitute for real friendships.\n\nIn conclusion, technology has certainly revolutionized communication between people in education, business and social life. But not all the results of this change have been positive, because it has made our communication easy, but real face-to-face interaction is being discouraged."},{"t":"ex","no":"23.1","q":"Boarding school mavzusiga reja tuzing (boarding school — maktab-internat, o'quvchilar maktabda yashab o'qiydi).","intro":"_Nowadays sending children to boarding schools is becoming increasingly popular. What are the reasons? Do you think it is a positive or negative development?_","kind":"write","items":[{"q":"Reasons (3 ta)","rows":4,"sample":"1. Parents are too busy and often travel abroad → children are in good hands. 2. For a better education → parents think the discipline is good there. 3. To learn about life and become independent → children don't rely on their parents."},{"q":"Positive development","rows":3,"sample":"Strict schedules for learning, exercise and a healthy diet → pupils become more knowledgeable and healthier than other pupils."},{"q":"Negative development","rows":3,"sample":"Far from parents → homesickness and not enough love from them → family ties weaken."}]},{"t":"ex","no":"23.2","q":"Rejangiz asosida boarding school inshosi uchun introduction va conclusion yozing.","kind":"write","items":[{"q":"Introduction","rows":4,"sample":"These days, many parents prefer their children to attend boarding school. They are choosing these schools for three main reasons, and in my opinion, there are both positive and negative effects of this development."},{"q":"Conclusion","rows":4,"sample":"In conclusion, more parents are choosing boarding schools because their children are in safe hands while they are away, can learn better and develop an independent character. However, these schools are not always a positive option, as they adversely affect family bonds despite offering better learning opportunities."}]},{"t":"ex","no":"23.3","q":"Introductionni o'qib, savollarga javob bering.","intro":"**Topshiriq:** _Marriages are bigger and more expensive nowadays than in the past. Why is this the case? Is it a positive or negative development?_ **Introduction:** _It is true that marriages have become more costly and extravagant in recent times. There are various reasons for it and in my opinion, it's both a positive and negative development._","kind":"fill","text":"1. \"bigger and more expensive\" qanday parafraza qilingan? → {1}\n2. \"than in the past\" qanday parafraza qilingan? → {2}\n3. Qaysi asosiy so'z o'zgarmadi? → {3}\n4. Topshiriqda Present Simple; introductionda qaysi zamon ishlatilgan? → {4}","a":["more costly and extravagant","in recent times","marriages/marriage","present perfect/the present perfect"]},{"t":"ex","no":"23.4","q":"1-savolga javob beruvchi paragrafni o'qing va topshiriqlarni bajaring.","intro":"_Marriages have become bigger and more expensive for various reasons. Firstly, people in developed countries are wealthier than their ancestors. They have enough money to spend on their weddings, which are considered one of life's important and unforgettable occasions. Secondly, in today's globalized world, people are inspired by celebrities' weddings and would like to copy them. For example, when Prince William got married, it was broadcast on television, and many people were so influenced by it that they wanted their weddings to be similar. Finally, the wedding industry has grown immensely and many companies want to sell their products using persuasive marketing. [Natijada, odamlar to'ylari uchun oldingiga qaraganda ko'proq xizmat va mahsulot sotib olmoqdalar.]_","kind":"write","items":[{"q":"Asosiy g'oyalarni har biri ko'pi bilan 4 so'z bilan yozing.","sample":"1) people wealthier than ancestors; 2) inspired by celebrities' weddings; 3) wedding industry has grown"},{"q":"Qavs ichidagi o'zbekcha gapni ingliz tiliga o'giring.","sample":"As a result, people are buying more services and goods for their weddings than in the past."}]},{"t":"ex","no":"23.5","q":"Marriage topshirig'ining ikkinchi savoliga (positive or negative development?) to'liq paragraf yozing.","kind":"write","items":[{"q":"Body paragraph 2","rows":7}]},{"t":"p","x":"**23.6.** To'liq insholar (uzoq ish soatlari; rivojlanayotgan davlatlarda turizm) — **Yozish xonasi**da."}],"writes":8}],"tasks":[{"id":"t1-req-club","unit":"w1.4","task":1,"kind":"request","style":"formal","title":"Private sports club — college student","situation":"You have just started a course in a college which has no sports facilities of its own.","to":"Write a letter to the manager of the nearest private sports club. In your letter","bullets":["introduce yourself","say why you are interested in this sports club","ask some questions about the club e.g., facilities, members, costs"],"src":"Unit 4"},{"id":"t1-req-town","unit":"w1.4","task":1,"kind":"request","style":"informal","title":"Visiting your friend's university town","situation":"You are going to visit the town where your friend went to university.","to":"Write a letter to your friend. In your letter:","bullets":["explain why you will be visiting the town","give details of where you will be staying","ask your friend to recommend some evening entertainment"],"src":"Unit 4"},{"id":"t1-req-teacher","unit":"w1.4","task":1,"kind":"request","style":"formal","title":"Learning a language with a local teacher","situation":"You want to learn a language. There is a teacher near to where you live.","to":"Write a letter to the teacher. In the letter:","bullets":["say how you came to know about him/her","explain why you want to learn","ask what help they can offer."],"src":"Unit 4","sample":"Dear Prof. Yuldashev,\n\nI am writing to inquire about taking Chinese lessons with you, and I am delighted to have found out about your language teaching services through a local advertisement.\n\nThe reason I am keen on learning Chinese is my desire to expand my horizons and explore diverse cultures. I believe that language is a gateway to understanding and appreciating different customs and traditions. Learning Chinese will not only enhance my personal growth but also open up new opportunities for professional development and interaction with a wider community.\n\nI am reaching out to request information about the language learning opportunities you offer. I am particularly interested in understanding the structure of your lessons, the duration of the course, and the frequency of classes. Additionally, I would like to know if you provide individual or group sessions and if there are any specific materials or resources required for the course.\n\nIf you can spare a moment to discuss the details and availability, I would greatly appreciate it. I am enthusiastic about commencing this learning journey with your guidance.\n\nThank you for considering my request. I look forward to your response.\n\nSincerely,\nBarno Sabirova"},{"id":"t1-req-flat","unit":"w1.4","task":1,"kind":"request","style":"informal","title":"Moving to a city where an old friend lives","situation":"You are moving to a new city for work and have just realized that an old friend lives in the city.","to":"Write a letter to your friend. In your letter:","bullets":["ask them for advice in finding accommodation","tell them where you would like to live","tell them the type of place you are looking for"],"src":"Unit 4","sample":"Dear Jakhongir,\n\nI hope this letter finds you in great spirits. As you might have heard, I am relocating to Samarkand for a new job opportunity, and I just discovered that you are living there as well. I would be grateful if you could help me to find suitable accommodation.\n\nSince you are already familiar with the area, I was hoping to seek your valuable advice on finding suitable accommodation. Ideally, I would prefer to live in a neighbourhood that is safe, well-connected to public transportation, and offers a vibrant community vibe.\n\nAs I'm still in the early stages of my housing search, I would appreciate any insights you might have regarding the best areas to consider. I am looking for a cozy one-bedroom apartment or a small house with some greenery nearby, as I enjoy spending time outdoors.\n\nI genuinely value your guidance and any tips you can provide to ease my transition to the new city. I look forward to catching up soon and creating more memories together.\n\nThank you for your support, and let's plan a meet-up once I'm settled in.\n\nWarm regards,\nKamol"},{"id":"t1-req-tourist","unit":"w1.4","task":1,"kind":"request","style":"formal","title":"Short break — tourist information centre","situation":"You are visiting another town next month for a short break.","to":"Write a letter to the tourist information centre. In your letter:","bullets":["tell them how long you are staying","ask for some suggestions for what to do","find out if there are any local events happening at the time"],"src":"Unit 4 · 4.5"},{"id":"t1-req-hotel","unit":"w1.4","task":1,"kind":"request","style":"formal","title":"Family weekend at a seaside hotel","situation":"You and your family are planning to spend a weekend at a seaside hotel.","to":"Write a letter to the hotel for making the arrangement. In your letter:","bullets":["tell them when you will be arriving and leaving","tell what type of rooms you would like and ask how much the weekend will cost","inquire about activities and places of interest near the hotel"],"src":"Unit 4 · 4.5"},{"id":"t1-cmp-tv","unit":"w1.5","task":1,"kind":"complaint","style":"formal","title":"A new TV that doesn't work as expected","situation":"You bought a TV a week ago but when you got home you discovered it did not work as you expected.","to":"Write a letter to the company and in your letter:","bullets":["introduce yourself","explain the problem","and state what action you would like from the company."],"src":"Unit 5"},{"id":"t1-cmp-gym","unit":"w1.5","task":1,"kind":"complaint","style":"formal","title":"Changing rooms at the sports centre","situation":"You visit a sports centre regularly, and there is a problem with the changing rooms in it. You have complained about it several times but with no success.","to":"Write a letter to the manager of the sports centre. In your letter:","bullets":["describe what the problem with the changing rooms is","say what happened the last time you complained","explain what you want the manager to do"],"src":"Unit 5","sample":"Dear Sir or Madam,\n\nI am writing to express my dissatisfaction with the persistent issue with the changing rooms at your sports centre.\n\nI regret to inform you that there is an issue with the changing rooms due to their insufficient cleanliness and lack of proper maintenance. The floors are often wet and the locker doors are frequently malfunctioning. This has created an uncomfortable and unhygienic environment for members like myself who visit the sports centre regularly.\n\nDespite my previous complaints, there was not any visible improvement. This lack of response was disheartening, as it indicates a disregard for the well-being and satisfaction of your customers.\n\nIt would be greatly appreciated if you could take immediate action to address these concerns. It is essential that the changing rooms are cleaned thoroughly, locker facilities are repaired, and proper maintenance protocols are put in place to ensure a pleasant experience for all visitors.\n\nI hope you can address this matter promptly and provide a suitable solution.\n\nYours faithfully,\nBahodir Hamroyev"},{"id":"t1-cmp-music","unit":"w1.5","task":1,"kind":"complaint","style":"formal","title":"Neighbour's loud music at night","situation":"Your next-door neighbour often listens to loud music at night. Due to the loud music, you often struggle to sleep and experience frequent headaches.","to":"Write a letter to your building manager. In your letter:","bullets":["describe the situation","explain the problems it is causing you","offer at least one solution"],"src":"Unit 5 · 5.5","sample":"Dear Sir or Madam,\n\nI am writing to express my strong dissatisfaction with the behaviour of my neighbour, which is constantly disturbing the overall quality of my life.\n\nI am a resident of Apartment 15, and I have been facing consistent disturbance due to loud music played by my next-door neighbour during late hours.\n\nRegrettably, I must inform you that the constant noise, especially at night, is causing significant problems for me. Precisely, I am finding it increasingly difficult to fall asleep and stay asleep due to the loud music. Consequently, this lack of rest is leading to frequent headaches, impacting my overall well-being and daily activities.\n\nTo address this situation, I kindly request your intervention in communicating with my neighbour about the noise disturbance. It may be beneficial to remind residents of the building's quiet hours policy and the importance of being considerate of their neighbours, especially during night-time hours.\n\nI trust that you will take the necessary steps to rectify this situation.\n\nYours faithfully,\nDavron Abdullaev"},{"id":"t1-cmp-micro","unit":"w1.5","task":1,"kind":"complaint","style":"formal","title":"A microwave that doesn't work","situation":"You bought a microwave but when you got home, you discovered it didn't work. You have called customer service but the matter has not been dealt with yet.","to":"Write a letter to the company and in your letter:","bullets":["introduce yourself","explain the problem","state what action you would like from the company"],"src":"Unit 5 · 5.5","sample":"Dear Sir or Madam,\n\nI am writing to express my dissatisfaction with a recent purchase I made from your company. On 16th June, I purchased a microwave, the model called \"Family\", from your store.\n\nTo my disappointment, after unpacking the microwave, I realized that it is faulty and does not function as intended. Precisely, although the microwave appeared to be working properly, it actually did not heat the meal I put in it. As a result, I immediately contacted your customer service department on 17th June to report the issue and seek a resolution. Regrettably, despite my initial communication, the matter has not been addressed or resolved to date.\n\nI kindly request prompt attention to this matter. I expect either a replacement for the defective microwave or a full refund of the purchase price. I believe it is reasonable to expect a functional product when making a purchase, and I hope the company can uphold its commitment to customer satisfaction.\n\nI appreciate your understanding and cooperation in resolving this matter promptly.\n\nYours faithfully,\nBahodir Nodirov"},{"id":"t1-inf-centre","unit":"w1.6","task":1,"kind":"info","style":"formal","title":"Council plans to close the leisure centre","situation":"Your local council is considering closing a sports and leisure centre that it runs, in order to save money.","to":"Write a letter to the local council. In your letter:","bullets":["explain why the centre is important for the local community","give details of how you and your friends or family use the centre","describe the possible effects on local people if the centre closes"],"src":"Unit 6","sample":"Dear Sir or Madam,\n\nI am writing with regard to the proposed closure of the town's sports and leisure centre.\n\nFirst, I would like to stress how important the centre is for my own family. My wife and I both use the gym on a daily basis, and our two children attend weekly gymnastics and football clubs, which they enjoy immensely.\n\nI also believe that the leisure centre is an integral part of the local community. It is where people go to do exercise, play sports, take part in group activities, and to socialize and make friends. It really is a social hub in the town.\n\nIf you do close the sports and leisure centre, the local residents will lose a treasured facility. As there are no other sports centres within a reasonable distance, the closure would have a detrimental effect on health and quality of life in the area.\n\nI hope that you will take these concerns into consideration before making a decision.\n\nYours faithfully,\nPaul Jones"},{"id":"t1-inf-police","unit":"w1.6","task":1,"kind":"info","style":"formal","title":"More police in your neighbourhood","situation":"Your neighbourhood is experiencing a surge in crime, and you believe that increased police presence is necessary.","to":"Write a letter to your local police department. In your letter:","bullets":["describe recent incidents or concerns about safety in your neighbourhood","explain why having more police presence is essential for community security","request specific actions or strategies to address the crime issue"],"src":"Unit 6","sample":"Dear Sir or Madam,\n\nI am writing to bring to your attention the recent rise in crime within our neighbourhood, which has left many residents deeply concerned about our safety.\n\nFirst and foremost, our community relies heavily on the local police department to maintain law and order. However, recent incidents, including break-ins and vandalism, have shaken our sense of security. Consequently, residents are forced to install cameras in their homes and prevent their children from playing outdoors.\n\nIt is crucial to emphasize that increasing police presence is vital for deterring criminal activity and ensuring the safety of our residents. A visible police presence not only prevents crimes but also fosters a sense of security among our community members, encouraging them to report suspicious activities promptly.\n\nI respectfully urge the local police department to consider allocating additional resources and officers to our neighbourhood to address these concerns effectively and restore our community's sense of security.\n\nThank you for your attention to this matter.\n\nSincerely,\nSanjar Ahmedov"},{"id":"t1-inf-party","unit":"w1.6","task":1,"kind":"info","style":"semi","title":"Chris's surprise birthday party","situation":"The parents of your Australian friend Chris have invited you to a surprise birthday party for him.","to":"Write a letter to Chris's parents. In your letter:","bullets":["say why you think Chris will enjoy the surprise party","explain why you won't be able to attend the party","give details of a plan to see Chris at a different time"],"src":"Unit 6 · 6.3","sample":"Dear Mr and Mrs Jones,\n\nI am excited to hear that you will be arranging a surprise birthday party for Chris next month. I am honoured to be invited to this party. However, I will be visiting my hometown at that time and cannot make it.\n\nChris will love this party, especially since his close university friends will be there to cheer him up. It will also be a fabulous occasion for him, as he is a bit stressed out from a few deadlines in his new office. I am sure you will have many memorable moments at his birthday party.\n\nAs much as I would like to be present at the party, I just cannot miss an appointment to take my father to the doctor on the same day. The specialist doctor comes from a different state and is available only for three days. That is why I will travel to my hometown two days before Chris's birthday and return a day after his party.\n\nI would, however, like to meet him a week after his birthday and present him with a gift from my side. On that occasion, I hope to spend some time outdoors with him or even arrange a dinner party at my home.\n\nThank you once again for inviting me.\n\nYours sincerely,\nAlfred Kinsey"},{"id":"t1-inf-agent","unit":"w1.6","task":1,"kind":"info","style":"formal","title":"Moving abroad — property agent","situation":"You and your family are moving to another country, and you are looking for rented accommodation there.","to":"Write a letter to a property agent. In your letter:","bullets":["introduce yourself and your family","describe the type of accommodation that you hope to find","give your preference for the location of the accommodation"],"src":"Unit 6 · 6.3","sample":"Dear Sir or Madam,\n\nI am writing to ask for your help in finding accommodation in Australia.\n\nMy name is Mark Smith, and I am married with two young children. A recent promotion at work has meant that I will soon be based in Sydney instead of London, and so we are hoping to emigrate as soon as possible.\n\nOur plan is to find rented accommodation for at least the first year of our stay in Australia. Ideally, we would like a detached house with three or four bedrooms and a good-sized garden so that the children have somewhere to run around.\n\nWe would prefer a quiet, suburban location within easy commuting distance of the city centre. The local schools are an important consideration, and we would like to be close to shops and other amenities.\n\nI hope you can help us with our house search, and I look forward to hearing from you.\n\nYours faithfully,\nMark Smith"},{"id":"t1-apo-dinner","unit":"w1.7","task":1,"kind":"apology","style":"informal","title":"Missed a friend's dinner party","situation":"You said you would attend a friend's dinner party but you did not go.","to":"Write a letter to your friend. In the letter:","bullets":["apologize for not attending","explain why you did not attend","say what you will do to make up for it"],"src":"Unit 7"},{"id":"t1-apo-meeting","unit":"w1.7","task":1,"kind":"apology","style":"formal","title":"Missed an important meeting at work","situation":"You missed an important meeting at work.","to":"Write a letter to your manager. In the letter:","bullets":["apologize for not attending","explain why you did not attend","say what you will do to make up for it"],"src":"Unit 7"},{"id":"t1-apo-noise","unit":"w1.7","task":1,"kind":"apology","style":"semi","title":"Neighbours complain about noise from your house","situation":"Your neighbours have recently written to you to complain about the noise from your house.","to":"Write a letter to your neighbours. In your letter:","bullets":["explain the reasons for the noise","give an apology","describe what action you will take"],"src":"Unit 7 · 7.5","sample":"Dear Mr Robertson,\n\nI am writing to apologise for the recent noise coming from my flat. I received your letter and was very embarrassed, as I had not realized it would bother you so much.\n\nLet me explain a little. Two weeks ago, my son got a new puppy and he has been doing his best to look after her. Unfortunately, when I am at work and my son is at school, the puppy is home alone. We thought that she was doing fine by herself but, according to your letter, she is making a lot of noise when we are out of the house.\n\nWe will immediately begin training the dog to make less noise and will also install some soundproofing in the flat so that any noise she does make does not bother you so much. Hopefully, within a few days, you won't hear anything at all through the walls.\n\nOnce again, I apologise for this whole affair and will make sure it does not happen again.\n\nSincerely,\nDavid Wills"},{"id":"t1-apo-start","unit":"w1.7","task":1,"kind":"apology","style":"formal","title":"Can't start the new job on the agreed date","situation":"You successfully passed a job interview. You are expected to start on November 15, but you will not be available on that date.","to":"Write a letter to your boss. In your letter:","bullets":["explain your situation","express your concern","suggest a solution"],"src":"Unit 7 · 7.5","sample":"Dear Sir or Madam,\n\nI am writing to inform you that I will not be able to start work on November 15, as agreed during my recent interview with you.\n\nThe reason I cannot start work on that date is that my mother fell down the stairs yesterday. As I am the only daughter and there are no other relatives who are able to look after her, I have no choice but to go back and care for her. According to the doctors, it will take about two weeks for her to be able to walk and take care of herself again.\n\nI apologize for any inconvenience, and I understand that you need me at work on that day for the project that is scheduled to be completed three weeks later. I am able to work from home and complete the project as planned. I will also report to you by e-mail, and if there is a problem, I will call and inform you along the way.\n\nOnce again, I am very sorry for the inconvenience and thank you for your understanding.\n\nYours faithfully,\nS. Chua"},{"id":"t1-thx-rest","unit":"w1.8","task":1,"kind":"thanks","style":"formal","title":"A celebration meal at a restaurant","situation":"You and some friends ate a meal at a restaurant to celebrate a special occasion, and you were very pleased with the food and service.","to":"Write a letter to the restaurant manager. In your letter","bullets":["give details of your visit to the restaurant","explain the reason for the celebration","say what was good about the food and the service"],"src":"Unit 8","sample":"Dear Sir,\n\nI am writing to thank you and your staff for making our celebration meal so special last Friday evening.\n\nI made a booking for ten people at very short notice on Friday, and you managed to find us a table. When we made the spontaneous decision to eat out that evening, we were amazed to find a table for such a large group, and we could not have chosen a better restaurant.\n\nThe ten of us were celebrating our university graduation. The ceremony had taken place, and my friends and I were all so relieved to have finally received our degree certificates. Nobody wanted to go home, so I suggested that we find somewhere to have dinner together.\n\nAs soon as we walked into the restaurant, we knew that we were in good hands. Your waiters were extremely friendly and obliging, and the food was delicious. We were also impressed that both you and the head chef came to check that everyone was happy with their food.\n\nAll ten of us would like to thank you for giving us such a memorable evening.\n\nYours faithfully,\nPaul Jones"},{"id":"t1-thx-pet","unit":"w1.8","task":1,"kind":"thanks","style":"informal","title":"A friend will look after your house and pet","situation":"A friend has agreed to look after your house and pet while you are on holiday.","to":"Write a letter to your friend. In your letter","bullets":["give contact details for when you are away","give instructions about how to care for your pet","describe other household duties"],"src":"Unit 8","sample":"Hello Jean,\n\nThanks again for agreeing to look in on Barry while I'm in Thailand for the week. I really appreciate it.\n\nI'd just like to give you a little extra info that I'd forgotten to mention when we spoke last time. Barry's pretty easy to look after. He gets fed twice a day from the bag of kibble under the sink. If he whines, don't bother giving him any more, as he's just trying to manipulate you. Like most cats, he can look after himself, but he gets a bit lonely, so it'll be good to have you there for him every now and then.\n\nAs for the house, you can water my plants whenever you think they look a bit dry, and please remember to bring in the delivery packages before noon, or else the local kids might steal them.\n\nIf there's any problem or if you have any questions, you can send me a message on WhatsApp or Messenger. I know you already have both of those.\n\nThanks again,\nDavid"},{"id":"t1-thx-photos","unit":"w1.8","task":1,"kind":"thanks","style":"informal","title":"Holiday photos from your friends","situation":"Last month you had a holiday overseas where you stayed with some friends. They have just sent you some photos of your holiday.","to":"Write a letter to your friends. In your letter:","bullets":["thank them for the photos and for the holiday","explain why you didn't write earlier","invite them to come and stay with you"],"src":"Unit 8 · 8.3","sample":"Dear Mark and Lucy,\n\nHope you're doing great. I had a great time with you guys. Thank you so much both for the remarkable holiday in your city and for the lovely photos that you sent me yesterday.\n\nSorry it has taken me so long to write back and thank you. Almost as soon as I landed back in Italy, I got extremely busy with my office work. Besides, a severe cold forced me to take a few days off, and I struggled to regain momentum at work and at home.\n\nI would like to invite both of you to visit Italy. We'll be celebrating our parents' 40th wedding anniversary next month, and I expect you on this special occasion. I'll take you to some of the famous places in Italy, including Rome. Best known for its ancient Roman structures and the Vatican City, Rome has stunning cathedrals and Renaissance architecture. I am sure you'll enjoy your time here.\n\nI would love to see you both soon. Take care and write back.\n\nWarm wishes,\nEmily"},{"id":"t1-thx-stranger","unit":"w1.8","task":1,"kind":"thanks","style":"formal","title":"A stranger who helped you after an accident","situation":"After being involved in an accident, you were looked after by a person you did not know before.","to":"Write a special thank you letter. In your letter:","bullets":["introduce yourself and let him / her know why you are writing to him / her","express your gratitude","offer him / her to visit your home with his / her family"],"src":"Unit 8 · 8.3","sample":"Dear Mr Jony,\n\nI hope this letter finds you in good health. My name is Mary, and I wanted to take a moment to express my heartfelt gratitude to you. I am writing to you because of a recent incident in which you played an important role.\n\nA few days ago, I was involved in an accident, and you came to my aid, even though we had never met before. Your kindness and assistance during that time meant a lot to me. Your reassuring words and quick actions helped me stay calm amidst the chaos.\n\nI want to extend my sincerest thanks for your selflessness and compassion. It's not every day that we encounter someone so willing to help a stranger, and I am truly grateful for your presence when I needed it most.\n\nAs a token of my appreciation, I would like to invite you and your family to visit my home. I believe that good deeds should be acknowledged, and I would be honoured to host you as my guests. It would be a wonderful opportunity for us to get to know each other better.\n\nOnce again, thank you for your kindness. I look forward to the possibility of welcoming you into my home.\n\nYours faithfully,\nMary Tomkins"},{"id":"t1-job-catering","unit":"w1.9","task":1,"kind":"job","style":"formal","title":"Summer job at a catering company","situation":"You have seen an advert in a local magazine for a job working at a catering company during the summer season. You decide to apply for the job.","to":"Write a letter to the director of the company. In your letter:","bullets":["introduce yourself","explain what experience and special skills you have","explain why you are interested in the job"],"src":"Unit 9"},{"id":"t1-job-train","unit":"w1.9","task":1,"kind":"job","style":"semi","title":"A businesswoman you met on a train","situation":"During a recent train journey, you sat next to a businesswoman who owns a chain of hotels. You talked to her and she suggested that you should contact her about a possible job opening in one of her hotels.","to":"Write a letter to this businesswoman. In your letter:","bullets":["remind her when and where you met","tell her what kind of job you are interested in","say why you think you would be suitable for the job"],"src":"Unit 9","sample":"Dear Ms Bakhromova,\n\nI am writing to express my interest in the position of sales manager at one of the \"Belek\" hotels owned by your organization.\n\nMy name is Alisher and we met last week on the train from Tashkent to Samarkand, on a late Sunday afternoon. We sat next to each other and you told me in detail about your hotels. Then, we exchanged business cards and you told me about a job vacancy in a new boutique hotel.\n\nAs I told you during our journey, I hold a degree from Singapore Management University with a significant background in Tourism and Hospitality. Currently, I am employed as an Assistant Manager at \"Nur\" hotel and I have been working in the tourism industry for more than 5 years. My responsibilities encompass managing hotel staff, addressing client concerns, and making plans for future development. Therefore, I am eager to contribute to the future growth of your new hotel as a sales manager.\n\nI consider myself to be a punctual, hard-working, and outgoing person. Experience from my previous roles has helped me develop my problem-solving and communication skills.\n\nI would be pleased to supply you with any further information during the interview.\n\nYours sincerely,\nAlisher Juraev"},{"id":"t1-job-resign","unit":"w1.9","task":1,"kind":"job","style":"formal","title":"Resigning to try a new field","situation":"You have decided to resign from your work in order to try a new field.","to":"Write a letter of resignation to your boss. In your letter:","bullets":["tell your boss of your decision and explain why you are leaving","explain what you have learnt from your current job and how you feel about leaving","ask for a letter of reference"],"src":"Unit 9","sample":"Dear Mr John,\n\nI am writing to formally announce my resignation from my position as a sales manager at Nestle company.\n\nI am truly grateful for the invaluable experiences and opportunities I have had at Nestle. Precisely, while working at your company, I have gained valuable experience in leadership through the sales manager position that I have held for several years. I was also able to enhance my communication skills by interacting with others in the organization. Additionally, working with international companies helped to broaden my horizons in terms of cultural differences between nations.\n\nI would really appreciate it if you could provide me with a letter of reference for my new employer. Specifically, it should include my relevant experience and roles throughout this period, as well as my key skills.\n\nI sincerely wish Nestle company ongoing success and growth in the years to come.\n\nYours faithfully,\nMalak"},{"id":"t1-job-parttime","unit":"w1.9","task":1,"kind":"job","style":"formal","title":"Part-time job at a local restaurant","situation":"You recently noticed a local restaurant that was offering a part-time job.","to":"Write a letter to the restaurant's manager. In your letter","bullets":["explain that you would like to apply for the job","give some details of any relevant experience that you have","specify the days and times that would suit you"],"src":"Unit 9 · 9.3","sample":"Dear Sir or Madam,\n\nI am writing to express my interest in the position of a chef advertised on the local village board.\n\nI noticed from the job description that you require someone who can both cook in a creative and healthy way, and who can communicate with and manage staff in an effective manner. As you can see from my CV, I have been working as an assistant chef for the past 2 years at Brew's restaurant in London. My responsibilities encompass preparing all the dishes on the restaurant's menu and coming up with inventive recipes to present to the head chef. Additionally, I am also personally very interested in healthy living and this is always reflected in how I cook. I was responsible at Brew's for managing the cleaning and serving staff, in which capacity I was able to build good working relationships with all the staff in my responsibility. My time at Brew's cultivated my communication and organization skills.\n\nI am eager to contribute to the growth and success of your restaurant. My preferred days for working would be Monday, Wednesday and Friday afternoons and evenings.\n\nShould you have any questions, feel free to contact me at any time.\n\nYours faithfully,\nMarjona"},{"id":"t1-job-fulltime","unit":"w1.9","task":1,"kind":"job","style":"formal","title":"A full-time job from an advertisement","situation":"You are looking for a full-time job, and recently you saw a job opening in an advertisement.","to":"Write a letter to the company. In your letter:","bullets":["introduce yourself","explain what sort of job you would like to do","and say what experience and skills you have"],"src":"Unit 9 · 9.4","sample":"Dear Sir or Madam,\n\nI am excited to apply for the position of assistant manager at Adventure Hotel, which I learned about through the local newspaper recently.\n\nI would like to work as an assistant manager, which would enable me to work closely with the hotel staff and with the management. This way, I would be able to serve the hotel well on the one hand and gain valuable experience on the other.\n\nI graduated from City University in 2019 and I have a significant background in Tourism and Hospitality. Afterwards, I worked for two four-star hotels, and my current job as an assistant manager at the Gilbert hotel makes me a suitable candidate for the post. I do not see enough opportunity for career growth with my current employer, and that is why I would like to change my job.\n\nShould you need any further details, please do not hesitate to call me.\n\nYours faithfully,\nPaul Jenkins"},{"id":"t1-job-leave","unit":"w1.9","task":1,"kind":"job","style":"formal","title":"Leaving a company after several years","situation":"You have been working for a company for more than a few years, and now have decided to leave the company.","to":"Write a letter to your company manager saying that you want to leave the company. In your letter:","bullets":["say what you have learned while working for the company","say whether you enjoyed working there","say what your reasons are for leaving"],"src":"Unit 9 · 9.4","sample":"Dear Sir or Madam,\n\nI am writing to formally announce my resignation from my position as a sales supervisor, effective from the 1st of March.\n\nWorking as a sales supervisor for almost half a decade in your esteemed organization was one of the best opportunities in my life. I have gained valuable experience in dealing with customers and promoting products, which I believe will help me further advance my career. Moreover, my co-workers, seniors and the management have been like a family to me. I enjoyed working for this company to a great extent.\n\nThe reason for my leaving is that I have recently accepted an offer of a managerial position at Dunken's Brothers Company. I am expected to join them at the beginning of March. Hence, I would like you to release me from my responsibilities before that date.\n\nI will always remember the excellent time that I have spent working for you. I wish the company and the team every progress and success.\n\nYours faithfully,\nRien Taylor"},{"id":"t1-con-dog","unit":"w1.10","task":1,"kind":"condolence","style":"informal","title":"Your friend's dog has passed away","situation":"Your friend's dog has recently passed away.","to":"Write a letter to console your friend. In your letter:","bullets":["express your sympathy","include memories you have about the dog","invite your friend to do something with you."],"src":"Unit 10"},{"id":"t1-con-father","unit":"w1.10","task":1,"kind":"condolence","style":"semi","title":"Your colleague's father has passed away","situation":"You recently heard about the passing of your colleague's father.","to":"Write to your colleague. In your letter:","bullets":["offer your condolences","include memories you have about his/her father","invite your colleague to do something with you."],"src":"Unit 10 · 10.4"},{"id":"t1-con-fire","unit":"w1.10","task":1,"kind":"condolence","style":"semi","title":"Your neighbour's house was destroyed in a fire","situation":"Your neighbour's house was recently destroyed in a fire.","to":"Write a letter to your neighbour. In your letter:","bullets":["express your condolences for their loss","offer your support during this challenging time","suggest ways in which the community can come together to help them recover from the incident"],"src":"Unit 10 · 10.4"},{"id":"t1-cmp-rude","unit":"w1.11","task":1,"kind":"complaint","style":"formal","title":"A rude supermarket employee","situation":"You were recently disrespected by one of the employees at your local supermarket.","to":"Write a letter to the supermarket manager. In your letter:","bullets":["tell him/her why you were speaking with the employee","describe the employee's rude behaviour","explain what you'd like the manager to do"],"src":"Unit 11","sample":"Dear Sir or Madam,\n\nI am writing to complain about the way I was treated by a member of your staff last Tuesday.\n\nWhile at your supermarket last Tuesday, I was unable to reach a box of cereal from the top shelf, and there weren't any staff members or other customers in the aisle who I could ask for help. For this reason, I asked for assistance from a female employee in the nearby bakery section of your supermarket.\n\nThis person's response was incredibly inappropriate and is the reason I am writing this letter. At first, she stared into my eyes without saying anything, after which she laughed under her breath and walked away. At this point, she began pointing in my direction while whispering to another member of staff in the bakery.\n\nI'm highly insulted by this conduct for obvious reasons, and I wish to be sent a letter of apology directly from that staff member. On that day, it seemed as though this was the only female employee in the bakery, which is why I'm confident that you will easily identify the person in question, and furthermore, I expect to hear from her within the next week.\n\nI look forward to your prompt response.\n\nYours faithfully,\nA. Karimov"},{"id":"t1-req-resort","unit":"w1.11","task":1,"kind":"request","style":"formal","title":"Special offer at a tourist resort","situation":"You have seen an advertisement for a special offer at a beautiful tourist resort. You would like to book a holiday.","to":"Write a letter to the travel company. In your letter","bullets":["say when you would like to arrive and leave","describe the type of accommodation you require","ask for some more information about some activities you are interested in"],"src":"Unit 3 / 11","sample":"Dear Sir or Madam,\n\nI saw your advertisement for a two-week holiday in Tasmania in Cheap and Cheerful Holiday Magazine and I would like to have information on the issues below.\n\nFirst, I would like to know if the special offer is still available during the school holidays from 8 to 21 July, as this is the only time that it is possible for us to get away.\n\nSecondly, could you send me details of the type of accommodation you offer? I would like to know if you have anything suitable for a party of ten people. Furthermore, would it be possible for you to inform me whether any of the cabins have wheelchair access?\n\nFinally, we would like to go sailing and wonder if it is possible to book a boat from the resort.\n\nI look forward to your response and hope to see you in the near future.\n\nYours faithfully,\nDoniyor"},{"id":"t1-cmp-clothes","unit":"w1.11","task":1,"kind":"complaint","style":"formal","title":"Clothes bought online — wrong colour and size","situation":"You have bought some clothing online and are not satisfied with your purchase.","to":"Write a letter to the company that you bought clothing from. In your letter:","bullets":["give details of the purchase","describe the problem","explain why you need a replacement urgently"],"src":"Unit 11","sample":"Dear Sir or Madam,\n\nI am writing to express my dissatisfaction with the suit that I purchased from your online store and to request a prompt replacement.\n\nOn 25th of January, I ordered a black suit size 58 and a white shirt size XXL from your online store. The total price of the suit and white shirt was $165 and the order was supposed to be delivered directly to my house within 3 days.\n\nHowever, upon receiving the order and opening it, I immediately noticed a problem with the colour and size of the suit. After taking the items out of the box, I realized that there was a brown suit instead of a black one, and the size was also much smaller than expected. Furthermore, I felt greatly frustrated to find a big stain on the front of the white shirt.\n\nI kindly request you to make an urgent replacement because I was expecting to wear these clothes for my brother's wedding. Moreover, it would be greatly appreciated if you inspected the details of the replacement personally so that the mistake would not be repeated.\n\nI look forward to your swift resolution, and I trust that you will continue to provide excellent customer service.\n\nYours faithfully,\nNodirbek"},{"id":"t1-inf-party2","unit":"w1.11","task":1,"kind":"info","style":"informal","title":"Invite a foreign friend to your party","situation":"Write a letter to your friend from a different country. Invite him/her to a party at your home.","to":"Include the following:","bullets":["what the party is about","give directions on how to get to your place","suggest how to accommodate him/her"],"src":"Unit 11","sample":"Dear Dilshod,\n\nI am writing to invite you to a party I'm going to have at my home on March 12.\n\nI'm planning to celebrate my championship in the Asian boxing tournament with my close friends like you. The party is planned to start with a chess tournament at 3 o'clock and this should take a maximum of three hours. After that I've got some mates coming over who will play some good music and so on.\n\nAs you have visited my home before, I assume you remember how to find it. However, in case you don't, I'll give you some directions. Just after you've passed the Railway station, there is a bus stop before the junction on the right. Then go along the same street for about 100 metres and you should see my house at 67 Mitchell Street.\n\nAs I've got plenty of free space in my house, you don't need to worry about accommodation. I can keep a room for you. By the way, if you prefer to stay in a hotel, don't book one in advance without telling me, since my uncle has recently opened one in our local area, and I will accommodate you there.\n\nI look forward to your reply!\n\nBest wishes,\nFeruzbek"},{"id":"t1-req-house","unit":"w1.12","task":1,"kind":"request","style":"informal","title":"Ask a friend to look after your house","situation":"You are going on holiday.","to":"Write a letter to a friend asking him or her to look after your house. In the letter","bullets":["explain the situation","tell your friend what needs to be done while you are away","arrange to meet your friend before you go"],"src":"Unit 12","sample":"Dear Mike,\n\nAs you know, I am going to England on holiday from next Monday until the 15th of July. I wonder if you could do me a favour while I am away.\n\nI would really appreciate it if you could look after the house. In particular, I would like you to feed the cat. He can get in and out of the house on his own, so all you need to do is leave some food in his bowl. While you are at the house, it would be good if you could water the garden and take any post out of the mailbox and place it inside.\n\nWould it be possible for us to meet on Wednesday so I can give you the keys? If Wednesday is OK, please telephone me as soon as possible.\n\nI look forward to seeing you in the next few days.\n\nRegards,\nJohn"},{"id":"t1-inf-guidebook","unit":"w1.12","task":1,"kind":"info","style":"informal","title":"Returning a borrowed guidebook","situation":"You recently went on a foreign holiday and borrowed a guidebook about your destination from your friend.","to":"Write a letter to your friend. In your letter","bullets":["describe your holiday to him/her","tell him/her why the guidebook was useful","make arrangements to return the book"],"src":"Unit 12"},{"id":"t1-inf-accident","unit":"w1.12","task":1,"kind":"info","style":"formal","title":"A minor accident at work","situation":"You had a minor accident at work.","to":"Write a letter to your employers. In the letter","bullets":["describe what happened","explain the cause of the accident","state what you think should be done about the situation"],"src":"Unit 12","sample":"Dear Mr Williams,\n\nI would like to report an accident that I had leaving work on Friday 21 October. As I was leaving the office, I tripped over a raised paving stone just outside the front entrance. I fell over and tore my trousers and cut my knee. Although my injury was not serious, it was painful and my trousers were damaged beyond repair.\n\nI believe that this accident was caused by problems with the pavement just outside the front entrance. This may be because tree roots are growing under the paving stones and pushing them up. I feel that the path needs to be replaced if this type of accident is to be avoided in the future.\n\nI would also like the company to pay for the damage to my clothing. Replacing my trousers will cost around $200. I look forward to hearing from you.\n\nYours faithfully,\nHelen"},{"id":"t1-inf-match","unit":"w1.12","task":1,"kind":"info","style":"informal","title":"Tell your injured teammate about the match","situation":"You play a team sport with some friends. Last week a member of the team had an accident and wasn't able to play with you at the weekend. You decide to write to him in hospital, telling him about the match.","to":"Write a letter to your friend. In your letter,","bullets":["tell him which team won","describe the conditions on the day","say how you felt about the match"],"src":"Unit 12","sample":"Dear Frank,\n\nI was so sorry to hear about your accident! I hope you're feeling a lot better today and that it's not too boring in the hospital.\n\nThe match on Saturday was disappointing. The score was 2 all, probably because you weren't there to score that extra goal! The awful thing was that we were winning until 10 minutes before the end when suddenly they scored another goal. I was so shocked when I saw the ball hit the back of the net.\n\nI think the weather was to blame. It was a really wet day and the pitch was very muddy. By the end of the game, you could hardly see the grass and we were sliding around in the mud. Everyone was exhausted.\n\nLet us know when you're going home and we'll arrange for someone to bring you to watch the next game. The rest of the team send their regards and we all wish you a speedy recovery.\n\nBest wishes,\nCharlie"},{"id":"t1-req-extension","unit":"w1.12","task":1,"kind":"request","style":"formal","title":"Ask your lecturer for an extension","situation":"You won't be able to hand your assignment in on time.","to":"Write to your lecturer asking for an extension.","bullets":["describe the situation","explain why your assignment will be late","say when you will be able to hand in your assignment"],"src":"Unit 12","sample":"Dear Mr Murray,\n\nI am sorry to have to tell you that I will be unable to hand in my Geography assignment due on the 14th of September.\n\nUnfortunately, my mother has had a heart attack and I have to fly back to China to see her as soon as possible. At the moment I am on stand-by for the next available flight, so I do not know when I will be leaving or when I will be coming back.\n\nI believe that I will be away for two weeks at the most, and I think that I will be able to do some work while I am in China. However, I will almost certainly need an extension on my assignment. Please could you give me permission to hand it in on the 21st of September? This would be one week later than expected.\n\nCould you let me know as soon as possible whether I can get an extension? I am sorry for any inconvenience I have caused.\n\nYours sincerely,\nJohn"},{"id":"t1-req-car","unit":"w1.13","task":1,"kind":"request","style":"formal","title":"Hiring a car for a wheelchair user","situation":"You are going on holiday and you would like to hire a car. One of your party is in a wheelchair.","to":"Write a letter to a car hire company. In your letter:","bullets":["explain the reason you need the car","describe the type of car you need","ask what the price is and what it includes"],"src":"Unit 13","sample":"Dear Sir/Madam,\n\nI found out about your car hire company from your website and I would like some information.\n\nMy family and I are flying to Tashkent on 22 December and we would like to rent a car to travel around while we are there. We would return the car to the airport on the 29th of December.\n\nAs there will be six people in our group, we will need a large car. We will also be accompanied by my brother, who is in a wheelchair. Therefore, we will need a car with lots of storage space and, if possible, a ramp for easy access.\n\nPlease could you let me know if you have anything suitable and whether there would be an extra cost. In addition, I would like to know whether your prices include insurance.\n\nI look forward to your reply.\n\nYours faithfully"},{"id":"t1-cmp-bus","unit":"w1.13","task":1,"kind":"complaint","style":"formal","title":"Changes to the bus timetable","situation":"The local government is planning to change the bus timetable. You are not happy about the proposed changes.","to":"Write a letter to the newspaper. In the letter","bullets":["describe the changes","explain how they will affect you","say how you would improve the service"],"src":"Unit 13 · 13.5","sample":"Dear Sir or Madam,\n\nI saw in last week's edition the article about the proposed changes to the 391 bus from East Gardens to the City.\n\nI am sure that I am not the only one affected by this change. Reducing the number of 391 buses during the early morning rush hour will affect many people who need this link to catch a train from Central Station. Without this bus, people will be forced to abandon public transport and drive to work. This would contribute to the ever-increasing traffic jams in the city.\n\nI suggest that the government should run this bus more frequently and schedule it to coincide with the train timetable in order to make travelling easier. Better still, the government could extend the rail link from the city to the eastern suburbs. This way they could cut down the number of drivers on the road and reduce everyone's travel time.\n\nYours faithfully"},{"id":"t1-apo-library","unit":"w1.14","task":1,"kind":"apology","style":"formal","title":"Library books you can't return on time","situation":"You borrowed some books from your school library. Unfortunately, you have to go away to visit a sick relative and cannot return the books in time.","to":"Write a letter to the library.","bullets":["introduce yourself","explain what has happened","and tell them what you want to do about it"],"src":"Unit 14 · 14.6"},{"id":"t1-s15-1","unit":"w1.15","task":1,"kind":"job","style":"formal","title":"Can't continue an evening course","situation":"You have a full-time job and are also doing a part-time evening course. You now find that you cannot continue the course.","to":"Write a letter to the course tutor. In your letter","bullets":["describe the situation","explain why you cannot continue at this time","say what action you would like to take"],"src":"Unit 15 · Sample 1","sample":"Dear Mr Smith,\n\nI am writing to inform you that I will be unable to continue with the part-time computer programming course.\n\nI have been attending your evening classes for the last two months, and have enjoyed them immensely. As I stated on my course application form, I work full-time for a large IT company, and until now I have managed to fit the programming course into my schedule.\n\nHowever, my company is currently on the verge of signing a contract with an important new client in China, and I am part of the team that is being sent to Beijing to negotiate terms and conditions. I will probably be out of the country for several weeks.\n\nI am aware that you run the same course twice a year. Rather than try to catch up when I return from China, I was wondering if it would be possible for me to join the next cohort in September.\n\nI look forward to receiving your response.\n\nYours sincerely,\nPaul Jones"},{"id":"t1-s15-2","unit":"w1.15","task":1,"kind":"complaint","style":"formal","title":"Missed a flight because of airline staff","situation":"You missed a flight due to a problem at the airport.","to":"Write a letter to the airline. In your letter","bullets":["describe what happened that caused you to miss the flight","explain how missing your flight affected you","make it clear what you would like the airline to do"],"src":"Unit 15 · Sample 2","sample":"Dear Sir or Madam,\n\nI am writing with regard to a flight that I missed due to a mistake by one of your employees.\n\nTwo weeks ago, I was due to catch a flight to Rome, where I intended to spend four days on holiday. Unfortunately, the attendant at the check-in desk gave me a boarding card for a different flight, and I did not notice the mistake until I arrived at the departure gate and it was too late.\n\nAs a result of the error, I was not allowed to board the flight to Rome, and this caused me great inconvenience. I had to book a new flight two days later, which meant that I missed two days of my holiday and I spent an extra $200.\n\nAs the mistake was caused by your company, I hope that you will compensate me for the cost of the additional flight as well as for my taxi fares to and from the airport.\n\nI look forward to receiving your response.\n\nYours faithfully,\nPaul Jones"},{"id":"t1-s15-3","unit":"w1.15","task":1,"kind":"request","style":"formal","title":"Asking your manager for time off","situation":"You are working for a company. You need to take some time off work and want to ask your manager about this.","to":"Write a letter to your manager. In your letter","bullets":["explain why you want to take time off work","give details of the amount of time you need","suggest how your work could be covered while you are away"],"src":"Unit 15 · Sample 3","sample":"Dear Mr Smith,\n\nI am writing to ask for some time off work next month.\n\nThe reason for this request is that my brother is getting married. His future wife is Australian, and the wedding will take place in her home city, Melbourne. As the brother of the groom, I cannot miss such a special occasion.\n\nTo attend the ceremony and make the round trip from the UK, I would need at least five days off work. However, I would like to take the opportunity to do some sightseeing in Australia, so I am hoping that you will allow me to take a full two weeks' leave from the 1st to the 15th of May.\n\nI have spoken to my co-workers, and it seems that Peter Jones would be best placed to cover my project commitments while I am away. I will leave detailed instructions for him on my desk.\n\nI hope that my request does not cause you any inconvenience.\n\nYours sincerely,\nMichael Hall"},{"id":"t1-s15-5","unit":"w1.15","task":1,"kind":"complaint","style":"formal","title":"Lost camera — insurance claim","situation":"On a recent holiday you lost a valuable item. Fortunately, you have travel insurance to cover the cost of anything lost.","to":"Write a letter to the manager of your insurance company. In your letter","bullets":["describe the item you lost","explain how you lost it","tell the insurance company what you would like them to do"],"src":"Unit 15 · Sample 5","sample":"Dear Sir/Madam,\n\nI am writing to inform you that I recently lost my digital camera while on holiday in Vietnam.\n\nThe camera is a black Canon 70D and cost $1550 when I bought it new last month. It has a resolution of 20 megapixels, a Canon 67 millimetre lens and was in a brown leather case with my name on it.\n\nI lost it when I was having coffee with my husband in the backpacker area of Ho Chi Minh City. I believe the coffee shop was called Highlands Coffee and it was on Pham Ngu Lao Street. We had been at the coffee shop for around 45 minutes when I noticed it was missing.\n\nI am entitled to make a claim for the value of the above-mentioned item and request that you send me details of what I need to do in order to proceed.\n\nI look forward to hearing from you at your earliest convenience.\n\nYours faithfully,\nJohn Smith"},{"id":"t1-s15-6","unit":"w1.15","task":1,"kind":"complaint","style":"formal","title":"A faulty toy from an online shop","situation":"You have recently purchased a toy from an online shop, but the delivered product is faulty.","to":"Write a letter to the owner of the shop. In your letter","bullets":["describe the toy","give details of the problem","tell the owner what you want him/her to do"],"src":"Unit 15 · Sample 6","sample":"Dear Sir or Madam,\n\nI am writing this letter to complain about the faulty delivery of my product.\n\nYesterday, the brown teddy bear which I ordered from your website was delivered to my house. The bear appears to be made from polyester, and it is wearing a purple dress and matching hat, which are fashioned from a heavy velvet material. As well as that, the bear's paws are covered with red and white checkered cloth.\n\nHowever, the nose of the bear had not been firmly attached and fell off this morning. The bear was placed on a shelf immediately after the delivery and has not been touched since. I am, therefore, entirely confident that the issue was caused during the manufacturing process, rather than something that happened since it was delivered.\n\nAs this product was purchased as a gift for my daughter's birthday this weekend, I need you to send a replacement to me before the end of the week. My wife will be at home during the daytime, which means that your delivery driver can come at any time that is convenient for you.\n\nYours faithfully,\nLar Ryan"},{"id":"t1-s15-7","unit":"w1.15","task":1,"kind":"info","style":"formal","title":"New apartments planned in a public park","situation":"You have heard about plans to build new apartments in a public park near your home. You want to give your opinion about this.","to":"Write a letter to the editor of your local newspaper. In your letter","bullets":["explain how you learnt about these plans","say what you think of the park","give your opinion on the plans"],"src":"Unit 15 · Sample 7","sample":"Dear Sir or Madam,\n\nMy name is Mohammad Khatib, and I am a regular reader of your newspaper. I am writing to let you know of some rumours, which I hope are untrue, that I have heard recently about construction plans in our popular public park.\n\nAs you know, this is the only park within our immediate vicinity, and many people go there for relaxation. Many children also play in this park with their peers. I have recently heard from some of my neighbours that Royal Construction Company intends to build some apartment blocks in the park. At first, I did not take it seriously until yesterday, when I saw some engineers measuring and calculating different dimensions of the park.\n\nWe all like our local park, including its beautiful fountains, its playground and amusing facilities for children. So, as the representative of most of the neighbours, I have collected signatures against this project.\n\nTherefore, we, as local residents, disagree with the plan and kindly ask you to write an article about the disadvantages of this action and express our great disapproval of the plan. We are looking forward to seeing your article as our voice soon.\n\nThank you for your cooperation in advance.\n\nYours faithfully,\nMohammad Khatib"},{"id":"t1-s15-8","unit":"w1.15","task":1,"kind":"info","style":"informal","title":"Tell your best friend you've moved house","situation":"You have recently moved to a new house and want to inform your best friend about it.","to":"Write a letter to your friend. In the letter","bullets":["explain the reason for moving","describe your new house","invite him/her to your new house"],"src":"Unit 15 · Sample 8","sample":"Dear Jasur,\n\nI'm just writing to let you know that I've moved house.\n\nAs you know, I went for an interview for a job here in Tashkent. Well, they gave me the position! It would have been impractical to travel from Chinoz every day, so we've found a house here, in a nice part of Tashkent called Sebzor.\n\nOur new house isn't ideal. Tashkent prices are crazy, and we were only able to afford a one-bedroom flat. But on the bright side, it's on the ground floor, it's got nice big windows, and a lovely view out onto the garden.\n\nIf you ever fancy a trip to Tashkent, you're more than welcome to come and stay. It would be great to see you. From where we live, it's only a quick ride on the underground into the city centre, so we could do some sightseeing together.\n\nKeep in touch!\n\nAll the best,\nMurod"},{"id":"t1-s15-9","unit":"w1.15","task":1,"kind":"request","style":"informal","title":"Ask a friend to translate a document","situation":"You need a translation of a document into a different language, and you have a friend who speaks that language.","to":"Write a letter to your friend. In your letter","bullets":["explain what the document is and why you need a translation","explain why this is urgent and important for you","ask your friend if and when he/she will be able to help you"],"src":"Unit 15 · Sample 9","sample":"Dear Jane,\n\nI hope you're well. I'm writing to ask for your help with a document that I need to have translated into French.\n\nAs you know, I've been given the opportunity to spend a semester at a business school in Paris. Well, they've asked me to provide a translated copy of my degree certificate with the original.\n\nI've been told that I must submit both documents this week in order to secure my place on the course. They will give my place to someone else if I don't get the translation done; I'm running out of time, and you're my only hope!\n\nDo you think you could do me a big favour and give me an hour or so of your time either tomorrow or Wednesday? It shouldn't take you long to translate the certificate, and I can come to see you whenever suits you best.\n\nIf you're able to help, just let me know when you'd like me to pop round.\n\nSpeak soon,\nChris"},{"id":"t1-s15-10","unit":"w1.15","task":1,"kind":"info","style":"informal","title":"Offer your concert ticket to a friend","situation":"You bought a ticket to a music concert. However, you are unable to go, so you decide to offer your ticket to a friend.","to":"Write a letter to your friend. In your letter:","bullets":["tell your friend about the details of the concert","explain why you are unable to go","and explain how your friend can receive your ticket"],"src":"Unit 15 · Sample 10","sample":"Dear John,\n\nI hope you're well. I'm just writing to offer you a concert ticket that I won't be able to use.\n\nDo you remember that I told you I was going to a gig this Saturday? There's an up-and-coming singer and guitarist who's playing at the Apollo Theatre. I think you'll be blown away by how good he is. The concert starts at 7 pm, but there's a support act on first, so you can arrive a bit later if you just want to catch the main performance.\n\nThe reason why I'm offering you my ticket is that I've been asked to visit a client in Germany to help with a product launch, and I won't be back until Monday.\n\nIf you're free on Saturday evening and you'd like to go, just speak to my brother. He'll be going to the gig, so you won't be alone, and you can arrange to meet beforehand or outside the venue on the night.\n\nI hope you can make it, and that you enjoy the concert!\n\nSee you soon,\nSimon"},{"id":"t1-s15x-1.5","unit":"w1.15","task":1,"kind":"job","style":"formal","title":"Can't continue volunteering at a charity","situation":"You have been serving as a member of a local charity organization. You now find that you cannot continue your membership duties due to personal reasons.","to":"Write a letter to the organization's coordinator. In your letter:","bullets":["describe the situation","explain why you cannot continue your duties at this time","state what action you would like to take"],"src":"Unit 15 · 1.5"},{"id":"t1-s15x-2.4","unit":"w1.15","task":1,"kind":"apology","style":"formal","title":"Missed a crucial school exam","situation":"You missed a crucial exam at school due to a personal emergency.","to":"Write a letter to your teacher. In your letter:","bullets":["describe why you could not sit the exam","explain how missing the exam has impacted your academic progress and grades","make it clear what actions you would like your teacher to consider"],"src":"Unit 15 · 2.4"},{"id":"t1-s15x-3.4","unit":"w1.15","task":1,"kind":"request","style":"formal","title":"Time off from your English course","situation":"You are learning English at a language centre. You need some time off your course.","to":"Write a letter to your tutor. In your letter:","bullets":["explain why you need time off from the course","provide details about the duration and dates for which you need the time off","suggest a plan for how your learning progress can be managed during your absence"],"src":"Unit 15 · 3.4"},{"id":"t1-s15x-4.3","unit":"w1.15","task":1,"kind":"request","style":"formal","title":"Booking a venue for a family celebration","situation":"You and your family are planning a special event, like a birthday party or anniversary celebration, and you need to book a suitable venue.","to":"Write a letter to an event venue coordinator. In your letter:","bullets":["introduce yourself and briefly describe the event","describe the type of venue you are looking for and any specific requirements","specify your preferred location and date for the event"],"src":"Unit 15 · 4.3"},{"id":"t1-s15x-5.3","unit":"w1.15","task":1,"kind":"complaint","style":"formal","title":"Home burglary — insurance claim","situation":"Your home was burglarized, and several valuable items were stolen. Thankfully, you have home insurance.","to":"Write a letter to the insurance company. In your letter:","bullets":["describe the stolen items, including their estimated value","explain how the burglary occurred","tell the insurance company what you would like them to do"],"src":"Unit 15 · 5.3","sample":"Dear Sir/Madam,\n\nI am writing to report a recent unfortunate incident regarding my home. On 2 November 2024, my home was burglarized, resulting in the loss of several valuable items.\n\nThe stolen items include a 55-inch Samsung Smart TV (valued at approximately $800), a MacBook Pro laptop (valued at around $1,200), a Nikon DSLR camera with accessories (estimated at $1,500), and various items of jewellery with an estimated combined value of $3,000.\n\nThe burglary occurred during the evening when my family and I were away. The burglars gained entry by forcing open a rear window, subsequently breaking into our home and stealing the aforementioned items.\n\nTherefore, I would like to request your prompt assistance in processing a claim for the stolen property. I have attached the police report and a detailed list of the stolen items for your reference.\n\nThank you for your attention to this matter, and I look forward to your prompt response.\n\nYours sincerely,\nUtkir Kenjayev"},{"id":"t1-s15x-5.4","unit":"w1.15","task":1,"kind":"complaint","style":"formal","title":"Car accident — insurance claim","situation":"You were involved in a car accident, and your vehicle sustained significant damage.","to":"Write a letter to your car insurance company. In your letter:","bullets":["describe the extent of the damage to your vehicle","explain the details of the car accident","tell the insurance company what you would like them to do"],"src":"Unit 15 · 5.4"},{"id":"t1-s15x-6.4","unit":"w1.15","task":1,"kind":"complaint","style":"formal","title":"A book with missing pages","situation":"You purchased a book online, but when it arrived, it had missing pages and printing errors.","to":"Write a letter to the online bookstore. In your letter:","bullets":["describe the book you ordered","explain the issues you encountered with the book's quality","tell the online bookstore what you would like them to do about the problem"],"src":"Unit 15 · 6.4"},{"id":"t1-s15x-7.4","unit":"w1.15","task":1,"kind":"info","style":"formal","title":"No recycling facilities in your community","situation":"There is a growing concern about the lack of recycling facilities in your community.","to":"Write a letter to the local government. In your letter:","bullets":["explain the importance of recycling for the environment","address the absence of accessible recycling bins or centres","suggest initiatives or programmes to promote recycling in the area"],"src":"Unit 15 · 7.4"},{"id":"t1-s15x-8.3","unit":"w1.15","task":1,"kind":"info","style":"informal","title":"Tell a friend about your trip abroad","situation":"You have recently taken a trip to a foreign country and want to share your experience with a friend who couldn't join you.","to":"Write a letter to your friend. In the letter:","bullets":["explain the reason for your trip","describe some memorable experiences and places you visited","invite your friend to plan a future trip together"],"src":"Unit 15 · 8.3"},{"id":"t1-s15x-9.4","unit":"w1.15","task":1,"kind":"request","style":"informal","title":"Ask a tech-savvy friend for computer help","situation":"You have recently experienced a problem with your computer, and you need assistance from a tech-savvy friend.","to":"Write a letter to your friend. In your letter:","bullets":["describe the issue you are facing with your computer","explain why it is crucial to resolve this issue promptly","ask your friend if they can help you with the problem and when they might be available"],"src":"Unit 15 · 9.4"},{"id":"t1-s15x-10.3","unit":"w1.15","task":1,"kind":"info","style":"informal","title":"Offer your sports ticket to a friend","situation":"You have purchased a ticket to a sports event, but you can't attend, so you decide to offer your ticket to a friend.","to":"Write a letter to your friend. In your letter:","bullets":["share the details of the sports event","explain why you won't be able to attend the event","inform your friend how they can collect the ticket from you"],"src":"Unit 15 · 10.3"},{"id":"wt01-1","unit":"exam","set":1,"task":1,"kind":"info","style":"formal","title":"Council plans to demolish a local building","situation":"The local council has decided to destroy a building in your neighbourhood. You disagree with this decision.","to":"Write a letter to the local councillor. In your letter","bullets":["tell what building is going to be destroyed","explain why the building is useful for people","suggest how to improve the building"],"src":"Writing tasks · Variant 1"},{"id":"wt02-1","unit":"exam","set":2,"task":1,"kind":"job","style":"formal","title":"Resigning from your job as a waiter","situation":"You are working as a waiter/waitress in a restaurant. You are going to resign from your job.","to":"Write to the restaurant manager. In your letter","bullets":["say why you are resigning","say what good things you have got from your job","say what you want the restaurant to do (e.g. pay your salary earlier, give a reference letter)"],"src":"Writing tasks · Variant 2"},{"id":"wt03-1","unit":"exam","set":3,"task":1,"kind":"apology","style":"informal","title":"A friend's visit on a date you're busy","situation":"Your friend is coming to stay with you on holiday, but you are not available on that date.","to":"Write a letter to your friend. In your letter","bullets":["apologize for not being able to see him/her","give a reason why you are not available","suggest another day for your friend's visit"],"src":"Writing tasks · Variant 3"},{"id":"wt04-1","unit":"exam","set":4,"task":1,"kind":"info","style":"formal","title":"You found a lost suitcase","situation":"You found a lost suitcase on which the owner's name and address were labelled.","to":"Write a letter to the owner. In your letter","bullets":["describe the luggage you found","explain where you found it","suggest how the owner could get it back"],"src":"Writing tasks · Variant 4"},{"id":"wt05-1","unit":"exam","set":5,"task":1,"kind":"request","style":"formal","title":"Recommend an interpreter at work","situation":"Your workplace requires an interpreter to translate from one language to another during meetings.","to":"Write to your manager. In your letter","bullets":["recommend someone to act as an interpreter","explain why the person is qualified for the role","tell how the person can be contacted"],"src":"Writing tasks · Variant 5"},{"id":"wt06-1","unit":"exam","set":6,"task":1,"kind":"info","style":"formal","title":"Your opinion about a magazine","situation":"You have recently bought a magazine and its manager asked the readers for their opinion about the magazine.","to":"Write a letter to the manager. In your letter","bullets":["give a reason why you chose this magazine","explain what you like and dislike about it","say what improvement you hope to see in the future"],"src":"Writing tasks · Variant 6"},{"id":"wt07-1","unit":"exam","set":7,"task":1,"kind":"complaint","style":"formal","title":"Café tables blocking the pavement","situation":"A café near your home has put some chairs and tables on the pavement for customers. This creates a problem for you.","to":"Write a letter to the manager of the café to complain about this matter. In your letter,","bullets":["describe the problem","explain how it affects you","say what you will do if this matter is not resolved"],"src":"Writing tasks · Variant 7"},{"id":"wt08-1","unit":"exam","set":8,"task":1,"kind":"condolence","style":"informal","title":"A classmate broke his arm","situation":"Your classmate has broken his arm and so cannot come to school for two weeks.","to":"Write to your friend. In your letter","bullets":["express your sympathy for the incident","tell him/her some news from school","offer your help for him/her to keep up with studies"],"src":"Writing tasks · Variant 8"},{"id":"wt09-1","unit":"exam","set":9,"task":1,"kind":"thanks","style":"formal","title":"Booking a photographer for a family event","situation":"You had some photos of your family taken by a professional photographer.","to":"Write a letter to the photographer. In your letter","bullets":["say that you liked his photos of your family","ask him to be your photographer at a special family event","give him the details of the event"],"src":"Writing tasks · Variant 9"},{"id":"wt10-1","unit":"exam","set":10,"task":1,"kind":"apology","style":"formal","title":"Missed a staff meeting","situation":"You had to attend a staff meeting at work but you couldn't.","to":"Write a letter to the manager. In your letter:","bullets":["apologize for your absence","explain why you couldn't be there","ask him to send you brief information about the meeting"],"src":"Writing tasks · Variant 10"},{"id":"wt11-1","unit":"exam","set":11,"task":1,"kind":"request","style":"formal","title":"Volunteering to maintain a local school","situation":"You live near a school. The school has asked residents to help with the maintenance of school buildings and play areas.","to":"Write a letter to the principal. In your letter","bullets":["explain why you would like to help","tell them how you can help","let them know when you are available"],"src":"Writing tasks · Variant 11"},{"id":"wt12-1","unit":"exam","set":12,"task":1,"kind":"thanks","style":"semi","title":"Saying goodbye to your neighbour","situation":"You are moving home.","to":"Write a letter to your neighbour to say goodbye and to thank them for their help during your stay. In your letter","bullets":["explain how they helped you","say what you will miss most about the area where you lived","invite them to visit you at your new home"],"src":"Writing tasks · Variant 12"},{"id":"wt13-1","unit":"exam","set":13,"task":1,"kind":"complaint","style":"formal","title":"A problem with furniture from another town","situation":"You recently bought a piece of furniture from a store in another town. There is a problem with the item you bought.","to":"Write a letter to the store manager. In your letter","bullets":["provide the details of your purchase","describe the problem with the furniture","suggest what can be done about it"],"src":"Writing tasks · Variant 13"},{"id":"wt14-1","unit":"exam","set":14,"task":1,"kind":"thanks","style":"formal","title":"Moving out — thank your landlord","situation":"You are renting a house and the landlord has been very helpful during your stay. Your friend is interested in renting your place.","to":"Write a letter to your landlord to inform them that you will be moving out. In your letter,","bullets":["tell your landlord that you are leaving and explain the reason","thank your landlord for being helpful","recommend your friend as a prospective tenant"],"src":"Writing tasks · Variant 14"},{"id":"wt15-1","unit":"exam","set":15,"task":1,"kind":"request","style":"formal","title":"Clothing left at a hotel","situation":"You forgot an item of clothing at the hotel where you stayed recently.","to":"Write a letter to the hotel manager. In your letter","bullets":["explain when and in which room you stayed","describe the item you left behind","ask the manager to take certain actions"],"src":"Writing tasks · Variant 15"},{"id":"wt16-1","unit":"exam","set":16,"task":1,"kind":"complaint","style":"formal","title":"An unsafe college playground","situation":"You are concerned about a playground at your local college.","to":"Write a letter to the college principal. In your letter:","bullets":["express your worry about things in the playground that are not safe","explain why it is important to fix them","suggest any improvements that would make the playground safe for everyone"],"src":"Writing tasks · Variant 16"},{"id":"wt17-1","unit":"exam","set":17,"task":1,"kind":"complaint","style":"formal","title":"An evening course unlike its advertisement","situation":"You have started an evening course. You think that the course is a little different from the information in the advertisement for the course.","to":"Write to the manager of the education centre. In your letter:","bullets":["provide the details of the course","explain what the problem is","give some suggestions to fix the problem"],"src":"Writing tasks · Variant 17"},{"id":"wt18-1","unit":"exam","set":18,"task":1,"kind":"info","style":"informal","title":"Studying at a university abroad","situation":"You have started studying at a university abroad.","to":"Write to your friend in your country. In your letter:","bullets":["tell where you are studying","explain how you feel in a foreign country","advise him/her to apply to your university"],"src":"Writing tasks · Variant 18"},{"id":"wt19-1","unit":"exam","set":19,"task":1,"kind":"request","style":"formal","title":"A day off school for a family occasion","situation":"Your family is going to celebrate an occasion and you need a day off from school.","to":"Write a letter to your teacher. In your letter:","bullets":["tell what the occasion is","explain why you should attend this occasion","tell how you are going to make up for the missed lessons"],"src":"Writing tasks · Variant 19"},{"id":"wt20-1","unit":"exam","set":20,"task":1,"kind":"complaint","style":"formal","title":"An upsetting incident on public transport","situation":"You experienced an incident on public transport and it caused you distress.","to":"Write a letter to the manager of the public transport company. In your letter:","bullets":["describe the incident","explain how this incident affected you","suggest what could be done about it"],"src":"Writing tasks · Variant 20"},{"id":"t2-adv-tv","unit":"w2.18","task":2,"kind":"adv","title":"Spending free time watching TV","q":"Many people around the world spend the majority of their free time at home watching TV shows.\nWhat are the advantages and disadvantages of this situation?","src":"Unit 19","min":250},{"id":"t2-adv-uni","unit":"w2.19","task":2,"kind":"adv","title":"Moving away from home to attend university","q":"Some university students live with their families while studying, but others prefer to move away from home.\nDo the benefits of moving out to attend university outweigh the disadvantages?","src":"Unit 19","min":250,"sample":"Some students stay at their family home while attending university, but other students decide to move out. The advantages of moving away from home to attend university do not outweigh the drawbacks because the main disadvantages are the cost of living and the lack of focus on studies, whereas the only advantage is learning to be independent.\n\nThe first disadvantage of living away from home is the increased cost of living. That is to say that there are extra costs such as accommodation that don't need to be paid by those who stay with their families. As it usually takes four years to complete a university degree, these costs put considerable strain on an average family's finances.\n\nAnother downside is that students who move out of home tend to be less focused on their studies. Because they have nobody making sure they attend university every day, they are far more likely to skip lectures when they're tired or not in the mood. When I was at college, for instance, it was very rare for someone who lived with their parents to miss a lecture, which was not the case for those in rented accommodation.\n\nHowever, there is the advantage in having more independence. Students who live away from family are responsible for all aspects of their lives and need to complete household chores that their family members would otherwise complete. From these responsibilities, they become more independent, and this independence generally translates into other situations as well.\n\nIn conclusion, the advantages of moving away from home to study at university do not outweigh the disadvantages as this costs substantially more money, and these students are less focused on their studies. But, on the other hand, there is the advantage of becoming more independent."},{"id":"t2-adv-zoo","unit":"w2.19","task":2,"kind":"adv","title":"Keeping animals in zoos","q":"Some experts believe it is better for animals to live in zoos where they are safe and are given all the food they need.\nDo the advantages of keeping animals in zoos outweigh the disadvantages?","src":"Unit 19","min":250},{"id":"t2-adv-games","unit":"w2.19","task":2,"kind":"adv","title":"Video games: useful or harmful?","q":"Some people think that playing video games is useful. Others, however, believe that video games are having a negative effect on the people who play them.\nDo the drawbacks of video games outweigh the benefits?","src":"Unit 19","min":250,"sample":"Many people, and children in particular, enjoy playing computer games, but other people think they are more likely to have a harmful impact on the user. The advantages of playing computer games outweigh the drawbacks because the main advantages are that they can be educational and entertaining, whereas the only disadvantage is their addictive nature.\n\nOne of the advantages of video games is that they can be an educational tool. These games develop the user's creativity, concentration, logical thinking and problem-solving skills. For example, in racing games, the participant carefully analyses the opponents, makes various calculations and works out the shortest routes to win. Such skills will help them to cope with real-life tasks.\n\nAnother advantage of video games is their ability to serve as a source of entertainment. These games offer a gateway to the virtual world, providing an exciting and unique experience. When playing games like Blur racing, users dive into imaginative landscapes, leaving the real world behind. This immersive escape not only offers a thrilling pastime but also serves as a means to relieve stress, achieve relaxation, and thus enhance overall well-being.\n\nHowever, there is a disadvantage in becoming addicted to playing games. Games can be very addictive because they keep giving players scores, new goals, and rewards to make them keep playing. Nowadays, many children spend lots of time each day trying to reach higher levels in a game or beat their friends' scores. This kind of addiction can cause issues, from not getting enough sleep to having problems at school when homework is ignored in favour of spending more time on the computer or game console.\n\nIn conclusion, playing video games has various effects on a gamer's life. They serve as effective educational tools and sources of entertainment despite the risk of addiction. Overall, the benefits of playing video games generally outweigh the drawbacks."},{"id":"t2-adv-fastfood","unit":"w2.19","task":2,"kind":"adv","title":"Cheaper and more available fast food","q":"In many countries, fast food is becoming cheaper and more widely available.\nDo the disadvantages of this outweigh the advantages?","src":"Unit 19","min":250,"sample":"We can see fast food restaurants on every street in cities, and consuming this kind of food is becoming increasingly popular day by day. The advantages of fast food outweigh its disadvantages because the main advantages are that it is affordable and quick to make, whereas the only disadvantage is that it can be unhealthy.\n\nThe first advantage of fast food is that it gives people inexpensive choices for their meals. Typically, fast food is much cheaper than organic food or fresh produce but can provide as many calories as other foods do. This helps low-income people to have enough food during the day. For example, many students and workers with low salaries are able to buy their lunch regularly without skipping it thanks to affordable fast food.\n\nAnother upside is that this food lets people save valuable time. Many fast-food restaurants provide food in a few minutes. Therefore, fast food is a good option for those who are in a hurry, do not have time to cook, and want to eat quickly. In many jobs, employees are given a one-hour lunch break, and fast food is a good option for them to have lunch during such a period and be back at work on time.\n\nHowever, there is the disadvantage of the possibility of consuming unhealthy food. Fast foods are considered junk food as they are usually high in calories and fat. Quite often, a single lunch at a fast-food place will satisfy an individual's caloric needs for the whole day. If consumed excessively, it leads a person to gain extra weight and, in the worst cases, to diseases like obesity, diabetes and cardiovascular problems.\n\nIn conclusion, the positives of eating fast food outweigh the disadvantages because of its affordability and speed of preparation. But, on the other hand, there is the negative of consuming junk food that is believed to be harmful."},{"id":"t2-adv-celebrity","unit":"w2.19","task":2,"kind":"adv","title":"Being a celebrity","q":"Being a celebrity — such as a famous film star or sports personality — brings problems as well as benefits.\nDo you think that being a celebrity brings more benefits or more problems?","src":"Unit 19","min":250,"sample":"Being in the public eye — such as a movie star or a professional football player — has its benefits and drawbacks. The advantages of being a well-known figure outweigh its disadvantages because it brings huge financial rewards and special respect from fans, whereas famous people suffer from a lack of privacy.\n\nThe first benefit of having a lot of fame is that celebrities are often fabulously wealthy. They quickly become millionaires, and this allows them to buy whatever they want for themselves and their loved ones, all for doing something they love. In the media, celebrities are seen living in luxurious mansions, driving expensive cars and wearing clothes that are out of reach for ordinary people, and all these expenses are covered by the earnings that come from their fame.\n\nMoreover, celebrities get special treatment wherever they go. In most places they find fans who express their respect or offer them privileges. From special seats at theatres to special tables at restaurants, celebrities are treated as preferred customers everywhere they go.\n\nHowever, it is often argued that being a celebrity comes at a price, and that price is the destruction of their private lives. Many complain that they cannot do normal things such as having a cup of coffee in a café as other people do. When they appear in public places, fans come and ask for a photo or an autograph. Well-known people are also followed by the media and the paparazzi trying to film them no matter whether they are in a good mood or a bad one.\n\nIn conclusion, the financial freedom and fans' respect associated with fame far outweigh the problems, particularly the constant attention from the press and fans."},{"id":"t2-op-tech","unit":"w2.20","task":2,"kind":"opinion","title":"Modern technology creates more problems than it solves","q":"Some people believe that modern technology, such as the internet and smartphones, creates more problems than it solves.\nTo what extent do you agree or disagree with this opinion?","src":"Unit 20","min":250,"sample":"Some individuals think that technology from the modern era, like the internet and smartphones, is creating more issues than it is resolving. I completely agree with this statement because people's mental health is suffering and, also, people don't enjoy their free time as much as they used to.\n\nFirst of all, modern technology is negatively affecting the mental health of many individuals. This is because an essential aspect of good mental health is processing what happens to us, particularly any negative experiences. However, with modern technology, many people don't take any time to reflect on their lives and instead spend all of their available time on the internet or watching television. These days, for instance, most customers in supermarket queues look at something on their phones, whereas before this technology, they had no option but to think about whatever came to mind.\n\nAnother drawback is the way that this technology has hindered how much people enjoy their leisure time. Passing the time with modern technology, such as phone apps or video games, requires minimal effort but is not as enjoyable or rewarding as hobbies such as playing a sport or gardening, which were more popular in the past. For example, in my family, most members had various outdoor pursuits that they did in the evenings, but now it's more common to see them sitting inside the house on their phones.\n\nIn conclusion, I agree that the advent of modern technology has created more issues than it has solved because of the decline in mental health that it has brought and the resulting lack of enjoyment that people experience in their free time."},{"id":"t2-op-plastic","unit":"w2.20","task":2,"kind":"opinion","title":"Replace plastic with glass","q":"Some people believe that we should replace all plastic products with more environmentally-friendly materials, such as glass.\nDo you agree or disagree?","src":"Unit 20","min":250},{"id":"t2-op-practical","unit":"w2.20","task":2,"kind":"opinion","title":"Practical skills at school","q":"Some people believe that students should study practical skills at school such as managing a bank account or car maintenance as well as traditional subjects.\nTo what extent do you agree or disagree?","src":"Unit 20","min":250},{"id":"t2-op-marriage","unit":"w2.20","task":2,"kind":"opinion","title":"People are getting married later","q":"As the average age at which people get married increases, some people worry that it will have a negative impact on the family.\nTo what extent do you agree or disagree?","src":"Unit 20","min":250},{"id":"t2-op-tvbooks","unit":"w2.20","task":2,"kind":"opinion","title":"Less TV, more books for children","q":"Some people believe that parents should limit how much time their children spend watching TV and encourage them to read books instead.\nTo what extent do you agree or disagree with this statement?","src":"Unit 20","min":250},{"id":"t2-op-freeedu","unit":"w2.20","task":2,"kind":"opinion","title":"Free education at all levels","q":"Some people believe that the government should provide free education at all levels.\nDo you agree or disagree with this statement?","src":"Unit 20","min":250},{"id":"t2-op-community","unit":"w2.20","task":2,"kind":"opinion","title":"Unpaid community service for young people","q":"Some people think that young individuals should be required to do unpaid community service in their spare time.\nDo you agree or disagree with this idea?","src":"Unit 20","min":250},{"id":"t2-op-eduspend","unit":"w2.20","task":2,"kind":"opinion","title":"More money on education than on sports","q":"Governments should spend more money on education than on recreation and sports.\nTo what extent do you agree or disagree with this statement?","src":"Unit 20","min":250},{"id":"t2-op-country","unit":"w2.20","task":2,"kind":"opinion","title":"Children should grow up in the countryside","q":"Some people think that it is better for children to grow up in the countryside than in a big city.\nDo you agree or disagree?","src":"Unit 20","min":250,"sample":"Some individuals believe that it is more beneficial to raise children in a rural area than in a large city. I completely disagree with this statement because bringing up young people in an urban area provides a wide range of opportunities for study and positive cultural exposure.\n\nFirst of all, there are more high-quality educational choices for young children in a city than in a village. This is mainly because better educational organizations such as learning centres and libraries are usually located in densely populated cities. In other words, young children living in urban areas take advantage of such opportunities far earlier than children growing up in the countryside. These days, for example, most teenagers from rural areas visit cities in search of better options to study.\n\nAnother advantage of bringing up children in large cities is exposing them to people from different cultures. Children growing up in cities have to communicate with individuals from various social and economic backgrounds, and this helps them to broaden their horizons and improve their communication skills. In contrast, children in villages tend to develop relationships with only a certain group of people, which prevents them from being exposed to different cultures and gaining real-life experience. For example, my cousins from a rural area are too shy to speak to strangers and therefore usually ask me for help with daily problems like booking a hotel room or bargaining with a salesperson in a clothes shop.\n\nIn conclusion, I firmly believe that the probability of receiving a quality education is significantly higher for children raised in big cities than in the countryside, and they become more well-rounded as people."},{"id":"t2-op-ai","unit":"w2.20","task":2,"kind":"opinion","title":"Artificial intelligence will improve our lives","q":"Some people believe that developments in the field of artificial intelligence will have a positive impact on our lives in the near future.\nTo what extent do you agree or disagree?","src":"Unit 20","min":250,"sample":"It is believed by some individuals that advancements in the sphere of artificial intelligence will have a positive effect on people's lives in the near future. I firmly agree with this idea because applying artificial intelligence properly would improve people's overall health and help people run their businesses more effectively.\n\nFirstly, implementing new technologies backed by artificial intelligence would improve the quality of health services. This is because possible human error during important surgical procedures can be avoided by using robots. Such technologies can work with greater precision than a human doctor and, therefore, they should be applied to improve the safety of patients. Additionally, mobile applications with built-in artificial intelligence can remind sick people about their daily medicine or exercise time. These reminders help people to be more responsible about their health.\n\nSecondly, individuals can increase the productivity of their business operations by applying software or machines powered by artificial intelligence. By analysing big data taken from regular customers, software can give accurate suggestions about which services or products should be offered to clients. This approach helps companies to gain a competitive advantage and a higher share of the market. Currently, for example, by analysing the GPS locations of commuters with artificial intelligence, the taxi company \"Yandex Taxi\" provides accurate information about the position of potential clients to its drivers, allowing them to serve more clients.\n\nIn conclusion, I completely believe that the intervention of artificial intelligence in our lives has many upsides, since it offers better medicine for people and supports more efficient enterprises in the economy."},{"id":"t2-ds-country","unit":"w2.21","task":2,"kind":"discuss","title":"Countryside or city?","q":"Some people believe that it's better to live in the countryside. Others argue that living in the city is superior.\nDiscuss both views and give your own opinion.","src":"Unit 21","min":250,"sample":"There are individuals who feel that living in a rural area is more beneficial, while others feel that the city is a better choice. Although there are some advantages of living in the city, I do believe living in the countryside has more positive sides.\n\nOn the one hand, some individuals like the countryside best as it's more peaceful. With all the noise from traffic and construction in urban areas, it's difficult to relax. Where I live, for example, trucks on the nearby highway blow their horns all through the night, and this regularly affects my sleep.\n\nOn the other hand, other individuals like city life best because the short journey to and from work is a significant advantage. As people in the countryside often spend hours commuting between their house and workplace, they lose a lot of time compared to those in the city. This means that people who live in urban areas have additional free time and get to spend it doing things they enjoy.\n\nMy opinion is that life in the countryside is better as private outdoor space is an enjoyable feature. Houses in the country tend to have space outside that belongs to the owner, but this is rare for city houses. Having this land is a massive benefit as it can be used for barbecue parties with friends and family.\n\nIn conclusion, some people prefer to live in the country as they are more relaxed in the peaceful environment. In contrast, others who prefer to live in a city enjoy the benefits of having a short commute to work. However, my own opinion is that countryside life is more enjoyable because of the private outdoor space."},{"id":"t2-ds-abroad","unit":"w2.21","task":2,"kind":"discuss","title":"Studying abroad for a well-paid job","q":"In an era of globalization, some people think that studying abroad is the best way to attain a well-paid job, while others believe other options are better.\nDiscuss both views and give your own opinion.","src":"Unit 21","min":250},{"id":"t2-ds-professionals","unit":"w2.21","task":2,"kind":"discuss","title":"Should doctors and engineers work where they trained?","q":"Some people believe that professionals, such as doctors and engineers, should be required to work in the country where they did their training. Others believe they should be free to work in another country if they wish.\nDiscuss both views and give your own opinion.","src":"Unit 21","min":250},{"id":"t2-ds-beautiful","unit":"w2.21","task":2,"kind":"discuss","title":"Beautiful or functional cities?","q":"Some feel that cities should be designed to be beautiful while others feel their functionality is more important.\nDiscuss both sides and give your own opinion.","src":"Unit 21","min":250},{"id":"t2-ds-holidays","unit":"w2.21","task":2,"kind":"discuss","title":"Many short holidays or fewer long ones?","q":"Some people think it is better to have many short holidays during the year. Others believe it would be beneficial to have fewer, longer vacations.\nDiscuss both views and give your opinion.","src":"Unit 21","min":250},{"id":"t2-ds-jobs","unit":"w2.21","task":2,"kind":"discuss","title":"Change jobs often or stay in one job?","q":"Some people say that individuals should change jobs often during their working life, while others believe that doing the same job has advantages to individuals, companies, and society.\nDiscuss both views and give your opinion.","src":"Unit 21","min":250},{"id":"t2-ds-recycle","unit":"w2.21","task":2,"kind":"discuss","title":"Learning to recycle: school or home?","q":"Some say that children should be taught at school to recycle and avoid waste. Others say they should learn this at home.\nDiscuss both views and give your opinion.","src":"Unit 21","min":250},{"id":"t2-ds-mistakes","unit":"w2.21","task":2,"kind":"discuss","title":"Should children be free to make mistakes?","q":"Some people think children should have the freedom to make mistakes, while other people believe that adults should prevent children from making mistakes.\nDiscuss both sides and give your opinion.","src":"Unit 21","min":250},{"id":"t2-ds-advertising","unit":"w2.21","task":2,"kind":"discuss","title":"Effects of advertising","q":"Some feel that the effects of advertising are positive for individuals and businesses, while others think they are negative.\nDiscuss both sides and give your own opinion.","src":"Unit 21","min":250},{"id":"t2-ds-teamsports","unit":"w2.21","task":2,"kind":"discuss","title":"Team sports and future careers","q":"Some people believe that team sports prepare children for their future careers, while others do not agree.\nDiscuss both views and give your own opinion.","src":"Unit 21","min":250},{"id":"t2-ds-career","unit":"w2.21","task":2,"kind":"discuss","title":"Who should choose a young person's job?","q":"Some people say young people should be completely free to choose their future job, but others think parents must be responsible for choosing a job for their children.\nDiscuss both views and give your own opinion.","src":"Unit 21","min":250,"sample":"It is claimed by some that teenagers should be independent in choosing their future career, while others insist that it is a parent's responsibility to choose a suitable occupation for their children. Although it might be beneficial if parents choose the right job for their children, I do believe young people should be given the right to decide their future work.\n\nOn the one hand, since parents have more real-life experience than their children, it is logical to rely on them when deciding on a job. This is mainly because older people tend to analyse trends in the occupations developing around them effectively. Therefore, they might know exactly which jobs will be in high demand and better paid in the long run.\n\nOn the other hand, if children choose their future career independently, they might become more successful in their chosen job. The reason is that they do what they love and spend quality time understanding the industry better. As a result, their productivity will increase, and this has a positive impact on both their personal and financial growth.\n\nMy opinion is that everybody knows their strengths and weaknesses better than their parents and, therefore, should choose their career individually. In other words, a person may not have the physical or mental ability to do the job chosen by their parents. Consequently, such people may never work productively, since they usually underestimate themselves and blame their parents for their failures.\n\nIn conclusion, some feel that parents, taking their experience into account, are the right people to decide their children's future job. In contrast, others think children should decide their future career independently because their work efficiency is higher if they do what they like. In my opinion, young people should take responsibility for deciding their future job; otherwise, they may not become professionals in their career."},{"id":"t2-ds-techgap","unit":"w2.21","task":2,"kind":"discuss","title":"Technology and the gap between rich and poor","q":"Some believe that advances in technology are increasing the gap between rich and poor, while others think the opposite is happening.\nDiscuss both sides and give your own opinion.","src":"Unit 21","min":250,"sample":"Some individuals feel that technological developments are widening the gap between rich and poor people, whereas others argue that such advancements are reducing it. Although there are several reasons why technology may contribute to this gap, I do believe progress in the tech industry is narrowing the difference.\n\nFirstly, wealth inequality is rising significantly due to the implementation of automation in most companies. This is because the automation of processes reduces the need for manual labour. As a result, competition for positions increases and wages go down. Thus, business owners using advanced technologies can generate even more money, while less-skilled employees get poorer by losing their jobs because of this progress.\n\nHowever, technological developments have created equal opportunities for both the poor and the rich to prosper financially by showing their skills. The reason is that even an impoverished person may achieve financial freedom by using modern devices. Popular bloggers on YouTube or Instagram are the best examples of how ordinary people can make more money by creating useful video content and adding advertisements to it.\n\nIn my opinion, with technological advancements, it is now possible for everyone to attend online courses which were affordable only for wealthy people in the past. For instance, a person may watch the lectures of top universities without attending the campus or paying expensive tuition fees. Eventually, the knowledge and experience gained online may provide equal chances for both rich and poor people to find a well-paid job.\n\nIn conclusion, due to the mass use of automation, the gap between the wealthy and the poor may widen. In contrast, using electronic devices effectively may help people with lower incomes to earn more. I firmly feel that the gap between the poor and the rich is narrowing, since innovations are creating equal opportunities for all that were mainly accessible only to the affluent before."},{"id":"t2-ps-crime","unit":"w2.22","task":2,"kind":"problem","title":"Serious crimes committed by young people","q":"In many countries, there is an increase in the number of serious crimes committed by young people.\nWhat do you think are the causes of this situation?\nWhat measures could be taken to solve this problem?","src":"Unit 22","min":250,"sample":"In many nations, rising numbers of young people are committing serious crimes. This is happening because many parents are too busy, and children have easy access to violent movies. To resolve this issue, governments should enforce a maximum number of hours that people can work, and websites with mature content should require their visitors to register.\n\nOne of the primary reasons for more crimes being committed by young people is that parents must work longer hours. Because they don't have the time to care for their children properly, some young people use the additional freedom to explore criminal activities. Furthermore, with the advent of the internet, young people can easily access inappropriate films, and some come to admire the violent characters portrayed and so imitate the behaviour they observe.\n\nThe first way this can be resolved is by setting a limit to the number of hours that anyone can work. If parents spend less time at work, they will have the opportunity to closely foster their children and guide them away from any unlawful behaviour. In addition to this, websites that provide access to movies unsuitable for children should require their visitors to create accounts that confirm their age. This will ensure that children are not exposed to inappropriate content and will not be negatively affected.\n\nIn conclusion, more young people are breaking the law because their parents are too busy working, and violent content can readily be accessed on websites. To overcome this, governments should set a maximum number of working hours per person, and websites with violent movies must get visitors to register and confirm their age."},{"id":"t2-ps-cities","unit":"w2.22","task":2,"kind":"problem","title":"Problems of living in large cities","q":"People who live in large cities face a range of problems in their daily life.\nWhat are the main problems people in cities face?\nHow can these problems be tackled?","src":"Unit 22","min":250},{"id":"t2-ps-teachers","unit":"w2.22","task":2,"kind":"problem","title":"Fewer people want to become teachers","q":"These days, in many countries, fewer and fewer people want to become teachers, particularly in secondary schools.\nWhat are the reasons for this?\nHow could the problem be solved?","src":"Unit 22","min":250},{"id":"t2-ps-warming","unit":"w2.22","task":2,"kind":"problem","title":"Global warming","q":"Global warming is one of the biggest threats to our environment.\nWhat causes global warming?\nWhat solutions are there to this problem?","src":"Unit 22","min":250},{"id":"t2-ps-behaviour","unit":"w2.22","task":2,"kind":"problem","title":"Behaviour in schools is getting worse","q":"Behaviour in schools is getting worse.\nExplain the causes and suggest some possible solutions.","src":"Unit 22","min":250},{"id":"t2-ps-obesity","unit":"w2.22","task":2,"kind":"problem","title":"Childhood obesity","q":"Childhood obesity is becoming a serious problem in many countries.\nExplain the main causes and suggest some possible solutions.","src":"Unit 22","min":250},{"id":"t2-ps-neighbours","unit":"w2.22","task":2,"kind":"problem","title":"People don't know their neighbours","q":"Today, many people do not know their neighbours in large cities.\nWhy is this?\nWhat can be done about this?","src":"Unit 22","min":250,"sample":"In capital cities, neighbours do not often interact or even know each other. This happens because people are too busy and neighbours keep changing in city apartments. To mitigate this, social events and online neighbourhood groups should be organized.\n\nOne of the major reasons why many residents today do not often speak with their neighbours is that most people do not have enough time to build relationships with them. As the cost of living is higher in megacities, most people have to work hard until the evening. Even when they come back home, they try to spend quality time with their children. As a result, they lack time to spend with other people in their neighbourhood. Another cause is that the residents of a neighbourhood tend to change quite often in cities. Before stable bonds are formed, a neighbour may move out and a new one arrives. Therefore, many people do not know their neighbours well enough to have friendly relationships.\n\nTo alleviate this issue, various social activities should be arranged to let neighbours communicate with each other more often. For example, in my country people organize \"Sumalak\" events where neighbours prepare traditional food together, have nice conversations and do various group activities. In this way, people next door have a chance to get to know one another and build trust. In addition to this, people should create neighbourhood groups on social networks where they share common interests and discuss local issues. This would help neighbours be friendly to each other and boost mutual contact.\n\nIn conclusion, people in big cities interact less with their neighbours because of a shortage of time and frequent moves. To improve this situation, people ought to set up social events and neighbourhood chat groups on social networks to get to know and trust each other."},{"id":"t2-ps-water","unit":"w2.22","task":2,"kind":"problem","title":"Shortage of drinking water","q":"The lack of water for drinking is a problem in many countries.\nWhy do countries face water shortages?\nWhat could be done to deal with the problem?","src":"Unit 22","min":250,"sample":"In many parts of the world, people suffer from a shortage of drinking water. Water shortages are caused by growing demand for water and by pollution. The problem can be tackled by sustainable water management and proper education.\n\nWater shortages are occurring due to the rapidly growing demand for water. Over the last 50 years, the world's population has doubled and continues to grow. As a result, the use of water for drinking, cooking and other needs has increased dramatically. Another reason for water scarcity is the contamination of drinking water because of human activity and natural factors. Fertilizers, pesticides and urban sewage are polluting water and making it unfit for consumption, while natural disasters such as floods and droughts have a detrimental impact on freshwater resources.\n\nTo deal with the water problem, water resources should be managed with a focus on conservation and efficiency. In agriculture, smart irrigation technologies that help save water must be applied. For example, crops should be watered by drip irrigation, or new water-efficient plant species ought to be grown. Another solution is to educate people to raise awareness of the water crisis and of the actions that individuals can take to address it. If people know the problem is pressing, they may start to take practical actions to help the situation.\n\nIn conclusion, running out of drinking water has become a serious issue for millions of people around the globe due to the rise in demand for water and the degradation of water quality. However, we can still supply enough water for people if we improve water management and people's awareness of the issue."},{"id":"t2-tp-techrel","unit":"w2.23","task":2,"kind":"essay","title":"Technology and relationships","q":"Nowadays the way many people interact with each other has changed because of technology.\nIn what ways has technology affected the types of relationships that people make?\nHas this been a positive or negative development?","src":"Unit 23","min":250,"sample":"New technologies have indeed had an influence on communication between people. Technology has affected relationships in various ways, and in my opinion there are both positive and negative effects.\n\nTechnology has had an impact on relationships in business, education and social life. Firstly, telephones and the Internet allow business people in different countries to interact without ever meeting each other. Secondly, services like Zoom create new possibilities for relationships between students and teachers. For example, a student can now take video lessons with a teacher in a different city or country. Finally, many people use social networks, like Instagram, to make new friends and find people who share common interests, and they interact through their computers rather than face to face.\n\nOn the one hand, these developments can be extremely positive. Cooperation between people in different countries was much more difficult when communication was limited to written letters or telegrams. Nowadays, interactions by email, phone or video are almost as good as face-to-face meetings, and many of us benefit from these interactions, either in work or social contexts. On the other hand, the availability of new communication technologies can also have the result of isolating people and discouraging real interaction. For example, many young people choose to make friends online rather than mixing with their peers in the real world, and these 'virtual' relationships are a poor substitute for real friendships.\n\nIn conclusion, technology has certainly revolutionized communication between people in education, business and social life. But not all the results of this change have been positive, because it has made our communication easy, but real face-to-face interaction is being discouraged."},{"id":"t2-tp-boarding","unit":"w2.23","task":2,"kind":"essay","title":"Boarding schools are becoming popular","q":"Nowadays sending children to boarding schools is becoming increasingly popular.\nWhat are the reasons?\nDo you think it is a positive or negative development?","src":"Unit 23","min":250},{"id":"t2-tp-weddings","unit":"w2.23","task":2,"kind":"essay","title":"Bigger and more expensive weddings","q":"Marriages are bigger and more expensive nowadays than in the past.\nWhy is this the case?\nIs it a positive or negative development?","src":"Unit 23","min":250},{"id":"t2-tp-hours","unit":"w2.23","task":2,"kind":"essay","title":"Long working hours","q":"In some countries, people spend long hours at work.\nWhy does this happen?\nIs it a positive or negative development?","src":"Unit 23","min":250,"sample":"Workers tend to stay at the workplace for extended hours in many parts of the world. These people spend long hours in offices for three main reasons, and in my opinion, there are both positive and negative effects.\n\nEmployees work long hours because of the desire to earn more, inefficient technology at work and the expectations of the job. Firstly, people wish to receive a higher salary, since the more time they invest in their job, the more money they can earn. Secondly, technological advances are not applied in many jobs, so the work relies on time-consuming manual labour, and to meet their targets, workers may have to work overtime. Finally, although it is not official, in many developing countries it is a tradition for staff not to go home on time. For example, workers tend not to leave before their boss leaves the office, and as a result, they stay at work much later.\n\nOn the one hand, this is a positive trend, as people can earn higher salaries by working overtime, which is particularly important for covering living costs and investing in their children's education. On the other hand, staying at work for longer periods has an adverse effect on a worker's family. When coming home very late, many people feel exhausted and are unable to spend quality time with their family members. For instance, mothers working overtime may skip preparing healthy home-cooked food after a long day at work, which may have a negative influence on their family's long-term health.\n\nIn conclusion, people work overtime in order to get paid more, complete labour-intensive work and follow tradition. Although this may improve a worker's financial security, it may have a negative impact on their family."},{"id":"t2-tp-tourism","unit":"w2.23","task":2,"kind":"essay","title":"Developing countries expanding tourism","q":"Many developing countries are currently expanding their tourist industries.\nWhy is this the case?\nIs it a positive or negative development?","src":"Unit 23","min":250,"sample":"The expansion of tourism has become a top priority for many low-income nations these days. These countries are investing in tourism for two major reasons, and there are both positive and negative effects of developing tourism.\n\nMany governments are focusing on boosting the tourism sector since it generates national income and provides employment. When foreign visitors come, they contribute to the national economy by purchasing local products and services, which also increases tax revenue from the service sector. What's more, tourism can create thousands of jobs in developing countries. This can help governments provide employment in remote places where there are no factories but there is beautiful nature. In the Maldives, for example, tourism is the largest employer and most citizens rely on it to survive.\n\nOn the one hand, tourism can have a negative impact on the environment. To build hotels, roads and other tourist facilities, natural habitats are destroyed. Tourism also creates pollution and waste, which cause significant harm to wildlife. On the other hand, tourism can improve people's standard of living and reduce poverty. This is because it creates jobs for locals, allowing ordinary people to earn an income. As a result, people can afford basic necessities, recreation, education and better medical services.\n\nIn conclusion, the main reasons for developing countries to expand their tourist industries are to create jobs and grow their economies. Although boosting tourism raises people's quality of life, it has a harmful effect on the environment and wildlife of the country."},{"id":"wt01-2","unit":"exam","set":1,"task":2,"kind":"problem","title":"Declining numbers of animals and plants","q":"In many countries, the number of animals and plants is declining.\nWhy do you think this is happening?\nHow can this issue be solved?","src":"Writing tasks · Variant 1","min":250},{"id":"wt02-2","unit":"exam","set":2,"task":2,"kind":"adv","title":"Photographing and filming social activities","q":"Nowadays people take photographs and record videos of their social activities.\nWhy are they doing this?\nWhat are the advantages and disadvantages of this activity?","src":"Writing tasks · Variant 2","min":250},{"id":"wt03-2","unit":"exam","set":3,"task":2,"kind":"discuss","title":"Part-time jobs for teenagers","q":"Some countries allow teenagers to have a part-time job. Some people think this is a good idea, while others disagree.\nDiscuss both views and give your opinion.","src":"Writing tasks · Variant 3","min":250},{"id":"wt04-2","unit":"exam","set":4,"task":2,"kind":"discuss","title":"Cooking lessons at school","q":"Some people think that students should learn cooking at school, while others believe that this is a waste of school time.\nDiscuss both views and give your own opinion.","src":"Writing tasks · Variant 4","min":250},{"id":"wt05-2","unit":"exam","set":5,"task":2,"kind":"problem","title":"People know exercise is good but don't do it","q":"People are not exercising regularly, although they know it is beneficial for their health.\nWhy is this the case?\nWhat can be done to solve this?","src":"Writing tasks · Variant 5","min":250},{"id":"wt06-2","unit":"exam","set":6,"task":2,"kind":"discuss","title":"Are TV advertisements useful?","q":"Some people think that TV advertisements can be useful for viewers, while others disagree.\nDiscuss both views and give your opinion.","src":"Writing tasks · Variant 6","min":250},{"id":"wt07-2","unit":"exam","set":7,"task":2,"kind":"opinion","title":"Teenagers' problems and working parents","q":"Today teenagers struggle with many social issues. Some people think that this is because their parents are spending more time at work than at home.\nDo you agree or disagree?","src":"Writing tasks · Variant 7","min":250},{"id":"wt08-2","unit":"exam","set":8,"task":2,"kind":"opinion","title":"Television should mainly educate and inform","q":"Some people say that television should be mainly used to educate and inform viewers.\nDo you agree or disagree?","src":"Writing tasks · Variant 8","min":250},{"id":"wt09-2","unit":"exam","set":9,"task":2,"kind":"discuss","title":"Does technology give us more free time?","q":"Some say that modern technology is giving people more free time, while others think it is making them busier.\nDiscuss both views and give your opinion.","src":"Writing tasks · Variant 9","min":250},{"id":"wt10-2","unit":"exam","set":10,"task":2,"kind":"essay","title":"Leaders are younger than in the past","q":"These days leaders of all kinds are younger than in the past.\nWhat are the reasons?\nIs this a negative or a positive trend?","src":"Writing tasks · Variant 10","min":250},{"id":"wt11-2","unit":"exam","set":11,"task":2,"kind":"adv","title":"Shopping malls","q":"Many shopping malls have been built in different countries all over the world.\nDo the advantages of shopping malls outweigh the disadvantages?","src":"Writing tasks · Variant 11","min":250},{"id":"wt12-2","unit":"exam","set":12,"task":2,"kind":"problem","title":"Extreme and dangerous sports","q":"Some people participate in extreme and dangerous sports.\nWhy do people do these sports?\nHow could these sports be made safer?","src":"Writing tasks · Variant 12","min":250},{"id":"wt13-2","unit":"exam","set":13,"task":2,"kind":"opinion","title":"Raising petrol prices to solve traffic and pollution","q":"Increasing the price of petrol is the best way to solve growing traffic and pollution problems.\nTo what extent do you agree or disagree?","src":"Writing tasks · Variant 13","min":250},{"id":"wt14-2","unit":"exam","set":14,"task":2,"kind":"discuss","title":"Wild animals living in cities","q":"Many wild birds and animals are living in cities. Some people believe that these animals should be killed, while others think that they should be saved and protected.\nDiscuss both views and give your opinion.","src":"Writing tasks · Variant 14","min":250},{"id":"wt15-2","unit":"exam","set":15,"task":2,"kind":"adv","title":"Security cameras versus freedom","q":"In many cities, security measures, such as the use of video cameras in public places, are being increased to reduce crime, but some people believe that these measures restrict our freedom.\nDo the benefits of increased security outweigh the drawbacks?","src":"Writing tasks · Variant 15","min":250},{"id":"wt16-2","unit":"exam","set":16,"task":2,"kind":"opinion","title":"Should governments regulate technology for privacy?","q":"Some people think that the government should regulate technological developments because of people's privacy.\nTo what extent do you agree or disagree?","src":"Writing tasks · Variant 16","min":250},{"id":"wt17-2","unit":"exam","set":17,"task":2,"kind":"opinion","title":"Will newspapers disappear?","q":"As more and more people are getting their news from the Internet, newspapers and magazines will gradually disappear.\nDo you agree or disagree?","src":"Writing tasks · Variant 17","min":250},{"id":"wt18-2","unit":"exam","set":18,"task":2,"kind":"opinion","title":"Fashionable clothes","q":"Nowadays more and more people prefer to wear fashionable clothes.\nIs it a positive or negative development?","src":"Writing tasks · Variant 18","min":250},{"id":"wt19-2","unit":"exam","set":19,"task":2,"kind":"discuss","title":"Are public libraries still necessary?","q":"Some people think that public libraries are necessary. But other people believe that nowadays these libraries are no longer important.\nDiscuss both views and give your opinion.","src":"Writing tasks · Variant 19","min":250},{"id":"wt20-2","unit":"exam","set":20,"task":2,"kind":"essay","title":"Cities replacing cars with bicycles","q":"Many cities are replacing cars with bicycles.\nWhat are the reasons for this?\nWhich do you think is better?","src":"Writing tasks · Variant 20","min":250}]};
